struct WC { word: Str, count: Int }

fn bump(m: HashMap<Str, Int>, w: Str) -> HashMap<Str, Int> {
  let mut out = m;
  let n = out.get(w).unwrap_or(0);
  out.insert(w, n + 1);
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let data = input.read("text.txt")?;
  let mut counts: HashMap<Str, Int> = HashMap::new();
  let mut cur: Bytes = "".to_bytes();
  for b in data {
    if b >= 65 && b <= 90 {
      cur.push(b + 32);
    } else if b >= 97 && b <= 122 {
      cur.push(b);
    } else if cur.len() > 0 {
      counts = bump(counts, cur.to_str());
      cur = "".to_bytes();
    }
  }
  if cur.len() > 0 {
    counts = bump(counts, cur.to_str());
  }
  let mut items: List<WC> = [];
  for k in counts.keys() {
    items.push(WC { word: k, count: counts.get(k).unwrap_or(0) });
  }
  items.sort_by(|a: WC, b: WC| {
    if a.count != b.count { a.count > b.count } else { a.word < b.word }
  });
  let mut lines: List<Str> = [];
  let n = items.len().min(5);
  for i in 0..n {
    lines.push(items[i].word + " " + items[i].count.to_str());
  }
  Ok(lines.join("\n"))
}

struct WC { w: Str, c: Int }

fn count_words(text: Bytes) -> HashMap<Str, Int> {
  let mut counts: HashMap<Str, Int> = HashMap::new();
  let mut cur = "".to_bytes();
  for b in text {
    let mut is_letter = false;
    let mut lb = b;
    if b >= 65 && b <= 90 {
      is_letter = true;
      lb = b + 32;
    } else if b >= 97 && b <= 122 {
      is_letter = true;
    }
    if is_letter {
      cur.push(lb);
    } else if cur.len() > 0 {
      let w = cur.to_str();
      counts.insert(w, counts.get(w).unwrap_or(0) + 1);
      cur = "".to_bytes();
    }
  }
  if cur.len() > 0 {
    let w = cur.to_str();
    counts.insert(w, counts.get(w).unwrap_or(0) + 1);
  }
  counts
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("text.txt")?;
  let counts = count_words(text);
  let mut items: List<WC> = [];
  for k in counts.keys() {
    items.push(WC { w: k, c: counts.get(k).unwrap_or(0) });
  }
  items.sort_by(|a: WC, b: WC| a.c > b.c || (a.c == b.c && a.w < b.w));
  let n = items.len().min(5);
  let mut lines: List<Str> = [];
  for i in 0..n {
    lines.push(items[i].w + " " + items[i].c.to_str());
  }
  Ok(lines.join("\n"))
}

struct W { word: Str, count: Int }

fn is_letter(b: Int) -> Bool {
  (b >= 65 && b <= 90) || (b >= 97 && b <= 122)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let data = input.read("text.txt")?;
  let mut counts: HashMap<Str, Int> = HashMap::new();
  let mut cur: Bytes = "".to_bytes();
  for b in data {
    if is_letter(b) {
      let mut c = b;
      if c >= 65 && c <= 90 { c = c + 32; }
      cur.push(c);
    } else {
      if cur.len() > 0 {
        let w = cur.to_str();
        counts.insert(w, counts.get(w).unwrap_or(0) + 1);
        cur = "".to_bytes();
      }
    }
  }
  if cur.len() > 0 {
    let w = cur.to_str();
    counts.insert(w, counts.get(w).unwrap_or(0) + 1);
  }
  let mut ws: List<W> = [];
  for k in counts.keys() {
    ws.push(W { word: k, count: counts.get(k).unwrap_or(0) });
  }
  ws.sort_by(|a: W, b: W| a.count > b.count || (a.count == b.count && a.word < b.word));
  let n = ws.len().min(5);
  let mut lines: List<Str> = [];
  for i in 0..n {
    lines.push(ws[i].word + " " + ws[i].count.to_str());
  }
  Ok(lines.join("\n"))
}

struct Agg { region: Str, qty: Int, rev: Int }

fn money(c: Int) -> Str {
  let neg = c < 0;
  let a = if neg { -c } else { c };
  let d = a / 100;
  let r = a % 100;
  let rs = if r < 10 { "0" + r.to_str() } else { r.to_str() };
  let s = d.to_str() + "." + rs;
  if neg { "-" + s } else { s }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let lines = text.lines();
  let mut m: Map<Str, Agg> = Map::new();
  let mut skipped = 0;
  for i in 0..lines.len() {
    if i == 0 { continue; }
    let line = lines[i];
    if line.trim() == "" { continue; }
    let parts = line.split(",");
    if parts.len() != 5 { skipped += 1; continue; }
    let region = parts[1].trim();
    let Some(q) = parts[3].trim().parse_int() else { skipped += 1; continue; };
    let Some(u) = parts[4].trim().parse_int() else { skipped += 1; continue; };
    let cur = m.get(region).unwrap_or(Agg { region: region, qty: 0, rev: 0 });
    m.insert(region, Agg { region: region, qty: cur.qty + q, rev: cur.rev + q * u });
  }
  let mut rows: List<Agg> = [];
  for k in m.keys() {
    if let Some(a) = m.get(k) { rows.push(a); }
  }
  rows.sort_by(|a, b| a.rev > b.rev || (a.rev == b.rev && a.region < b.region));
  let mut out: List<Str> = [];
  for r in rows {
    out.push(r.region + " " + r.qty.to_str() + " " + money(r.rev));
  }
  out.push("skipped " + skipped.to_str());
  Ok(out.join("\n"))
}

