struct Entry { ip: Str, path: Str, status: Int, size: Int }

struct IpCount { ip: Str, count: Int }

fn parse(line: Str) -> Option<Entry> {
  let q = line.find("\"")?;
  let head = line.slice(0, q);
  let head_parts = head.split(" ");
  let ip = head_parts[0];
  if ip.len() == 0 { return None; }
  if !head.contains("[") { return None; }
  let rest = line.slice(q + 1, line.len());
  let q2 = rest.find("\"")?;
  let req = rest.slice(0, q2);
  let words = req.split(" ");
  if words.len() != 3 { return None; }
  let mut path = words[1];
  if let Some(i) = path.find("?") { path = path.slice(0, i); }
  if path.len() == 0 { return None; }
  let tail = rest.slice(q2 + 1, rest.len()).trim();
  let tp = tail.split(" ");
  if tp.len() != 2 { return None; }
  let status = tp[0].parse_int()?;
  if status < 100 || status > 599 { return None; }
  let size = if tp[1] == "-" { 0 } else { tp[1].parse_int()? };
  if size < 0 { return None; }
  Some(Entry { ip: ip, path: path, status: status, size: size })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total = 0;
  for line in text.lines() {
    let Some(e) = parse(line) else { continue; };
    statuses.insert(e.status, statuses.get(e.status).unwrap_or(0) + 1);
    paths.insert(e.path, paths.get(e.path).unwrap_or(0) + 1);
    total = total + e.size;
    if e.status >= 500 && e.status <= 599 {
      errs.insert(e.ip, errs.get(e.ip).unwrap_or(0) + 1);
    }
  }
  let mut out: List<Str> = [];
  for s in statuses.keys() {
    out.push(s.to_str() + " " + statuses.get(s).unwrap_or(0).to_str());
  }
  out.push("bytes " + total.to_str());
  let mut best = "";
  let mut best_n = 0;
  for p in paths.keys() {
    let n = paths.get(p).unwrap_or(0);
    if n > best_n { best = p; best_n = n; }
  }
  if best_n > 0 {
    out.push("top " + best + " " + best_n.to_str());
  }
  let mut ips: List<IpCount> = [];
  for ip in errs.keys() {
    ips.push(IpCount { ip: ip, count: errs.get(ip).unwrap_or(0) });
  }
  ips.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.ip < b.ip));
  for c in ips {
    out.push("errors " + c.ip + " " + c.count.to_str());
  }
  Ok(out.join("\n"))
}

