  if size < 0 { return None; }
  Some(Entry { ip: ip, path: path, status: status, size: size })
}

fn bump_int(m: Map<Int, Int>, k: Int) -> Map<Int, Int> {
  let mut m2 = m;
  m2.insert(k, m.get(k).unwrap_or(0) + 1);
  m2
}

fn bump_str(m: Map<Str, Int>, k: Str) -> Map<Str, Int> {
  let mut m2 = m;
  m2.insert(k, m.get(k).unwrap_or(0) + 1);
  m2
}

fn main(input: Dir) -> Result<Str, IoErr> {
