struct Entry { ip: Str, path: Str, status: Int, size: Int }

fn parse_line(line: Str) -> Option<Entry> {
  let q1 = line.find("\"")?;
  let prefix = line.slice(0, q1);
  let rest = line.slice(q1 + 1, line.len());
  let q2 = rest.find("\"")?;
  let request = rest.slice(0, q2);
  let tail = rest.slice(q2 + 1, rest.len()).trim();

  if !prefix.contains("[") || !prefix.contains("]") { return None; }
  let pparts = prefix.trim().split(" ");
  if pparts.len() < 4 { return None; }
  let ip = pparts[0];
  if ip.len() == 0 { return None; }

  let rparts = request.split(" ");
  if rparts.len() != 3 { return None; }
  let mut path = rparts[1];
  if path.len() == 0 { return None; }
  if let Some(i) = path.find("?") { path = path.slice(0, i); }

  let tparts = tail.split(" ");
  if tparts.len() != 2 { return None; }
  let status = tparts[0].parse_int()?;
  if status < 100 || status > 599 { return None; }
  let size = if tparts[1] == "-" { 0 } else { tparts[1].parse_int()? };
  if size < 0 { return None; }

  Some(Entry { ip: ip, path: path, status: status, size: size })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errors: Map<Str, Int> = Map::new();
  let mut total = 0;

  for line in text.lines() {
    let Some(e) = parse_line(line) else { continue; };
    statuses.insert(e.status, statuses.get(e.status).unwrap_or(0) + 1);
    paths.insert(e.path, paths.get(e.path).unwrap_or(0) + 1);
    total = total + e.size;
    if e.status >= 500 && e.status <= 599 {
      errors.insert(e.ip, errors.get(e.ip).unwrap_or(0) + 1);
    }
  }

  let mut out: List<Str> = [];
  for s in statuses.keys() {
    out.push(s.to_str() + " " + statuses.get(s).unwrap_or(0).to_str());
  }
  out.push("bytes " + total.to_str());

  let mut best_path = "";
  let mut best_count = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > best_count {
      best_count = c;
      best_path = p;
    }
  }
  if best_count > 0 {
    out.push("top " + best_path + " " + best_count.to_str());
  }

  let mut ips = errors.keys();
  let counts = errors;
  ips.sort_by(|a, b| {
    let ca = counts.get(a).unwrap_or(0);
    let cb = counts.get(b).unwrap_or(0);
    ca > cb || (ca == cb && a < b)
  });
  for ip in ips {
    out.push("errors " + ip + " " + errors.get(ip).unwrap_or(0).to_str());
  }

  Ok(out.join("\n"))
}

struct Agg { n: Int, total: Int }

fn order_total(o: Json) -> Int {
  let items = o.get("items").and_then(|j| j.as_list()).unwrap_or([]);
  let mut t = 0;
  for it in items {
    let q = it.get("qty").and_then(|j| j.as_int()).unwrap_or(0);
    let p = it.get("price_cents").and_then(|j| j.as_int()).unwrap_or(0);
    t = t + q * p;
  }
  t
}

fn main(input: Dir) -> Result<Str, Str> {
  let bytes = input.read("orders.json").map_err(|e| "cannot read orders.json")?;
  let doc = bytes.to_str().parse_json()?;
  let orders = doc.as_list().unwrap_or([]);
  let mut paid: Map<Str, Agg> = Map::new();
  let mut ref_n = 0;
  let mut ref_total = 0;
  let mut pend_n = 0;
  for o in orders {
    let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
    let customer = o.get("customer").and_then(|j| j.as_str()).unwrap_or("");
    let t = order_total(o);
    if status == "paid" {
      let cur = paid.get(customer).unwrap_or(Agg { n: 0, total: 0 });
      paid.insert(customer, Agg { n: cur.n + 1, total: cur.total + t });
    } else if status == "refunded" {
      ref_n = ref_n + 1;
      ref_total = ref_total + t;
    } else if status == "pending" {
      pend_n = pend_n + 1;
    }
  }
  let mut lines: List<Str> = [];
  for c in paid.keys() {
    let a = paid.get(c).unwrap_or(Agg { n: 0, total: 0 });
    lines.push(c + " " + a.n.to_str() + " " + a.total.to_str());
  }
  lines.push("refunded " + ref_n.to_str() + " " + ref_total.to_str());
  lines.push("pending " + pend_n.to_str());
  Ok(lines.join("\n"))
}

struct Agg { n: Int, total: Int }

fn order_total(o: Json) -> Int {
  let items = o.get("items").and_then(|j| j.as_list()).unwrap_or([]);
  let mut sum = 0;
  for it in items {
    let qty = it.get("qty").and_then(|j| j.as_int()).unwrap_or(0);
