fn to_roman(n: Int) -> Str {
  let vals = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  let syms = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let mut out = "";
  let mut rest = n;
  for i in 0..vals.len() {
    while rest >= vals[i] {
      out = out + syms[i];
      rest = rest - vals[i];
    }
  }
  out
}

fn digit(c: Str) -> Option<Int> {
  match c {
    "I" => Some(1),
    "V" => Some(5),
    "X" => Some(10),
    "L" => Some(50),
    "C" => Some(100),
    "D" => Some(500),
    "M" => Some(1000),
    _ => None,
  }
}

fn from_roman(s: Str) -> Option<Int> {
  let cs = s.chars();
  if cs.len() == 0 { return None; }
  let mut ds: List<Int> = [];
  for c in cs {
    ds.push(digit(c)?);
  }
  let mut sum = 0;
  for i in 0..ds.len() {
    if i + 1 < ds.len() && ds[i + 1] > ds[i] {
      sum = sum - ds[i];
    } else {
      sum = sum + ds[i];
    }
  }
  if sum < 1 || sum > 3999 { return None; }
  if to_roman(sum) == s { Some(sum) } else { None }
}

fn convert(s: Str) -> Str {
  if let Some(n) = s.parse_int() {
    if n >= 1 && n <= 3999 { return to_roman(n); }
    return "invalid";
  }
  match from_roman(s) {
    Some(n) => n.to_str(),
    None => "invalid",
  }
}

