}

fn from_roman(s: Str) -> Option<Int> {
  if s.len() == 0 || s.len() > 15 {
    return None;
  }
  let cs = s.chars();
  let mut total = 0;
  for i in 0..cs.len() {
    let v = digit(cs[i]);
    if v == 0 {
      return None;
    }
    let next = if i + 1 < cs.len() { digit(cs[i + 1]) } else { 0 };
    if v < next {
      total -= v;
    } else {
      total += v;
    }
  }
  if total < 1 || total > 3999 {
    return None;
  }
  if to_roman(total) != s {
    return None;
  }
  Some(total)
}

