fn check(line: Str) -> Str {
  let mut stack: List<Str> = [];
  let mut col = 0;
  for c in line.chars() {
    col = col + 1;
    if c == "(" {
      stack.push(")");
    } else if c == "[" {
      stack.push("]");
    } else if c == "{" {
      stack.push("}");
    } else if c == ")" || c == "]" || c == "}" {
      match stack.pop() {
        None => { return "col " + col.to_str() + ": unexpected " + c; }
        Some(want) => {
          if want != c {
            return "col " + col.to_str() + ": expected " + want + ", found " + c;
          }
        }
      }
    }
  }
  match stack.pop() {
    None => "ok",
    Some(want) => "unclosed " + want,
  }
}

