fn add_edge(adj: Map<Str, Map<Str, Int>>, a: Str, b: Str, w: Int) -> Map<Str, Map<Str, Int>> {
  let mut out = adj;
  let mut nb: Map<Str, Int> = Map::new();
  match out.get(a) {
    Some(m) => { nb = m; }
    None => {}
  }
  match nb.get(b) {
    Some(old) => {
      if w < old { nb.insert(b, w); }
    }
    None => { nb.insert(b, w); }
  }
  out.insert(a, nb);
  out
}

fn neighbors(adj: Map<Str, Map<Str, Int>>, u: Str) -> Map<Str, Int> {
  match adj.get(u) {
    Some(m) => m,
    None => Map::new(),
  }
}

fn dijkstra(adj: Map<Str, Map<Str, Int>>, src: Str) -> Map<Str, Int> {
  let mut dist: Map<Str, Int> = Map::new();
  dist.insert(src, 0);
  let mut done: Map<Str, Bool> = Map::new();
  loop {
    let mut best: Option<Str> = None;
    let mut bd = 0;
    for k in dist.keys() {
      if done.get(k).is_none() {
        let d = dist.get(k).unwrap_or(0);
        if best.is_none() || d < bd {
          best = Some(k);
          bd = d;
        }
      }
    }
    let Some(u) = best else { break; };
    done.insert(u, true);
    let nb = neighbors(adj, u);
    for v in nb.keys() {
      let w = nb.get(v).unwrap_or(0);
      let nd = bd + w;
      match dist.get(v) {
        Some(old) => {
          if nd < old { dist.insert(v, nd); }
        }
        None => { dist.insert(v, nd); }
      }
    }
  }
  dist
}

fn plan(adj: Map<Str, Map<Str, Int>>, x: Str, y: Str) -> Str {
  if x == y {
    return x + " 0";
  }
  let dist = dijkstra(adj, y);
  let Some(total) = dist.get(x) else { return x + " " + y + " unreachable"; };
  let mut path: List<Str> = [x];
  let mut cur = x;
  while cur != y {
    let dc = dist.get(cur).unwrap_or(0);
    let nb = neighbors(adj, cur);
    let mut next: Option<Str> = None;
    for v in nb.keys() {
      if next.is_none() {
        let w = nb.get(v).unwrap_or(0);
        if let Some(dv) = dist.get(v) {
          if dv + w == dc {
            next = Some(v);
          }
        }
      }
    }
    let Some(n) = next else { return x + " " + y + " unreachable"; };
    path.push(n);
    cur = n;
  }
  path.join(" -> ") + " " + total.to_str()
}

