    if parts.len() == 4 && parts[0] == "road" {
      let Some(w) = parts[3].parse_int() else { continue; };
      adj = add_edge(adj, parts[1], parts[2], w);
      adj = add_edge(adj, parts[2], parts[1], w);
    } else if parts.len() == 3 && parts[0] == "trip" {
      trips.push([parts[1], parts[2]]);
    }
  }
  let mut out: List<Str> = [];
  for t in trips {
    out.push(plan(adj, t[0], t[1]));
  }
  Ok(out.join("\n"))
}

struct Edge { to: Str, cost: Int }

fn words(line: Str) -> List<Str> {
  let mut out: List<Str> = [];
  for p in line.split(" ") {
    let t = p.trim();
    if t.len() > 0 { out.push(t); }
  }
  out
}

fn add_edge(adj: Map<Str, List<Edge>>, a: Str, b: Str, c: Int) -> Map<Str, List<Edge>> {
  let mut m = adj;
  let empty: List<Edge> = [];
  let mut l = m.get(a).unwrap_or(empty);
  l.push(Edge { to: b, cost: c });
  m.insert(a, l);
  m
}

fn dists(adj: Map<Str, List<Edge>>, src: Str) -> Map<Str, Int> {
  let mut dist: Map<Str, Int> = Map::new();
  let mut done: Map<Str, Bool> = Map::new();
  dist.insert(src, 0);
  loop {
    let mut best: Option<Str> = None;
    let mut bd = 0;
    for k in dist.keys() {
      if done.get(k).is_some() { continue; }
      let dk = dist.get(k).unwrap_or(0);
      if best.is_none() || dk < bd {
        best = Some(k);
        bd = dk;
      }
    }
    let Some(u) = best else { break; };
    done.insert(u, true);
    let empty: List<Edge> = [];
    for e in adj.get(u).unwrap_or(empty) {
      let nd = bd + e.cost;
      let better = match dist.get(e.to) {
        None => true,
        Some(old) => nd < old,
      };
      if better && done.get(e.to).is_none() { dist.insert(e.to, nd); }
    }
  }
  dist
}

fn plan(adj: Map<Str, List<Edge>>, x: Str, y: Str) -> Str {
  if x == y { return x + " 0"; }
  let d = dists(adj, y);
  let Some(total) = d.get(x) else { return x + " " + y + " unreachable"; };
  let mut path: List<Str> = [x];
  let mut cur = x;
  while cur != y {
    let dc = d.get(cur).unwrap_or(0);
    let mut best: Option<Str> = None;
    let empty: List<Edge> = [];
    for e in adj.get(cur).unwrap_or(empty) {
      if let Some(dv) = d.get(e.to) {
        if dv + e.cost == dc {
          let take = match best {
            None => true,
            Some(b) => e.to < b,
          };
          if take { best = Some(e.to); }
        }
      }
    }
    let Some(n) = best else { break; };
    path.push(n);
    cur = n;
  }
  path.join(" -> ") + " " + total.to_str()
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut adj: Map<Str, List<Edge>> = Map::new();
  let mut trips: List<List<Str>> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 || line.starts_with("#") { continue; }
    let w = words(line);
    if w.len() == 4 && w[0] == "road" {
      let Some(c) = w[3].parse_int() else { continue; };
      adj = add_edge(adj, w[1], w[2], c);
      adj = add_edge(adj, w[2], w[1], c);
    } else if w.len() == 3 && w[0] == "trip" {
      trips.push([w[1], w[2]]);
    }
  }
  let mut out: List<Str> = [];
  for t in trips {
    out.push(plan(adj, t[0], t[1]));
  }
  Ok(out.join("\n"))
}

fn add_road(adj: HashMap<Str, Map<Str, Int>>, a: Str, b: Str, c: Int) -> HashMap<Str, Map<Str, Int>> {
  let mut m = adj;
  let mut na: Map<Str, Int> = m.get(a).unwrap_or(Map::new());
  let mut put = true;
  if let Some(old) = na.get(b) {
    if old <= c { put = false; }
  }
  if put { na.insert(b, c); }
  m.insert(a, na);
  m
}

fn dijkstra(adj: HashMap<Str, Map<Str, Int>>, src: Str) -> HashMap<Str, Int> {
  let mut dist: HashMap<Str, Int> = HashMap::new();
  dist.insert(src, 0);
  let mut done: HashMap<Str, Bool> = HashMap::new();
  loop {
    let mut best: Option<Str> = None;
    let mut bd = 0;
    for k in dist.keys() {
      if done.get(k).is_none() {
        let d = dist.get(k).unwrap_or(0);
        if best.is_none() || d < bd {
          best = Some(k);
          bd = d;
        }
      }
    }
    let Some(u) = best else { break; };
    done.insert(u, true);
    let nb: Map<Str, Int> = adj.get(u).unwrap_or(Map::new());
    for v in nb.keys() {
      let c = nb.get(v).unwrap_or(0);
      let nd = bd + c;
      if let Some(old) = dist.get(v) {
        if nd < old { dist.insert(v, nd); }
      } else {
        dist.insert(v, nd);
      }
    }
  }
  dist
}

fn plan(adj: HashMap<Str, Map<Str, Int>>, x: Str, y: Str) -> Str {
  if x == y { return x + " 0"; }
  let dist = dijkstra(adj, y);
  let Some(total) = dist.get(x) else { return x + " " + y + " unreachable"; };
  let mut parts: List<Str> = [x];
  let mut cur = x;
  while cur != y {
    let dc = dist.get(cur).unwrap_or(0);
    let nb: Map<Str, Int> = adj.get(cur).unwrap_or(Map::new());
    let mut next: Option<Str> = None;
    for v in nb.keys() {
      if let Some(dv) = dist.get(v) {
        if nb.get(v).unwrap_or(0) + dv == dc {
          next = Some(v);
          break;
        }
      }
    }
    let Some(n) = next else { return x + " " + y + " unreachable"; };
    parts.push(n);
    cur = n;
  }
  parts.join(" -> ") + " " + total.to_str()
}

struct Trip { from: Str, to: Str }

fn main(input: Dir) -> Result<Str, IoErr> {
