    } else if w[0] == "trip" && w.len() == 3 {
      trips.push(Trip { from: w[1], to: w[2] });
    }
  }
  let mut out: List<Str> = [];
  for t in trips {
    out.push(plan(adj, t.from, t.to));
  }
  Ok(out.join("\n"))
}

struct Leaf { path: Str, val: Str }

fn merge(base: Json, ov: Json) -> Json {
  match ov {
    Json::Obj(om) => {
      let mut res: Map<Str, Json> = match base {
        Json::Obj(bm) => bm,
        _ => Map::new(),
      };
      for k in om.keys() {
        let Some(v) = om.get(k) else { continue; };
        if v == Json::Null {
          res.remove(k);
        } else {
          let b = res.get(k).unwrap_or(Json::Null);
          res.insert(k, merge(b, v));
        }
      }
      Json::Obj(res)
    }
    other => other,
  }
}

fn join_path(prefix: Str, k: Str) -> Str {
  if prefix.len() == 0 { k } else { prefix + "." + k }
}

fn flatten(prefix: Str, j: Json, out: List<Leaf>) -> List<Leaf> {
  let mut acc = out;
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        acc.push(Leaf { path: prefix, val: "{}" });
      } else {
        for k in m.keys() {
          let Some(v) = m.get(k) else { continue; };
          acc = flatten(join_path(prefix, k), v, acc);
        }
      }
    }
    Json::Arr(xs) => {
      if xs.len() == 0 {
        acc.push(Leaf { path: prefix, val: "[]" });
      } else {
        for i in 0..xs.len() {
          acc = flatten(join_path(prefix, i.to_str()), xs[i], acc);
        }
      }
    }
    other => {
      acc.push(Leaf { path: prefix, val: other.to_json() });
    }
  }
  acc
}

fn load(input: Dir, name: Str) -> Result<Json, Str> {
  let bytes = input.read(name).map_err(|e| "cannot read " + name)?;
  let text = bytes.to_str();
  text.parse_json()
}

fn main(input: Dir) -> Result<Str, Str> {
  let base = load(input, "base.json")?;
  let ov = load(input, "override.json")?;
  let merged = merge(base, ov);
  let empty: List<Leaf> = [];
  let mut leaves = flatten("", merged, empty);
  leaves.sort_by_key(|l| l.path);
  let lines = leaves.map(|l| l.path + "=" + l.val);
  Ok(lines.join("\n"))
}

struct Leaf { path: Str, value: Str }

fn merge(b: Map<Str, Json>, o: Map<Str, Json>) -> Map<Str, Json> {
  let mut out = b;
  for k in o.keys() {
    let Some(v) = o.get(k) else { continue; };
    match v {
      Json::Null => out.remove(k),
      Json::Obj(om) => {
        let base: Map<Str, Json> = match out.get(k) {
          Some(Json::Obj(bm)) => bm,
          _ => Map::new(),
        };
        out.insert(k, Json::Obj(merge(base, om)));
      }
      other => out.insert(k, other),
    }
  }
  out
}

fn join(prefix: Str, key: Str) -> Str {
  if prefix == "" { key } else { prefix + "." + key }
}

fn flat(path: Str, j: Json, acc: List<Leaf>) -> List<Leaf> {
  let mut out = acc;
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        out.push(Leaf { path: path, value: "{}" });
      } else {
        for k in m.keys() {
          let Some(v) = m.get(k) else { continue; };
          out = flat(join(path, k), v, out);
        }
      }
    }
    Json::Arr(xs) => {
      if xs.len() == 0 {
        out.push(Leaf { path: path, value: "[]" });
      } else {
        for i in 0..xs.len() {
          out = flat(join(path, i.to_str()), xs[i], out);
        }
      }
    }
    other => out.push(Leaf { path: path, value: other.to_json() }),
  }
  out
}

fn load(d: Dir, name: Str) -> Result<Map<Str, Json>, Str> {
  let bytes = match d.read(name) {
    Ok(b) => b,
    Err(_) => { return Err("cannot read " + name); }
  };
  let j = bytes.to_str().parse_json()?;
  match j {
    Json::Obj(m) => Ok(m),
    _ => Err(name + " is not a JSON object"),
  }
}

fn main(input: Dir) -> Result<Str, Str> {
  let base = load(input, "base.json")?;
  let over = load(input, "override.json")?;
  let merged = merge(base, over);
  let mut leaves: List<Leaf> = [];
  for k in merged.keys() {
    let Some(v) = merged.get(k) else { continue; };
    leaves = flat(k, v, leaves);
  }
  leaves.sort_by(|a: Leaf, b: Leaf| a.path < b.path);
  let lines = leaves.map(|l| l.path + "=" + l.value);
  Ok(lines.join("\n"))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("app.log")?.to_str();
  let mut err = "";
  let mut warn = "";
  let mut info = "";
  let mut ne = 0;
  let mut nw = 0;
  let mut ni = 0;
  let mut no = 0;
  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    let fields = line.split(" ").filter(|f| f.len() > 0);
    if fields.len() < 3 { no += 1; continue; }
    let level = fields[1].to_uppercase();
    match level {
      "ERROR" => { err = err + line + "\n"; ne += 1; }
      "WARN" | "WARNING" => { warn = warn + line + "\n"; nw += 1; }
      "INFO" => { info = info + line + "\n"; ni += 1; }
      _ => { no += 1; }
    }
  }
  out.write("error.log", err.to_bytes())?;
  out.write("warn.log", warn.to_bytes())?;
  out.write("info.log", info.to_bytes())?;
  Ok("error " + ne.to_str() + "\nwarn " + nw.to_str() + "\ninfo " + ni.to_str() + "\nother " + no.to_str())
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
