fn walk(d: Dir, dir: Str, acc: List<Str>) -> Result<List<Str>, IoErr> {
  let mut files = acc;
  let names = d.list(dir)?;
  for name in names {
    let full = if dir == "" { name } else { dir + "/" + name };
    if let Some(sub) = full.strip_suffix("/") {
      files = walk(d, sub, files)?;
    } else {
      files.push(full);
    }
  }
  Ok(files)
}

fn count_lines(b: Bytes) -> Int {
  let mut n = 0;
  for x in b {
    if x == 10 { n += 1; }
  }
  if b.len() > 0 && b[b.len() - 1] != 10 { n += 1; }
  n
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let empty: List<Str> = [];
  let mut files = walk(input, "", empty)?;
  files.sort();
  let mut csv = "path,bytes,lines\n";
  let mut total = 0;
  let mut count = 0;
  for f in files {
    let b = input.read(f)?;
    let size = b.len();
    total += size;
    count += 1;
    csv = csv + f + "," + size.to_str() + "," + count_lines(b).to_str() + "\n";
  }
  out.create("index.csv", csv.to_bytes())?;
  Ok("files " + count.to_str() + " bytes " + total.to_str())
}

fn parse_csv(line: Str) -> List<Str> {
  let cs = line.chars();
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut inq = false;
  let mut i = 0;
  while i < cs.len() {
    let c = cs[i];
    if inq {
      if c == "\"" {
        if i + 1 < cs.len() && cs[i + 1] == "\"" {
          cur = cur + "\"";
          i += 2;
          continue;
        }
        inq = false;
      } else {
        cur = cur + c;
      }
    } else if c == "\"" {
      inq = true;
    } else if c == "," {
      fields.push(cur);
      cur = "";
    } else {
      cur = cur + c;
    }
    i += 1;
  }
  fields.push(cur);
  fields
}

fn to_row(f: List<Str>) -> Option<Json> {
  if f.len() != 5 { return None; }
  let id = f[0].trim().parse_int()?;
  let act = f[3].trim().to_lowercase();
  let active = act == "yes" || act == "true" || act == "1";
  let mut tags: List<Json> = [];
  for t in f[4].split(";") {
    let tt = t.trim();
    if tt.len() > 0 { tags.push(Json::Str(tt)); }
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  m.insert("name", Json::Str(f[1]));
  m.insert("email", Json::Str(f[2]));
  m.insert("active", Json::Bool(active));
  m.insert("tags", Json::Arr(tags));
  Some(Json::Obj(m))
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("users.csv")?.to_str();
  let mut rows: List<Json> = [];
  let mut skipped = 0;
  let mut first = true;
  for raw in text.lines() {
    let line = raw.strip_suffix("\r").unwrap_or(raw);
    if line.trim().len() == 0 { continue; }
    if first { first = false; continue; }
    match to_row(parse_csv(line)) {
      Some(j) => rows.push(j),
      None => skipped += 1,
    }
  }
  let n = rows.len();
  out.write("users.json", Json::Arr(rows).to_json().to_bytes())?;
  Ok("rows " + n.to_str() + " skipped " + skipped.to_str())
}

fn parse_fields(line: Str) -> List<Str> {
  let cs = line.chars();
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut in_quotes = false;
  let mut at_start = true;
  let mut i = 0;
  let n = cs.len();
  while i < n {
    let c = cs[i];
    if in_quotes {
      if c == "\"" {
        if i + 1 < n && cs[i + 1] == "\"" {
          cur = cur + "\"";
          i = i + 1;
        } else {
          in_quotes = false;
        }
      } else {
        cur = cur + c;
      }
    } else {
      if c == "," {
        fields.push(cur);
        cur = "";
        at_start = true;
        i = i + 1;
        continue;
      } else if c == "\"" && at_start {
        in_quotes = true;
      } else {
        cur = cur + c;
      }
    }
    at_start = false;
    i = i + 1;
  }
  fields.push(cur);
  fields
}

fn is_active(s: Str) -> Bool {
  let v = s.trim().to_lowercase();
  v == "yes" || v == "true" || v == "1"
}

fn parse_tags(s: Str) -> List<Json> {
  let mut out: List<Json> = [];
  for part in s.split(";") {
    let t = part.trim();
    if t.len() > 0 {
      out.push(Json::Str(t));
    }
  }
  out
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("users.csv")?.to_str();
  let mut rows: List<Json> = [];
  let mut skipped = 0;
  let mut header_seen = false;
  for raw in text.lines() {
    let line = match raw.strip_suffix("\r") {
      Some(s) => s,
      None => raw,
    };
    if line.trim().len() == 0 {
      continue;
    }
    if !header_seen {
      header_seen = true;
      continue;
    }
    let f = parse_fields(line);
    if f.len() != 5 {
      skipped += 1;
      continue;
    }
    let Some(id) = f[0].trim().parse_int() else {
      skipped += 1;
      continue;
    };
    let mut obj: Map<Str, Json> = Map::new();
    obj.insert("id", Json::Num(id));
    obj.insert("name", Json::Str(f[1]));
    obj.insert("email", Json::Str(f[2]));
    obj.insert("active", Json::Bool(is_active(f[3])));
    obj.insert("tags", Json::Arr(parse_tags(f[4])));
    rows.push(Json::Obj(obj));
  }
  let count = rows.len();
  let doc = Json::Arr(rows).to_json();
  out.create("users.json", doc.to_bytes())?;
  Ok("rows " + count.to_str() + " skipped " + skipped.to_str())
}

fn parse_fields(line: Str) -> List<Str> {
  let cs = line.chars();
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut in_quotes = false;
  let mut started_quoted = false;
  let mut i = 0;
  while i < cs.len() {
    let c = cs[i];
    if in_quotes {
      if c == "\"" {
        if i + 1 < cs.len() && cs[i + 1] == "\"" {
          cur = cur + "\"";
          i += 1;
        } else {
          in_quotes = false;
        }
      } else {
        cur = cur + c;
      }
    } else {
      if c == "," {
        fields.push(cur);
        cur = "";
        started_quoted = false;
      } else if c == "\"" && cur.len() == 0 && !started_quoted {
        in_quotes = true;
        started_quoted = true;
      } else {
        cur = cur + c;
      }
    }
    i += 1;
  }
  fields.push(cur);
  fields
}

fn parse_active(s: Str) -> Bool {
