}

fn is_keep(c: Str) -> Bool {
  (c >= "a" && c <= "z" && c.len() == 1) || (c >= "0" && c <= "9" && c.len() == 1) || c == "."
}

fn normalize(name: Str) -> Str {
  let lower = name.to_lowercase();
  let mut s = "";
  let mut in_run = false;
  for c in lower.chars() {
    if is_keep(c) {
      s = s + c;
      in_run = false;
    } else {
      if !in_run {
        s = s + "-";
        in_run = true;
      }
    }
  }
  let mut r = s;
  loop {
    let Some(t) = r.strip_prefix("-") else { break; };
    r = t;
  }
  loop {
    let Some(t) = r.strip_suffix("-") else { break; };
    r = t;
  }
  r
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let mut names = input.list("")?;
  names.sort();
  let mut taken: HashMap<Str, Bool> = HashMap::new();
  let mut lines: List<Str> = [];
  for name in names {
    if name.ends_with("/") { continue; }
    let n = normalize(name);
    if n.len() == 0 || taken.get(n).is_some() {
      lines.push(name + " skipped");
      continue;
    }
    taken.insert(n, true);
    let data = input.read(name)?;
    out.create(n, data)?;
    lines.push(name + " -> " + n);
  }
  Ok(lines.join("\n"))
}

fn is_part(name: Str) -> Bool {
  let Some(rest) = name.strip_prefix("part-") else { return false; };
  let Some(mid) = rest.strip_suffix(".txt") else { return false; };
  if mid.len() == 0 { return false; }
  for c in mid.chars() {
    if !"0123456789".contains(c) { return false; }
  }
  true
}

fn parse_part(text: Str) -> Option<List<Int>> {
  let mut vals: List<Int> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    let Some(n) = t.parse_int() else { return None; };
    vals.push(n);
  }
  Some(vals)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut parts = 0;
  let mut corrupt = 0;
  let mut seen: Map<Int, Bool> = Map::new();
  for name in names {
    if !is_part(name) { continue; }
    parts += 1;
    let bytes = input.read(name)?;
    let text = bytes.to_str();
    match parse_part(text) {
      Some(vals) => {
        for v in vals { seen.insert(v, true); }
      }
      None => corrupt += 1,
    }
  }
  let mut body = "";
  let keys = seen.keys();
  for k in keys {
    body = body + k.to_str() + "\n";
  }
  out.create("merged.txt", body.to_bytes())?;
  Ok("parts " + parts.to_str() + " corrupt " + corrupt.to_str() + " values " + keys.len().to_str())
}

fn main(src: Dir, dst: Dir) -> Result<Str, IoErr> {
  let mut src_names = src.list("")?;
  src_names.sort();
  let dst_names = dst.list("")?;
  let mut lines: List<Str> = [];
  for name in src_names {
    if name.ends_with("/") { continue; }
    let data = src.read(name)?;
    if dst_names.contains(name) {
      let old = dst.read(name)?;
      if old == data {
        lines.push("same " + name);
      } else {
        dst.write(name, data)?;
        lines.push("updated " + name);
      }
    } else {
      dst.write(name, data)?;
      lines.push("added " + name);
    }
  }
  let mut kept = 0;
  for name in dst_names {
    if name.ends_with("/") { continue; }
    if !src_names.contains(name) { kept += 1; }
  }
  lines.push("kept " + kept.to_str());
  Ok(lines.join("\n"))
}

const PREFIX: Str = "visits:";

struct Entry { page: Str, total: Int }

fn kv_err(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "kv error: too large",
    KvErr::Full => "kv error: store full",
    KvErr::NotInt => "kv error: stored value is not an integer",
    KvErr::Overflow => "kv error: overflow",
  }
}

fn count_batch(text: Str) -> Map<Str, Int> {
  let mut batch: Map<Str, Int> = Map::new();
  for line in text.lines() {
    let p = line.trim();
    if p.len() == 0 { continue; }
    let c = batch.get(p).unwrap_or(0);
    batch.insert(p, c + 1);
  }
  batch
}

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let text = match input.read("visits.txt") {
    Ok(b) => b.to_str(),
    Err(_) => return Err("cannot read visits.txt"),
  };
  let batch = count_batch(text);
  for p in batch.keys() {
    let n = batch.get(p).unwrap_or(0);
    counts.add(PREFIX + p, n).map_err(kv_err)?;
  }

  let mut entries: List<Entry> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = counts.scan(PREFIX, after, 1000).map_err(kv_err)?;
    for e in page {
      let name = e.key.strip_prefix(PREFIX).unwrap_or(e.key);
      let total = e.value.to_str().trim().parse_int().unwrap_or(0);
      entries.push(Entry { page: name, total: total });
      after = Some(e.key);
    }
    if page.len() < 1000 { break; }
  }

  entries.sort_by(|a, b| a.total > b.total || (a.total == b.total && a.page < b.page));
  let lines = entries.map(|e| e.page + " " + e.total.to_str());
  Ok(lines.join("\n"))
}

struct Entry { page: Str, total: Int }

const PREFIX: Str = "page:";

fn tally(text: Str) -> HashMap<Str, Int> {
  let mut m: HashMap<Str, Int> = HashMap::new();
  for line in text.lines() {
    let p = line.trim();
    if p.len() == 0 { continue; }
    let n = m.get(p).unwrap_or(0);
    m.insert(p, n + 1);
  }
  m
}

fn kv_err(e: KvErr) -> Str {
  match e {
    KvErr::TooLarge => "kv: too large",
    KvErr::Full => "kv: full",
    KvErr::NotInt => "kv: value is not an integer",
    KvErr::Overflow => "kv: overflow",
  }
}

fn io_err(e: IoErr) -> Str {
