    IoErr::Denied => "io: denied",
    IoErr::TooLarge => "io: too large",
    IoErr::InvalidPath => "io: invalid path",
    IoErr::Exists => "io: exists",
  }
}

fn record(counts: Kv, m: HashMap<Str, Int>) -> Result<(), Str> {
  for page in m.keys() {
    let n = m.get(page).unwrap_or(0);
    counts.add(PREFIX + page, n).map_err(kv_err)?;
  }
  Ok(())
}

fn load_all(counts: Kv) -> Result<List<Entry>, Str> {
  let keys = counts.keys(PREFIX).map_err(kv_err)?;
  let mut out: List<Entry> = [];
  for k in keys {
    let Some(v) = counts.get(k).map_err(kv_err)? else { continue; };
    let Some(page) = k.strip_prefix(PREFIX) else { continue; };
    let total = v.to_str().trim().parse_int().unwrap_or(0);
    out.push(Entry { page: page, total: total });
  }
  Ok(out)
}

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let text = input.read("visits.txt").map_err(io_err)?.to_str();
  let m = tally(text);
  record(counts, m)?;
  let mut entries = load_all(counts)?;
  entries.sort_by(|a: Entry, b: Entry| a.total > b.total || (a.total == b.total && a.page < b.page));
  let lines = entries.map(|e| e.page + " " + e.total.to_str());
  Ok(lines.join("\n"))
}

const PREFIX: Str = "visits:";
const PAGE: Int = 1000;

struct Entry { page: Str, total: Int }

fn tally_file(text: Str) -> Map<Str, Int> {
  let mut tally: Map<Str, Int> = Map::new();
  for line in text.lines() {
    let p = line.trim();
    if p.len() == 0 { continue; }
    let c = tally.get(p).unwrap_or(0);
    tally.insert(p, c + 1);
  }
  tally
}

fn add_counts(counts: Kv, tally: Map<Str, Int>) -> Result<(), Str> {
  for p in tally.keys() {
    let n = tally.get(p).unwrap_or(0);
    counts.add(PREFIX + p, n).map_err(|_e| "could not update the count for " + p)?;
  }
  Ok(())
}

fn load_totals(counts: Kv) -> Result<List<Entry>, Str> {
  let mut entries: List<Entry> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = counts.scan(PREFIX, after, PAGE).map_err(|_e| "could not read the counts store")?;
    for e in page {
      let name = e.key.strip_prefix(PREFIX).unwrap_or(e.key);
      let total = e.value.to_str().parse_int().unwrap_or(0);
      entries.push(Entry { page: name, total: total });
      after = Some(e.key);
    }
    if page.len() < PAGE { break; }
  }
  Ok(entries)
}

fn render(entries: List<Entry>) -> Str {
  let mut sorted = entries;
  sorted.sort_by(|a, b| a.total > b.total || (a.total == b.total && a.page < b.page));
  let mut lines: List<Str> = [];
  for e in sorted {
    lines.push(e.page + " " + e.total.to_str());
  }
  lines.join("\n")
}

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let bytes = input.read("visits.txt").map_err(|_e| "cannot read visits.txt")?;
  let tally = tally_file(bytes.to_str());
  add_counts(counts, tally)?;
  let entries = load_totals(counts)?;
  Ok(render(entries))
}

fn key(id: Str) -> Str {
  "user:" + id
}

fn words(line: Str) -> List<Str> {
  let mut out: List<Str> = [];
  for w in line.split(" ") {
    let t = w.trim();
    if t.len() > 0 {
      out.push(t);
    }
  }
  out
}

fn load(users: Kv, id: Str) -> Result<Option<List<Str>>, KvErr> {
  let v = users.get(key(id))?;
  match v {
    None => Ok(None),
    Some(b) => {
      let parts = b.to_str().split(" ");
      if parts.len() != 2 {
        Ok(None)
      } else {
        Ok(Some(parts))
      }
    }
  }
}

fn save(users: Kv, id: Str, name: Str, email: Str) -> Result<(), KvErr> {
  users.set(key(id), (name + " " + email).to_bytes())
}

fn run_cmd(users: Kv, line: Str) -> Result<Str, KvErr> {
  let w = words(line);
  let bad = "bad " + line;
  if w.len() == 0 {
    return Ok(bad);
  }
  let cmd = w[0];
  let n = w.len();
  if cmd == "put" && n == 4 {
    save(users, w[1], w[2], w[3])?;
    return Ok("ok " + w[1]);
  }
  if cmd == "rename" && n == 3 {
    let id = w[1];
    match load(users, id)? {
      None => return Ok("missing " + id),
      Some(p) => {
        save(users, id, w[2], p[1])?;
        return Ok("ok " + id);
      }
    }
  }
  if cmd == "get" && n == 2 {
    let id = w[1];
    match load(users, id)? {
      None => return Ok("missing " + id),
      Some(p) => {
        let s = "{\"id\":" + Json::Str(id).to_json()
          + ",\"name\":" + Json::Str(p[0]).to_json()
          + ",\"email\":" + Json::Str(p[1]).to_json() + "}";
        return Ok(s);
      }
    }
  }
  if cmd == "del" && n == 2 {
    let id = w[1];
    let existing = users.get(key(id))?;
    if existing.is_none() {
      return Ok("missing " + id);
    }
    users.delete(key(id))?;
    return Ok("ok " + id);
  }
  if cmd == "count" && n == 1 {
    let ks = users.keys("user:")?;
    return Ok("count " + ks.len().to_str());
  }
  Ok(bad)
}

fn process(input: Dir, users: Kv) -> Result<Str, Str> {
  let text = input.read("commands.txt").map_err(|e| "cannot read commands.txt")?.to_str();
  let mut out: List<Str> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 {
      continue;
    }
    let r = run_cmd(users, line).map_err(|e| "kv error")?;
    out.push(r);
  }
  Ok(out.join("\n"))
}

fn main(input: Dir, users: Kv) -> Result<Str, Str> {
  process(input, users)
}

struct Ev { id: Str, account: Str, cents: Int }

fn parse(line: Str) -> Option<Ev> {
  let Ok(j) = line.parse_json() else { return None; };
  let Json::Obj(m) = j else { return None; };
  let Some(Json::Str(id)) = m.get("id") else { return None; };
  let Some(Json::Str(account)) = m.get("account") else { return None; };
  let Some(Json::Num(cents)) = m.get("cents") else { return None; };
  if id.len() == 0 || id.len() > 1000 || account.len() > 1000 { return None; }
  Some(Ev { id: id, account: account, cents: cents })
}

fn kv<T>(r: Result<T, KvErr>) -> Result<T, Str> {
  r.map_err(|e| "key-value store error")
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
  let bytes = input.read("events.jsonl").map_err(|e| "cannot read events.jsonl")?;
  let text = bytes.to_str();
  let mut applied = 0;
  let mut dup = 0;
  let mut rejected = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let Some(ev) = parse(line) else { rejected += 1; continue; };
    let claimed = kv(state.swap("ev:" + ev.id, None, Some("1".to_bytes())))?;
    if claimed {
      kv(state.add("bal:" + ev.account, ev.cents))?;
      applied += 1;
    } else {
      dup += 1;
    }
  }
  let mut out: List<Str> = [];
  out.push("applied " + applied.to_str() + " duplicate " + dup.to_str() + " rejected " + rejected.to_str());
  let mut after: Option<Str> = None;
  loop {
    let page = kv(state.scan("bal:", after, 1000))?;
    for e in page {
      let name = e.key.strip_prefix("bal:").unwrap_or(e.key);
      let v = e.value.to_str().parse_int().unwrap_or(0);
      out.push(name + " " + v.to_str());
      after = Some(e.key);
    }
    if page.len() < 1000 { break; }
  }
  Ok(out.join("\n"))
}

