fn current_count(limits: Kv, key: Str) -> Result<Int, Str> {
  let v = limits.get(key).map_err(kv_err)?;
  match v {
    None => Ok(0),
    Some(b) => Ok(b.to_str().trim().parse_int().unwrap_or(0)),
  }
}

fn main(input: Dir, limits: Kv) -> Result<Str, Str> {
  let text = input.read("requests.txt").map_err(io_err)?.to_str();
  let mut out: List<Str> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    let parts = line.split(" ").filter(|p| p.len() > 0);
    if parts.len() != 2 { continue; }
    let Some(ts) = parts[0].parse_int() else { continue; };
    let client = parts[1];
    let mut window = ts / 60;
    if ts < 0 && ts % 60 != 0 { window = window - 1; }
    let key = "rl:" + window.to_str() + ":" + client;
    let count = current_count(limits, key)?;
    if count < 3 {
      limits.add(key, 1).map_err(kv_err)?;
      out.push(ts.to_str() + " " + client + " allow");
    } else {
      out.push(ts.to_str() + " " + client + " deny");
    }
  }
  Ok(out.join("\n"))
}

struct P { name: Str, points: Int, played: Int }

fn bump(m: Map<Str, P>, name: Str, pts: Int) -> Map<Str, P> {
  let mut m2 = m;
  let cur = m2.get(name).unwrap_or(P { name: name, points: 0, played: 0 });
  m2.insert(name, P { points: cur.points + pts, played: cur.played + 1, ..cur });
  m2
}

fn load(board: Kv) -> Result<Map<Str, P>, Str> {
  let mut m: Map<Str, P> = Map::new();
  let keys = board.keys("p:").map_err(|e| "kv keys failed")?;
  for k in keys {
    let Some(name) = k.strip_prefix("p:") else { continue; };
    let v = board.get(k).map_err(|e| "kv get failed")?;
    let Some(bytes) = v else { continue; };
    let text = bytes.to_str();
    let parts = text.split(" ");
    if parts.len() != 2 { continue; }
    let pts = parts[0].parse_int().unwrap_or(0);
    let pl = parts[1].parse_int().unwrap_or(0);
    m.insert(name, P { name: name, points: pts, played: pl });
  }
  Ok(m)
}

fn main(input: Dir, board: Kv) -> Result<Str, Str> {
  let mut m = load(board)?;
  let text = input.read("games.txt").map_err(|e| "cannot read games.txt")?.to_str();
  for line in text.lines() {
    let parts = line.trim().split(" ").filter(|s| s.len() > 0);
    if parts.len() == 2 {
      m = bump(m, parts[0], 3);
      m = bump(m, parts[1], 0);
    } else if parts.len() == 3 && parts[2] == "draw" {
      m = bump(m, parts[0], 1);
      m = bump(m, parts[1], 1);
    }
  }
  let mut players: List<P> = [];
  for k in m.keys() {
    let Some(p) = m.get(k) else { continue; };
    let val = p.points.to_str() + " " + p.played.to_str();
    board.set("p:" + k, val.to_bytes()).map_err(|e| "kv set failed")?;
    players.push(p);
  }
  players.sort_by(|a, b| {
    if a.points != b.points { a.points > b.points }
    else if a.played != b.played { a.played < b.played }
    else { a.name < b.name }
  });
  let mut out: List<Str> = [];
  let mut i = 0;
  while i < players.len() && i < 3 {
    let p = players[i];
    out.push((i + 1).to_str() + ". " + p.name + " " + p.points.to_str() + " " + p.played.to_str());
    i += 1;
  }
  Ok(out.join("\n"))
}

