fn sql_str(v: SqlValue) -> Str {
  match v {
    SqlValue::Null => "",
    SqlValue::Int(n) => n.to_str(),
    SqlValue::Float(f) => f.to_str(),
    SqlValue::Text(s) => s,
    SqlValue::Blob(b) => b.to_hex(),
  }
}

fn main(input: Dir, shop: Db) -> Result<Str, Str> {
  shop.exec("CREATE TABLE IF NOT EXISTS orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL)", []).map_err(db_err)?;
  let bytes = input.read("orders.csv").map_err(io_err)?;
  let text = bytes.to_str();
  let lines = text.lines();
  let mut imported = 0;
  let mut skipped = 0;
  let mut rejected = 0;
  for i in 0..lines.len() {
    if i == 0 { continue; }
    let line = lines[i].trim();
    if line.len() == 0 { continue; }
    let Some(o) = parse_line(line) else { rejected += 1; continue; };
    let n = shop.exec(
      "INSERT OR IGNORE INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?)",
      [SqlValue::Int(o.id), SqlValue::Text(o.customer), SqlValue::Text(o.product), SqlValue::Int(o.qty), SqlValue::Int(o.unit)]
    ).map_err(db_err)?;
    if n == 0 { skipped += 1; } else { imported += 1; }
  }
  let mut out: List<Str> = [];
  out.push("imported " + imported.to_str() + " skipped " + skipped.to_str() + " rejected " + rejected.to_str());
  let rows = shop.query(
    "SELECT product, SUM(qty * unit_cents) AS rev, COUNT(*) FROM orders GROUP BY product ORDER BY rev DESC, product ASC LIMIT 3",
    []
  ).map_err(db_err)?;
  for r in rows {
    out.push(sql_str(r[0]) + " " + sql_str(r[1]) + " " + sql_str(r[2]));
  }
  Ok(out.join("\n"))
}

