  for raw in text.lines() {
    if first { first = false; continue; }
    let line = raw.trim();
    if line == "" { continue; }
    let Some(o) = parse_order(line) else { rejected += 1; continue; };
    let n = shop.exec(
      "INSERT OR IGNORE INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?)",
      [SqlValue::Int(o.id), SqlValue::Text(o.customer), SqlValue::Text(o.product), SqlValue::Int(o.qty), SqlValue::Int(o.unit)]
    ).map_err(db_err)?;
    if n > 0 { imported += 1; } else { skipped += 1; }
  }

  let rows = shop.query(
    "SELECT product, SUM(qty * unit_cents) AS rev, COUNT(*) FROM orders GROUP BY product ORDER BY rev DESC, product ASC LIMIT 3",
    []
  ).map_err(db_err)?;

  let mut out: List<Str> = [];
  out.push("imported " + imported.to_str() + " skipped " + skipped.to_str() + " rejected " + rejected.to_str());
  for r in rows {
    out.push(cell(r[0]) + " " + cell(r[1]) + " " + cell(r[2]));
  }
  Ok(out.join("\n"))
}

struct Cust { id: Int, name: Str, country: Str, orders: Int, revenue: Int }

struct Agg { country: Str, customers: Int, orders: Int, revenue: Int, top: Str, top_rev: Int }

fn as_int(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    SqlValue::Float(f) => f.to_int().unwrap_or(0),
    SqlValue::Text(s) => s.parse_int().unwrap_or(0),
    _ => 0,
  }
}

fn as_text(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    SqlValue::Int(n) => n.to_str(),
    SqlValue::Float(f) => f.to_str(),
    SqlValue::Blob(b) => b.to_str(),
    SqlValue::Null => "",
  }
}

fn load(shop: Db) -> Result<List<Cust>, DbErr> {
  let rows = shop.query(
    "SELECT c.id, c.name, c.country, COUNT(*), SUM(o.total_cents) FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.status = 'paid' AND substr(o.placed, 1, 4) = '2026' GROUP BY c.id, c.name, c.country ORDER BY c.id",
    [])?;
  let mut out: List<Cust> = [];
  for r in rows {
    out.push(Cust {
      id: as_int(r[0]),
      name: as_text(r[1]),
      country: as_text(r[2]),
      orders: as_int(r[3]),
      revenue: as_int(r[4]),
    });
  }
  Ok(out)
}

fn main(shop: Db) -> Result<Str, DbErr> {
  let custs = load(shop)?;
  let mut aggs: Map<Str, Agg> = Map::new();
  for c in custs {
    let cur = aggs.get(c.country);
    let next = match cur {
      None => Agg { country: c.country, customers: 1, orders: c.orders, revenue: c.revenue, top: c.name, top_rev: c.revenue },
      Some(a) => {
        let better = c.revenue > a.top_rev;
        Agg {
          customers: a.customers + 1,
          orders: a.orders + c.orders,
          revenue: a.revenue + c.revenue,
          top: if better { c.name } else { a.top },
          top_rev: if better { c.revenue } else { a.top_rev },
          ..a
        }
      }
    };
    aggs.insert(c.country, next);
  }
  let mut list: List<Agg> = [];
  for k in aggs.keys() {
    let Some(a) = aggs.get(k) else { continue; };
    list.push(a);
  }
  list.sort_by(|a, b| a.revenue > b.revenue || (a.revenue == b.revenue && a.country < b.country));
  let mut lines: List<Str> = [];
  let mut tot_orders = 0;
  let mut tot_rev = 0;
  for a in list {
    tot_orders += a.orders;
    tot_rev += a.revenue;
    lines.push(a.country + " customers=" + a.customers.to_str() + " orders=" + a.orders.to_str()
      + " revenue=" + a.revenue.to_str() + " top=" + a.top);
  }
  lines.push("total orders=" + tot_orders.to_str() + " revenue=" + tot_rev.to_str());
  Ok(lines.join("\n"))
}

struct Move { sku: Str, delta: Int }

struct Batch { name: Str, lines: List<Str> }

fn dberr(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(m) => "database error: " + m,
    DbErr::Constraint(m) => "database constraint: " + m,
    DbErr::Denied => "database denied",
    DbErr::Busy => "database busy",
    DbErr::TooLarge => "database too large",
  }
}

fn all_digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for b in s.to_bytes() {
    if b < 48 || b > 57 { return false; }
  }
  true
}

fn parse_move(line: Str) -> Option<Move> {
  let parts = line.split(" ").filter(|p| p.len() > 0);
  if parts.len() != 2 { return None; }
  let sku = parts[0];
  let amt = parts[1];
  let mut sign = 1;
  let mut rest = "";
  if let Some(r) = amt.strip_prefix("+") {
    rest = r;
  } else if let Some(r) = amt.strip_prefix("-") {
    rest = r;
    sign = -1;
  } else {
    return None;
  }
  if !all_digits(rest) { return None; }
  if rest.len() > 15 { return None; }
  let n = rest.parse_int()?;
  if n <= 0 { return None; }
  Some(Move { sku: sku, delta: sign * n })
}

fn current(db: Db, sku: Str) -> Result<Int, Str> {
  let rows = db.query("SELECT qty FROM stock WHERE sku = ?", [SqlValue::Text(sku)]).map_err(dberr)?;
  if rows.len() == 0 { return Ok(0); }
  match rows[0][0] {
    SqlValue::Int(n) => Ok(n),
    _ => Ok(0),
  }
}

fn already_applied(db: Db, name: Str) -> Result<Bool, Str> {
  let rows = db.query("SELECT 1 FROM applied WHERE name = ?", [SqlValue::Text(name)]).map_err(dberr)?;
  Ok(rows.len() > 0)
}

fn parse_batches(text: Str) -> List<Batch> {
  let mut batches: List<Batch> = [];
  let mut have = false;
  let mut cur = Batch { name: "", lines: [] };
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    let parts = line.split(" ").filter(|p| p.len() > 0);
    if parts.len() == 2 && parts[0] == "batch" {
      if have { batches.push(cur); }
      cur = Batch { name: parts[1], lines: [] };
      have = true;
    } else if have {
      cur.lines.push(line);
    }
  }
  if have { batches.push(cur); }
  batches
}

fn apply_batch(stock: Db, b: Batch) -> Result<Bool, Str> {
  let mut qty: HashMap<Str, Int> = HashMap::new();
  for line in b.lines {
    let Some(m) = parse_move(line) else { return Ok(false); };
    let cur = match qty.get(m.sku) {
      Some(q) => q,
      None => current(stock, m.sku)?,
    };
    let n = cur + m.delta;
    if n < 0 { return Ok(false); }
    qty.insert(m.sku, n);
  }
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  for k in qty.keys() {
    let v = qty.get(k).unwrap_or(0);
    stmts.push("INSERT INTO stock (sku, qty) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET qty = excluded.qty");
    params.push([SqlValue::Text(k), SqlValue::Int(v)]);
  }
  stmts.push("INSERT INTO applied (name) VALUES (?)");
  params.push([SqlValue::Text(b.name)]);
  stock.transaction(stmts, params).map_err(dberr)?;
  Ok(true)
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
  stock.exec("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)", []).map_err(dberr)?;
  stock.exec("CREATE TABLE IF NOT EXISTS applied (name TEXT PRIMARY KEY)", []).map_err(dberr)?;
  let text = input.read("moves.txt").map_err(|e| "cannot read moves.txt")?.to_str();
  let batches = parse_batches(text);
  let mut out = "";
  for b in batches {
    if already_applied(stock, b.name)? {
      out = out + b.name + " skipped\n";
    } else if apply_batch(stock, b)? {
      out = out + b.name + " applied\n";
    } else {
      out = out + b.name + " rejected\n";
    }
  }
  let rows = stock.query("SELECT sku, qty FROM stock WHERE qty != 0 ORDER BY sku", []).map_err(dberr)?;
  for row in rows {
    let sku = match row[0] { SqlValue::Text(s) => s, _ => "" };
    let q = match row[1] { SqlValue::Int(n) => n, _ => 0 };
    out = out + sku + " " + q.to_str() + "\n";
  }
  Ok(out)
}

fn db_err(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(s) => "db invalid: " + s,
    DbErr::Denied => "db denied",
    DbErr::Busy => "db busy",
    DbErr::TooLarge => "db too large",
    DbErr::Constraint(s) => "db constraint: " + s,
  }
}

fn io_err(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "not found",
    IoErr::Denied => "denied",
    IoErr::TooLarge => "too large",
    IoErr::InvalidPath => "invalid path",
    IoErr::Exists => "exists",
  }
}

fn text(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn main(input: Dir, crm: Db) -> Result<Str, Str> {
  crm.exec("CREATE TABLE IF NOT EXISTS contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL)", []).map_err(db_err)?;
  let content = input.read("contacts.csv").map_err(io_err)?.to_str();
  let mut inserted = 0;
  let mut updated = 0;
  let mut unchanged = 0;
  let mut rejected = 0;
  let mut first = true;
  for line in content.lines() {
    if first { first = false; continue; }
    if line.trim().len() == 0 { continue; }
    let parts = line.split(",");
    if parts.len() != 3 { rejected += 1; continue; }
    let email = parts[0].trim().to_lowercase();
    if !email.contains("@") { rejected += 1; continue; }
    let name = parts[1].trim();
    let phone = parts[2].trim();
    let rows = crm.query("SELECT name, phone FROM contacts WHERE email = ?", [SqlValue::Text(email)]).map_err(db_err)?;
    if rows.len() == 0 {
      crm.exec("INSERT INTO contacts (email, name, phone) VALUES (?, ?, ?)",
        [SqlValue::Text(email), SqlValue::Text(name), SqlValue::Text(phone)]).map_err(db_err)?;
      inserted += 1;
    } else {
      let row = rows[0];
      let old_name = text(row[0]);
      let old_phone = text(row[1]);
      if old_name != name || old_phone != phone {
        crm.exec("UPDATE contacts SET name = ?, phone = ? WHERE email = ?",
          [SqlValue::Text(name), SqlValue::Text(phone), SqlValue::Text(email)]).map_err(db_err)?;
        updated += 1;
      } else {
        unchanged += 1;
      }
    }
  }
  let mut out: List<Str> = [];
  out.push("inserted " + inserted.to_str() + " updated " + updated.to_str() + " unchanged " + unchanged.to_str() + " rejected " + rejected.to_str());
  let cnt = crm.query("SELECT COUNT(*) FROM contacts", []).map_err(db_err)?;
  let mut total = 0;
  if cnt.len() > 0 {
    match cnt[0][0] {
      SqlValue::Int(n) => total = n,
      _ => {}
    }
  }
  out.push("contacts " + total.to_str());
  let missing = crm.query("SELECT email FROM contacts WHERE phone = '' ORDER BY email", []).map_err(db_err)?;
  let mut emails: List<Str> = [];
  for r in missing { emails.push(text(r[0])); }
  emails.sort();
  for e in emails { out.push("missing phone: " + e); }
  Ok(out.join("\n"))
}

struct Resp { status: Int, body: Json }

struct Entry { name: Str, count: Int }

fn valid_name(name: Str) -> Bool {
  if name.len() < 1 || name.len() > 32 { return false; }
  for b in name.to_bytes() {
    let ok = (b >= 97 && b <= 122) || (b >= 48 && b <= 57) || b == 45;
    if !ok { return false; }
  }
  true
}

fn err_json(msg: Str) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Json::Obj(m)
}

fn count_json(name: Str, count: Int) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(name));
  m.insert("count", Json::Num(count));
  Json::Obj(m)
}

fn bad_name() -> Resp { Resp { status: 400, body: err_json("bad name") } }

fn not_found() -> Resp { Resp { status: 404, body: err_json("not found") } }

fn get_count(counts: Kv, name: Str) -> Result<Int, KvErr> {
  let v = counts.get("c:" + name)?;
  match v {
    Some(b) => Ok(b.to_str().trim().parse_int().unwrap_or(0)),
    None => Ok(0),
  }
}

fn top(counts: Kv) -> Result<List<Entry>, KvErr> {
  let mut all: List<Entry> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = counts.scan("c:", after, 1000)?;
    for e in page {
      let name = e.key.slice(2, e.key.len());
      let n = e.value.to_str().trim().parse_int().unwrap_or(0);
      all.push(Entry { name: name, count: n });
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  all.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.name < b.name));
  if all.len() > 3 {
    Ok(all.slice(0, 3))
  } else {
    Ok(all)
  }
}

fn handle(req: Incoming, counts: Kv) -> Result<Resp, KvErr> {
  let method = req.method();
  let target = req.target();
  if method == "POST" {
    if let Some(name) = target.strip_prefix("/hit/") {
      if !valid_name(name) { return Ok(bad_name()); }
      let n = counts.add("c:" + name, 1)?;
      return Ok(Resp { status: 200, body: count_json(name, n) });
    }
    return Ok(not_found());
  }
  if method == "GET" {
    if target == "/top" {
      let entries = top(counts)?;
      let mut arr: List<Json> = [];
      for e in entries { arr.push(count_json(e.name, e.count)); }
      return Ok(Resp { status: 200, body: Json::Arr(arr) });
    }
    if let Some(name) = target.strip_prefix("/count/") {
      if !valid_name(name) { return Ok(bad_name()); }
      let n = get_count(counts, name)?;
      return Ok(Resp { status: 200, body: count_json(name, n) });
    }
    return Ok(not_found());
  }
  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Str {
  let r = match handle(req, counts) {
    Ok(r) => r,
    Err(_) => Resp { status: 500, body: err_json("storage error") },
  };
  let sent = res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes());
  match sent {
    Ok(_) => r.status.to_str(),
    Err(_) => "send failed",
  }
}

struct Todo { id: Int, title: Str, done: Bool }

fn todo_json(t: Todo) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(t.id));
  m.insert("title", Json::Str(t.title));
  m.insert("done", Json::Bool(t.done));
  Json::Obj(m)
}

fn err_json(msg: Str) -> Str {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Json::Obj(m).to_json()
}

fn pad(n: Int) -> Str {
  let mut s = n.to_str();
  while s.len() < 20 { s = "0" + s; }
  s
}

fn key(id: Int) -> Str { "todo/" + pad(id) }

fn reply(res: Outgoing, status: Int, body: Str) {
  if body.len() == 0 {
    let _r = res.send(status, [], [], "".to_bytes());
  } else {
    let _r = res.send(status, ["content-type"], ["application/json"], body.to_bytes());
  }
}

fn cont(b: Bytes, i: Int, lo: Int, hi: Int) -> Bool {
  if i >= b.len() { return false; }
  b[i] >= lo && b[i] <= hi
}

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 {
      i += 1;
    } else if c >= 194 && c <= 223 {
      if !cont(b, i + 1, 128, 191) { return false; }
      i += 2;
    } else if c >= 224 && c <= 239 {
      let mut lo = 128;
      let mut hi = 191;
      if c == 224 { lo = 160; }
      if c == 237 { hi = 159; }
      if !cont(b, i + 1, lo, hi) { return false; }
      if !cont(b, i + 2, 128, 191) { return false; }
      i += 3;
    } else if c >= 240 && c <= 244 {
      let mut lo = 128;
      let mut hi = 191;
      if c == 240 { lo = 144; }
      if c == 244 { hi = 143; }
      if !cont(b, i + 1, lo, hi) { return false; }
      if !cont(b, i + 2, 128, 191) { return false; }
      if !cont(b, i + 3, 128, 191) { return false; }
      i += 4;
    } else {
      return false;
    }
  }
  true
}

fn body_json(req: Incoming) -> Option<Json> {
  let b = req.body();
  if !valid_utf8(b) { return None; }
  b.to_str().parse_json().ok()
}

fn decode(b: Bytes) -> Option<Todo> {
  if !valid_utf8(b) { return None; }
  let j = b.to_str().parse_json().ok()?;
  let id = j.get("id")?.as_int()?;
  let title = j.get("title")?.as_str()?;
  let done = j.get("done")?.as_bool()?;
  Some(Todo { id: id, title: title, done: done })
}

fn parse_id(s: Str) -> Option<Int> {
  if s.len() == 0 || s.len() > 18 { return None; }
  for c in s.to_bytes() {
    if c < 48 || c > 57 { return None; }
  }
  let n = s.parse_int()?;
  if n <= 0 { return None; }
  Some(n)
}

fn list(res: Outgoing, store: Kv, query: Str) -> Result<(), KvErr> {
  let mut filter: Option<Bool> = None;
  if query.len() > 0 {
    for part in query.split("&") {
      if part == "done=true" { filter = Some(true); }
      else if part == "done=false" { filter = Some(false); }
    }
  }
  let mut items: List<Json> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = store.scan("todo/", after, 1000)?;
    for e in page {
      if let Some(t) = decode(e.value) {
        let keep = match filter { None => true, Some(d) => t.done == d };
        if keep { items.push(todo_json(t)); }
      }
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  reply(res, 200, Json::Arr(items).to_json());
  Ok(())
}

fn create(req: Incoming, res: Outgoing, store: Kv) -> Result<(), KvErr> {
  let mut title = "";
  if let Some(Json::Obj(m)) = body_json(req) {
    if let Some(Json::Str(s)) = m.get("title") {
      title = s.trim();
    }
  }
  if title.len() == 0 {
    reply(res, 400, err_json("title required"));
    return Ok(());
  }
  let id = store.add("next", 1)?;
  let t = Todo { id: id, title: title, done: false };
  let text = todo_json(t).to_json();
  store.set(key(id), text.to_bytes())?;
  reply(res, 201, text);
  Ok(())
}

fn get_one(res: Outgoing, store: Kv, id: Int) -> Result<(), KvErr> {
  let Some(b) = store.get(key(id))? else {
    reply(res, 404, err_json("not found"));
    return Ok(());
  };
  let Some(t) = decode(b) else {
    reply(res, 404, err_json("not found"));
    return Ok(());
  };
  reply(res, 200, todo_json(t).to_json());
  Ok(())
}

fn patch(req: Incoming, res: Outgoing, store: Kv, id: Int) -> Result<(), KvErr> {
  let Some(_b) = store.get(key(id))? else {
    reply(res, 404, err_json("not found"));
    return Ok(());
  };
  let Some(Json::Obj(m)) = body_json(req) else {
    reply(res, 400, err_json("bad update"));
    return Ok(());
  };
  let mut new_title: Option<Str> = None;
  let mut new_done: Option<Bool> = None;
  if let Some(v) = m.get("title") {
    let Json::Str(s) = v else {
      reply(res, 400, err_json("bad update"));
      return Ok(());
    };
    let tr = s.trim();
    if tr.len() == 0 {
      reply(res, 400, err_json("bad update"));
      return Ok(());
    }
    new_title = Some(tr);
  }
  if let Some(v) = m.get("done") {
    let Json::Bool(d) = v else {
      reply(res, 400, err_json("bad update"));
      return Ok(());
    };
    new_done = Some(d);
  }
  loop {
    let Some(old) = store.get(key(id))? else {
      reply(res, 404, err_json("not found"));
      return Ok(());
    };
    let Some(t) = decode(old) else {
      reply(res, 404, err_json("not found"));
      return Ok(());
    };
    let mut nt = t;
    if let Some(s) = new_title { nt.title = s; }
    if let Some(d) = new_done { nt.done = d; }
    let text = todo_json(nt).to_json();
    if store.swap(key(id), Some(old), Some(text.to_bytes()))? {
      reply(res, 200, text);
      return Ok(());
    }
  }
}

fn remove(res: Outgoing, store: Kv, id: Int) -> Result<(), KvErr> {
  let Some(old) = store.get(key(id))? else {
    reply(res, 404, err_json("not found"));
    return Ok(());
  };
  if store.swap(key(id), Some(old), None)? {
    reply(res, 204, "");
    return Ok(());
  }
  match store.get(key(id))? {
    None => reply(res, 404, err_json("not found")),
    Some(_) => {
      store.delete(key(id))?;
      reply(res, 204, "");
    }
  }
  Ok(())
}

fn handle(req: Incoming, res: Outgoing, store: Kv) -> Result<(), KvErr> {
  let target = req.target();
  let method = req.method();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  if path == "/todos" {
    if method == "GET" { return list(res, store, query); }
    if method == "POST" { return create(req, res, store); }
    reply(res, 404, err_json("not found"));
    return Ok(());
  }
  if let Some(rest) = path.strip_prefix("/todos/") {
    if let Some(id) = parse_id(rest) {
      if method == "GET" { return get_one(res, store, id); }
      if method == "PATCH" { return patch(req, res, store, id); }
      if method == "DELETE" { return remove(res, store, id); }
    }
  }
  reply(res, 404, err_json("not found"));
  Ok(())
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Str {
