    }
  }
}

struct Resp { status: Int, body: Json }

struct Note { id: Int, title: Str, body: Str, tags: List<Str> }

struct NewNote { title: Str, body: Str, tags: List<Str> }

fn msg(status: Int, key: Str, text: Str) -> Resp {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(key, Json::Str(text));
  Resp { status: status, body: Json::Obj(m) }
}

fn not_found() -> Resp { msg(404, "error", "not found") }

fn server_err() -> Resp { msg(500, "error", "internal error") }

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 { i += 1; continue; }
    let mut need = 0;
    let mut min = 0;
    let mut cp = 0;
    if c >= 194 && c <= 223 { need = 1; min = 128; cp = c - 192; }
    else if c >= 224 && c <= 239 { need = 2; min = 2048; cp = c - 224; }
    else if c >= 240 && c <= 244 { need = 3; min = 65536; cp = c - 240; }
    else { return false; }
    if i + need >= n + 0 && i + need > n - 1 { if i + need > n - 1 { return false; } }
    let mut k = 1;
    while k <= need {
      let d = b[i + k];
      if d < 128 || d > 191 { return false; }
      cp = cp * 64 + (d - 128);
      k += 1;
    }
    if cp < min || cp > 1114111 || (cp >= 55296 && cp <= 57343) { return false; }
    i = i + need + 1;
  }
  true
}

fn parse_new(body: Bytes) -> Option<NewNote> {
  if !valid_utf8(body) { return None; }
  let j = body.to_str().parse_json().ok()?;
  let m = j.as_map()?;
  let title = m.get("title")?.as_str()?;
  if title.len() == 0 { return None; }
  let text = m.get("body")?.as_str()?;
  let mut tags: List<Str> = [];
  if let Some(t) = m.get("tags") {
    let items = t.as_list()?;
    for it in items {
      let s = it.as_str()?.to_lowercase();
      if !tags.contains(s) { tags.push(s); }
    }
  }
  Some(NewNote { title: title, body: text, tags: tags })
}

fn row_note(row: List<SqlValue>) -> Option<Note> {
  if row.len() < 4 { return None; }
  let id = match row[0] { SqlValue::Int(n) => n, _ => return None };
  let title = match row[1] { SqlValue::Text(s) => s, _ => return None };
  let body = match row[2] { SqlValue::Text(s) => s, _ => return None };
  let tj = match row[3] { SqlValue::Text(s) => s, _ => return None };
  let list = tj.parse_json().ok()?.as_list()?;
  let mut tags: List<Str> = [];
  for t in list { tags.push(t.as_str()?); }
  Some(Note { id: id, title: title, body: body, tags: tags })
}

fn note_json(n: Note) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(n.id));
  m.insert("title", Json::Str(n.title));
  m.insert("body", Json::Str(n.body));
  m.insert("tags", Json::Arr(n.tags.map(|t| Json::Str(t))));
  Json::Obj(m)
}

fn create(db: Db, body: Bytes) -> Resp {
  let Some(n) = parse_new(body) else { return msg(400, "error", "invalid note"); };
  let tags = Json::Arr(n.tags.map(|t| Json::Str(t))).to_json();
  let r = db.query("INSERT INTO notes (title, body, tags) VALUES (?, ?, ?) RETURNING id",
    [SqlValue::Text(n.title), SqlValue::Text(n.body), SqlValue::Text(tags)]);
  let Ok(rows) = r else { return server_err(); };
  if rows.len() == 0 || rows[0].len() == 0 { return server_err(); }
  let SqlValue::Int(id) = rows[0][0] else { return server_err(); };
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  Resp { status: 201, body: Json::Obj(m) }
}

fn get_one(db: Db, id: Int) -> Resp {
  let Ok(rows) = db.query("SELECT id, title, body, tags FROM notes WHERE id = ?", [SqlValue::Int(id)]) else { return server_err(); };
  if rows.len() == 0 { return not_found(); }
  let Some(n) = row_note(rows[0]) else { return server_err(); };
  Resp { status: 200, body: note_json(n) }
}

fn delete_one(db: Db, id: Int) -> Resp {
  let Ok(c) = db.exec("DELETE FROM notes WHERE id = ?", [SqlValue::Int(id)]) else { return server_err(); };
  if c == 0 { return not_found(); }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("deleted", Json::Num(id));
  Resp { status: 200, body: Json::Obj(m) }
}

fn list_all(db: Db, query: Str) -> Resp {
  let mut tag: Option<Str> = None;
  let mut q: Option<Str> = None;
  if query.len() > 0 {
    for p in query.split("&") {
      let kv = p.split("=");
      if kv.len() < 2 { continue; }
      if kv[0] == "tag" { tag = Some(kv[1].to_lowercase()); }
      else if kv[0] == "q" { q = Some(kv[1]); }
    }
  }
  let Ok(rows) = db.query("SELECT id, title, body, tags FROM notes ORDER BY id DESC", []) else { return server_err(); };
  let mut out: List<Json> = [];
  for row in rows {
    let Some(n) = row_note(row) else { continue; };
    if let Some(t) = tag { if !n.tags.contains(t) { continue; } }
    if let Some(w) = q { if !(n.title.contains(w) || n.body.contains(w)) { continue; } }
    let mut m: Map<Str, Json> = Map::new();
    m.insert("id", Json::Num(n.id));
    m.insert("title", Json::Str(n.title));
    out.push(Json::Obj(m));
  }
  Resp { status: 200, body: Json::Arr(out) }
}

fn handle(req: Incoming, db: Db) -> Resp {
  let schema = db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)", []);
  if schema.is_err() { return server_err(); }
  let target = req.target();
  let method = req.method();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  let segs = path.split("/");
  if segs.len() < 2 || segs[0] != "" || segs[1] != "notes" { return not_found(); }
  if segs.len() == 2 {
    if method == "GET" { return list_all(db, query); }
    if method == "POST" { return create(db, req.body()); }
    return not_found();
  }
  if segs.len() != 3 { return not_found(); }
  let s = segs[2];
  if s.len() == 0 || s.len() > 18 { return not_found(); }
  for c in s.to_bytes() { if c < 48 || c > 57 { return not_found(); } }
  let Some(id) = s.parse_int() else { return not_found(); };
  if method == "GET" { return get_one(db, id); }
  if method == "DELETE" { return delete_one(db, id); }
  not_found()
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Str {
  let r = handle(req, db);
  let sent = res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes());
  if sent.is_err() { return "send failed"; }
  r.status.to_str()
}

