fn fmt(t: Int) -> Str {
  let a = if t < 0 { -t } else { t };
  let s = (a / 10).to_str() + "." + (a % 10).to_str();
  if t < 0 { "-" + s } else { s }
}

fn station_line(api: Http, st: Station) -> Str {
  let path = "/stations/" + st.id + "/readings";
  let body = match api.get(path) {
    Ok(b) => b,
    Err(_) => return st.name + " unavailable",
  };
  let doc = match body.to_str().parse_json() {
    Ok(j) => j,
    Err(_) => return st.name + " unavailable",
  };
  let readings = doc.get("readings").and_then(|j| j.as_list()).unwrap_or([]);
  let mut temps: List<Int> = [];
  for r in readings {
    let Some(t) = r.get("temp").and_then(|j| j.as_int()) else { continue; };
    temps.push(t);
  }
  if temps.len() == 0 {
    return st.name + " no data";
  }
  let mut mn = temps[0];
  let mut mx = temps[0];
  let mut sum = 0;
  for t in temps {
    mn = mn.min(t);
    mx = mx.max(t);
    sum = sum + t;
  }
  let n = temps.len();
  let avg = sum / n;
  st.name + " min=" + fmt(mn) + " max=" + fmt(mx) + " avg=" + fmt(avg) + " n=" + n.to_str()
}

