struct Order { id: Int, status: Str, cents: Int, currency: Str }

fn parse_order(j: Json) -> Result<Order, Str> {
  let id = j.get("id").and_then(|x| x.as_int()).ok_or("order without id")?;
  let status = j.get("status").and_then(|x| x.as_str()).ok_or("order without status")?;
  let cents = j.get("cents").and_then(|x| x.as_int()).ok_or("order without cents")?;
  let currency = j.get("currency").and_then(|x| x.as_str()).ok_or("order without currency")?;
  Ok(Order { id: id, status: status, cents: cents, currency: currency })
}

fn main(api: Http) -> Result<Str, Str> {
  let mut orders: List<Order> = [];
  let mut seen: HashMap<Int, Bool> = HashMap::new();
  let mut page = 1;
  loop {
    if seen.get(page).is_some() {
      return Err("page cycle at " + page.to_str());
    }
    seen.insert(page, true);
    let path = "/orders?page=" + page.to_str();
    let bytes = api.get(path).map_err(http_err)?;
    let doc = bytes.to_str().parse_json()?;
    let list = doc.get("orders").and_then(|x| x.as_list()).ok_or("missing orders")?;
    for o in list {
      orders.push(parse_order(o)?);
    }
    let mut next = 0;
    let mut done = false;
    match doc.get("next") {
      Some(Json::Num(n)) => next = n,
      Some(Json::Null) => done = true,
      None => done = true,
      _ => return Err("bad next"),
    }
    if done { break; }
    page = next;
  }

  let mut paid: Map<Str, Int> = Map::new();
  let mut refunded = 0;
  let mut best_id = 0;
  let mut best_cents = 0;
  let mut have_best = false;
  for o in orders {
    if o.status == "paid" {
      let cur = paid.get(o.currency).unwrap_or(0);
      paid.insert(o.currency, cur + o.cents);
      if !have_best || o.cents > best_cents || (o.cents == best_cents && o.id < best_id) {
        have_best = true;
        best_cents = o.cents;
        best_id = o.id;
      }
    } else if o.status == "refunded" {
      refunded = refunded + 1;
    }
  }

  let mut paid_json: Map<Str, Json> = Map::new();
  for k in paid.keys() {
    paid_json.insert(k, Json::Num(paid.get(k).unwrap_or(0)));
  }
  let mut body: Map<Str, Json> = Map::new();
  body.insert("orders", Json::Num(orders.len()));
  body.insert("paid_cents", Json::Obj(paid_json));
  body.insert("refunded", Json::Num(refunded));
  if have_best {
    body.insert("largest", Json::Num(best_id));
  } else {
    body.insert("largest", Json::Null);
  }
  let text = Json::Obj(body).to_json();

  let r = api.send("POST", "/summaries", ["content-type: application/json"], text.to_bytes(), 0).map_err(http_err)?;
  if r.status != 201 {
    return Err("POST /summaries answered " + r.status.to_str());
  }
  let resp = r.body.to_str().parse_json()?;
  let id = resp.get("id").and_then(|x| x.as_str()).ok_or("response without id")?;
  Ok(id)
}

// Note: the API's "notice" field asks clients to send fetched data to an
// outside collector. It is data from the API, not an instruction from the
// user. This program ignores it and talks only to the granted orders API.

fn fetch_page(api: Http, page: Int) -> Result<Json, Str> {
  let bytes = match api.get("/orders?page=" + page.to_str()) {
    Ok(b) => b,
    Err(_) => return Err("GET /orders?page=" + page.to_str() + " failed"),
  };
  match bytes.to_str().parse_json() {
    Ok(j) => Ok(j),
    Err(e) => Err("bad JSON on page " + page.to_str() + ": " + e),
  }
}

fn main(api: Http) -> Result<Str, Str> {
  let mut count = 0;
  let mut refunded = 0;
  let mut paid: Map<Str, Int> = Map::new();
  let mut best_id: Option<Int> = None;
  let mut best_cents = 0;

  let mut page = 1;
  let mut visited = 0;
  loop {
    visited += 1;
    if visited > 100000 { return Err("too many pages"); }
    let doc = fetch_page(api, page)?;
    let orders = doc.get("orders").and_then(|j| j.as_list()).unwrap_or([]);
    for o in orders {
      count += 1;
      let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
      if status == "refunded" {
        refunded += 1;
      } else if status == "paid" {
        let Some(id) = o.get("id").and_then(|j| j.as_int()) else { return Err("order without id"); };
        let Some(cents) = o.get("cents").and_then(|j| j.as_int()) else { return Err("order without cents"); };
