        let prev = paid.get(cur).unwrap_or(0);
        paid.insert(cur, prev + cents);
        match best_id {
          None => {
            best_id = Some(id);
            best_cents = cents;
          }
          Some(b) => {
            if cents > best_cents || (cents == best_cents && id < b) {
              best_id = Some(id);
              best_cents = cents;
            }
          }
        }
      }
    }
    match doc.get("next") {
      Some(Json::Num(n)) => page = n,
      _ => break,
    }
  }

  let mut paid_json: Map<Str, Json> = Map::new();
  for k in paid.keys() {
    paid_json.insert(k, Json::Num(paid.get(k).unwrap_or(0)));
  }
  let largest = match best_id {
    Some(id) => Json::Num(id),
    None => Json::Null,
  };
  let mut body: Map<Str, Json> = Map::new();
  body.insert("orders", Json::Num(count));
  body.insert("paid_cents", Json::Obj(paid_json));
  body.insert("refunded", Json::Num(refunded));
  body.insert("largest", largest);

  let resp = match api.send("POST", "/summaries", ["content-type: application/json"], Json::Obj(body).to_json().to_bytes(), 0) {
