struct State { order: List<Str>, vals: Map<Str, Str>, hits: Int, misses: Int, evictions: Int }

fn empty_state() -> State {
  State { order: [], vals: Map::new(), hits: 0, misses: 0, evictions: 0 }
}

fn decode(j: Json) -> State {
  let mut order: List<Str> = [];
  for x in j.get("order").and_then(|x| x.as_list()).unwrap_or([]) {
    if let Some(s) = x.as_str() { order.push(s); }
  }
  let mut vals: Map<Str, Str> = Map::new();
  let m = j.get("vals").and_then(|x| x.as_map()).unwrap_or(Map::new());
  for k in m.keys() {
    if let Some(v) = m.get(k) {
      if let Some(s) = v.as_str() { vals.insert(k, s); }
    }
  }
  State {
    order: order,
    vals: vals,
    hits: j.get("hits").and_then(|x| x.as_int()).unwrap_or(0),
    misses: j.get("misses").and_then(|x| x.as_int()).unwrap_or(0),
    evictions: j.get("evictions").and_then(|x| x.as_int()).unwrap_or(0),
  }
}

fn encode(s: State) -> Str {
  let mut obj: Map<Str, Json> = Map::new();
  obj.insert("order", Json::Arr(s.order.map(|k| Json::Str(k))));
  let mut vm: Map<Str, Json> = Map::new();
  for k in s.vals.keys() {
    vm.insert(k, Json::Str(s.vals.get(k).unwrap_or("")));
  }
  obj.insert("vals", Json::Obj(vm));
  obj.insert("hits", Json::Num(s.hits));
  obj.insert("misses", Json::Num(s.misses));
  obj.insert("evictions", Json::Num(s.evictions));
  Json::Obj(obj).to_json()
}

fn to_front(order: List<Str>, k: Str) -> List<Str> {
  let mut out: List<Str> = [k];
  for x in order { if x != k { out.push(x); } }
  out
}

fn remove_key(order: List<Str>, k: Str) -> List<Str> {
  order.filter(|x| x != k)
}

fn main(input: Dir, cache: Kv) -> Result<Str, Str> {
  let text = input.read("ops.txt").map_err(|e| "cannot read ops.txt")?.to_str();
  let lines = text.lines();
  if lines.len() == 0 { return Err("empty ops.txt"); }
  let cap = lines[0].trim().strip_prefix("capacity ").and_then(|s| s.trim().parse_int()).unwrap_or(1).max(1);

  let stored = cache.get("lru").map_err(|e| "kv error")?;
  let st = match stored {
    Some(b) => match b.to_str().parse_json() {
      Ok(j) => decode(j),
      Err(_) => empty_state(),
    },
    None => empty_state(),
  };
  let mut order = st.order;
  let mut vals = st.vals;
  let mut hits = st.hits;
  let mut misses = st.misses;
  let mut evictions = st.evictions;
  let mut out: List<Str> = [];

  while order.len() > cap {
    let Some(k) = order.pop() else { break; };
    vals.remove(k);
    evictions += 1;
    out.push("evict " + k);
  }

  for i in 1..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    let n = i + 1;
    let parts = line.split(" ");
    let op = parts[0];
    if (op == "get" || op == "del") && parts.len() == 2 && parts[1] != "" {
      let k = parts[1];
      if op == "get" {
        match vals.get(k) {
          Some(v) => {
            hits += 1;
            order = to_front(order, k);
            out.push(k + "=" + v);
          }
          None => {
            misses += 1;
            out.push(k + " miss");
          }
        }
      } else {
        if vals.get(k).is_some() {
          vals.remove(k);
          order = remove_key(order, k);
        }
      }
    } else if op == "put" {
      let rest = line.slice(4, line.len());
      let mut ok = false;
      if let Some(p) = rest.find(" ") {
        let k = rest.slice(0, p);
        let v = rest.slice(p + 1, rest.len());
        if k != "" && v != "" {
          ok = true;
          if vals.get(k).is_none() && order.len() >= cap {
            if let Some(ev) = order.pop() {
              vals.remove(ev);
              evictions += 1;
              out.push("evict " + ev);
            }
          }
          vals.insert(k, v);
          order = to_front(order, k);
        }
      }
      if !ok { out.push("bad line " + n.to_str()); }
    } else {
      out.push("bad line " + n.to_str());
    }
  }

  if order.len() == 0 {
    out.push("cache:");
  } else {
    out.push("cache: " + order.join(","));
  }
  out.push("stats hits " + hits.to_str() + " misses " + misses.to_str() + " evictions " + evictions.to_str());

  let ns = State { order: order, vals: vals, hits: hits, misses: misses, evictions: evictions };
  cache.set("lru", encode(ns).to_bytes()).map_err(|e| "kv error")?;
  Ok(out.join("\n"))
}

fn parse_deps(j: Json) -> Option<List<Str>> {
  match j {
    Json::Arr(xs) => {
      let mut out: List<Str> = [];
      for x in xs {
        let Json::Str(s) = x else { return None; };
        if !out.contains(s) { out.push(s); }
      }
      Some(out)
    }
    _ => None,
  }
}

fn reach_from(deps: Map<Str, List<Str>>, p: Str) -> Map<Str, Bool> {
  let mut seen: Map<Str, Bool> = Map::new();
  let mut stack: List<Str> = [];
  let start = deps.get(p).unwrap_or([]);
  for d in start { stack.push(d); }
  loop {
    let Some(q) = stack.pop() else { break; };
    if seen.get(q).is_some() { continue; }
    let Some(qd) = deps.get(q) else { continue; };
    seen.insert(q, true);
    for d in qd { if seen.get(d).is_none() { stack.push(d); } }
  }
  seen
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("packages.json")?.to_str();
  let doc = match text.parse_json() {
    Ok(j) => j,
    Err(_) => return Ok("error: not an object"),
  };
  let obj = match doc {
    Json::Obj(m) => m,
    _ => return Ok("error: not an object"),
  };
  let mut deps: Map<Str, List<Str>> = Map::new();
  let mut invalid: List<Str> = [];
  for name in obj.keys() {
    let v = obj.get(name).unwrap_or(Json::Null);
    match parse_deps(v) {
      Some(ds) => deps.insert(name, ds),
      None => invalid.push(name),
    }
  }
  let names = deps.keys();

  // reachability
  let mut reach: Map<Str, Map<Str, Bool>> = Map::new();
  for p in names { reach.insert(p, reach_from(deps, p)); }

  // cycles
  let mut in_cycle: Map<Str, Bool> = Map::new();
  let mut groups: Map<Str, List<Str>> = Map::new();
  for p in names {
    let rp = reach.get(p).unwrap_or(Map::new());
    if rp.get(p).is_none() { continue; }
    in_cycle.insert(p, true);
    let mut g: List<Str> = [];
    for q in names {
      if q == p { g.push(q); continue; }
      let rq = reach.get(q).unwrap_or(Map::new());
      if rp.get(q).is_some() && rq.get(p).is_some() { g.push(q); }
    }
    groups.insert(g[0], g);
  }

  // missing
  let mut missing: Map<Str, List<Str>> = Map::new();
  for p in names {
    let ds = deps.get(p).unwrap_or([]);
    for d in ds {
      if deps.get(d).is_none() {
        let mut l = missing.get(d).unwrap_or([]);
        if !l.contains(p) { l.push(p); }
        missing.insert(d, l);
      }
    }
  }

  // stages
  let mut stage: Map<Str, Int> = Map::new();
  let mut max_stage = 0;
  loop {
    let mut changed = false;
    for p in names {
      if stage.get(p).is_some() || in_cycle.get(p).is_some() { continue; }
      let ds = deps.get(p).unwrap_or([]);
      let mut ok = true;
      let mut mx = 0;
      for d in ds {
        match stage.get(d) {
          Some(s) => mx = mx.max(s),
          None => ok = false,
        }
      }
      if ok {
        stage.insert(p, mx + 1);
        max_stage = max_stage.max(mx + 1);
        changed = true;
      }
    }
    if !changed { break; }
  }

  let mut lines: List<Str> = [];
  for i in 1..max_stage + 1 {
    let mut ps: List<Str> = [];
    for p in names {
      if stage.get(p) == Some(i) { ps.push(p); }
    }
    if ps.len() > 0 { lines.push("stage " + i.to_str() + ": " + ps.join(", ")); }
  }
  for k in groups.keys() {
    let g = groups.get(k).unwrap_or([]);
    lines.push("cycle: " + g.join(", "));
  }
  for m in missing.keys() {
    let l = missing.get(m).unwrap_or([]);
    lines.push("missing: " + m + " (needed by " + l.join(", ") + ")");
  }
  if invalid.len() > 0 {
    invalid.sort();
    lines.push("invalid: " + invalid.join(", "));
  }
  let mut blocked: List<Str> = [];
  for p in names {
    if stage.get(p).is_none() && in_cycle.get(p).is_none() { blocked.push(p); }
  }
  if blocked.len() > 0 { lines.push("blocked: " + blocked.join(", ")); }
  lines.push("built " + stage.len().to_str() + " of " + names.len().to_str());
  Ok(lines.join("\n"))
}

struct Booking { s: Int, e: Int, who: Str }
struct Iv { s: Int, e: Int }
struct Conf { lo: Int, text: Str }

fn digit(b: Int) -> Bool { b >= 48 && b <= 57 }

fn parse_time(s: Str, allow24: Bool) -> Option<Int> {
  let b = s.to_bytes();
  if b.len() != 5 { return None; }
  if b[2] != 58 { return None; }
  if !digit(b[0]) || !digit(b[1]) || !digit(b[3]) || !digit(b[4]) { return None; }
  let h = (b[0] - 48) * 10 + (b[1] - 48);
  let m = (b[3] - 48) * 10 + (b[4] - 48);
  if allow24 && h == 24 && m == 0 { return Some(1440); }
  if h > 23 || m > 59 { return None; }
  Some(h * 60 + m)
}

fn two(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn fmt(t: Int) -> Str { two(t / 60) + ":" + two(t % 60) }

fn fmt_iv(s: Int, e: Int) -> Str { fmt(s) + "-" + fmt(e) }

fn day_report(bs: List<Booking>) -> List<Str> {
  let mut out: List<Str> = [];
  let mut sorted = bs;
  sorted.sort_by_key(|b: Booking| b.s);
  let mut merged: List<Iv> = [];
  for b in sorted {
    let n = merged.len();
    if n > 0 && b.s <= merged[n - 1].e {
      if b.e > merged[n - 1].e { merged[n - 1].e = b.e; }
    } else {
      merged.push(Iv { s: b.s, e: b.e });
    }
  }
  let mut busy: List<Str> = [];
  for iv in merged { busy.push(fmt_iv(iv.s, iv.e)); }
  out.push("  busy " + busy.join(", "));

  let mut free: List<Str> = [];
  let mut cur = 540;
  for iv in merged {
    if cur >= 1080 { break; }
    if iv.s > cur {
      let ge = iv.s.min(1080);
      if ge - cur >= 30 { free.push(fmt_iv(cur, ge)); }
    }
    cur = cur.max(iv.e);
  }
  if cur < 1080 && 1080 - cur >= 30 { free.push(fmt_iv(cur, 1080)); }
  if free.len() == 0 { out.push("  free none"); } else { out.push("  free " + free.join(", ")); }

  let mut confs: List<Conf> = [];
  let n = bs.len();
  for i in 0..n {
    for j in (i + 1)..n {
      let a = bs[i];
