        confs.push(Conf { lo: lo, text: "  conflict " + names + " " + fmt_iv(lo, hi) });
      }
    }
  }
  confs.sort_by(|x: Conf, y: Conf| x.lo < y.lo || (x.lo == y.lo && x.text < y.text));
  for c in confs { out.push(c.text); }
  out
}

