struct Bk { s: Int, e: Int, who: Str }
struct Iv { s: Int, e: Int }
struct Conf { s: Int, text: Str }

fn parse_time(t: Str, allow24: Bool) -> Option<Int> {
  let b = t.to_bytes();
  if b.len() != 5 { return None; }
  if b[2] != 58 { return None; }
  for i in [0, 1, 3, 4] {
    if b[i] < 48 || b[i] > 57 { return None; }
  }
  let h = (b[0] - 48) * 10 + (b[1] - 48);
  let m = (b[3] - 48) * 10 + (b[4] - 48);
  if h == 24 && m == 0 && allow24 { return Some(1440); }
  if h > 23 || m > 59 { return None; }
  Some(h * 60 + m)
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn fmt(m: Int) -> Str {
  pad2(m / 60) + ":" + pad2(m % 60)
}

fn fmt_iv(s: Int, e: Int) -> Str {
  fmt(s) + "-" + fmt(e)
}

fn report(bks: List<Bk>) -> List<Str> {
  let mut out: List<Str> = [];
  let mut sorted = bks;
  sorted.sort_by_key(|b| b.s);
  let mut merged: List<Iv> = [];
  for b in sorted {
    let n = merged.len();
    if n > 0 && b.s <= merged[n - 1].e {
      if b.e > merged[n - 1].e { merged[n - 1].e = b.e; }
    } else {
      merged.push(Iv { s: b.s, e: b.e });
    }
  }
  let busy = merged.map(|iv| fmt_iv(iv.s, iv.e));
  out.push("  busy " + busy.join(", "));

  let mut free: List<Str> = [];
  let mut cur = 540;
  for iv in merged {
    if cur >= 1080 { break; }
    if iv.s > cur {
      let ge = iv.s.min(1080);
      if ge - cur >= 30 { free.push(fmt_iv(cur, ge)); }
    }
    cur = cur.max(iv.e);
  }
  if cur < 1080 && 1080 - cur >= 30 { free.push(fmt_iv(cur, 1080)); }
  if free.len() == 0 {
    out.push("  free none");
  } else {
    out.push("  free " + free.join(", "));
  }

  let mut confs: List<Conf> = [];
  let n = bks.len();
  for i in 0..n {
    for j in (i + 1)..n {
      let a = bks[i];
      let b = bks[j];
      let os = a.s.max(b.s);
      let oe = a.e.min(b.e);
      if oe - os >= 1 {
        let names = if a.who <= b.who { a.who + "/" + b.who } else { b.who + "/" + a.who };
        confs.push(Conf { s: os, text: "  conflict " + names + " " + fmt_iv(os, oe) });
      }
    }
  }
  confs.sort_by(|x, y| x.s < y.s || (x.s == y.s && x.text < y.text));
  for c in confs { out.push(c.text); }
  out
}

