struct E { path: Str, msg: Str }

fn type_ok(t: Str, v: Json) -> Bool {
  match v {
    Json::Obj(_) => t == "object",
    Json::Arr(_) => t == "array",
    Json::Str(_) => t == "string",
    Json::Num(_) => t == "integer" || t == "number",
    Json::Float(_) => t == "number",
    Json::Bool(_) => t == "boolean",
    Json::Null => t == "null",
  }
}

fn get_int(s: Json, key: Str) -> Option<Int> {
  s.get(key).and_then(|j| j.as_int())
}

fn num_lt(v: Json, n: Int) -> Bool {
  match v {
    Json::Num(x) => x < n,
    Json::Float(f) => f < n.to_float(),
    _ => false,
  }
}

fn num_gt(v: Json, n: Int) -> Bool {
  match v {
    Json::Num(x) => x > n,
    Json::Float(f) => f > n.to_float(),
    _ => false,
  }
}

fn check(s: Json, v: Json, path: Str) -> List<E> {
  let mut out: List<E> = [];
  let t = s.get("type").and_then(|j| j.as_str()).unwrap_or("");
  if !type_ok(t, v) {
    out.push(E { path: path, msg: "expected " + t });
    return out;
  }
  if t == "object" {
    let m: Map<Str, Json> = v.as_map().unwrap_or(Map::new());
    let props: Map<Str, Json> = s.get("properties").and_then(|j| j.as_map()).unwrap_or(Map::new());
    let req: List<Json> = s.get("required").and_then(|j| j.as_list()).unwrap_or([]);
    let additional = s.get("additional").and_then(|j| j.as_bool()).unwrap_or(true);
    for r in req {
      if let Some(name) = r.as_str() {
        if m.get(name).is_none() {
          out.push(E { path: path + "." + name, msg: "missing required field" });
        }
      }
    }
    for k in m.keys() {
      let Some(fv) = m.get(k) else { continue; };
      match props.get(k) {
        Some(ps) => {
          for e in check(ps, fv, path + "." + k) { out.push(e); }
        }
        None => {
          if !additional {
            out.push(E { path: path + "." + k, msg: "unexpected field" });
          }
        }
      }
    }
  } else if t == "array" {
    let xs: List<Json> = v.as_list().unwrap_or([]);
    if let Some(mn) = get_int(s, "min_items") {
      if xs.len() < mn {
        out.push(E { path: path, msg: "fewer than " + mn.to_str() + " items" });
      }
    }
    if let Some(is) = s.get("items") {
      for i in 0..xs.len() {
        for e in check(is, xs[i], path + "[" + i.to_str() + "]") { out.push(e); }
      }
    }
  } else if t == "string" {
    let st = v.as_str().unwrap_or("");
    let n = st.chars().len();
    if let Some(a) = get_int(s, "min_length") {
      if n < a {
        out.push(E { path: path, msg: "shorter than " + a.to_str() });
        return out;
      }
    }
    if let Some(b) = get_int(s, "max_length") {
      if n > b {
        out.push(E { path: path, msg: "longer than " + b.to_str() });
        return out;
      }
    }
    if let Some(en) = s.get("enum").and_then(|j| j.as_list()) {
      if !en.any(|e| e.as_str() == Some(st)) {
        out.push(E { path: path, msg: "not in enum" });
        return out;
      }
    }
  } else if t == "integer" || t == "number" {
    if let Some(a) = get_int(s, "minimum") {
      if num_lt(v, a) {
        out.push(E { path: path, msg: "less than " + a.to_str() });
        return out;
      }
    }
    if let Some(b) = get_int(s, "maximum") {
      if num_gt(v, b) {
        out.push(E { path: path, msg: "greater than " + b.to_str() });
        return out;
      }
    }
  }
  out
}

fn run(input: Dir) -> Result<Str, Str> {
  let schema_text = input.read("schema.json").map_err(|e| "cannot read schema.json")?.to_str();
  let schema = schema_text.parse_json()?;
  let text = input.read("records.jsonl").map_err(|e| "cannot read records.jsonl")?.to_str();
  let lines = text.lines();
  let mut out: List<Str> = [];
  let mut valid = 0;
  let mut total = 0;
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    total += 1;
    let n = (i + 1).to_str();
    match line.parse_json() {
      Err(_) => out.push("line " + n + ": invalid JSON"),
      Ok(v) => {
        let mut errs = check(schema, v, "$");
        if errs.len() == 0 {
          valid += 1;
          out.push("line " + n + ": ok");
        } else {
          errs.sort_by(|a, b| a.path < b.path || (a.path == b.path && a.msg < b.msg));
          for e in errs {
            out.push("line " + n + ": " + e.path + ": " + e.msg);
          }
        }
      }
    }
  }
  out.push("valid " + valid.to_str() + " of " + total.to_str());
  Ok(out.join("\n"))
}

fn main(input: Dir) -> Result<Str, Str> {
  run(input)
}

struct Issue { path: Str, msg: Str }

fn type_ok(t: Str, v: Json) -> Bool {
  match v {
    Json::Null => t == "null",
    Json::Bool(_) => t == "boolean",
    Json::Num(_) => t == "integer" || t == "number",
    Json::Float(_) => t == "number",
    Json::Str(_) => t == "string",
    Json::Arr(_) => t == "array",
    Json::Obj(_) => t == "object",
  }
}

fn num_less(v: Json, b: Int) -> Bool {
  match v {
    Json::Num(n) => n < b,
    Json::Float(f) => f < b.to_float(),
    _ => false,
  }
}

fn num_greater(v: Json, b: Int) -> Bool {
  match v {
    Json::Num(n) => n > b,
    Json::Float(f) => f > b.to_float(),
    _ => false,
  }
}

fn validate(schema: Json, v: Json, path: Str, errs: List<Issue>) -> List<Issue> {
  let mut out = errs;
  let t = schema.get("type").and_then(|j| j.as_str()).unwrap_or("");
  if !type_ok(t, v) {
    out.push(Issue { path: path, msg: "expected " + t });
    return out;
  }
  if let Json::Obj(m) = v {
    let props: Map<Str, Json> = schema.get("properties").and_then(|j| j.as_map()).unwrap_or(Map::new());
    let reqs: List<Json> = schema.get("required").and_then(|j| j.as_list()).unwrap_or([]);
    let additional = schema.get("additional").and_then(|j| j.as_bool()).unwrap_or(true);
    for r in reqs {
      if let Some(name) = r.as_str() {
        if m.get(name).is_none() {
          out.push(Issue { path: path + "." + name, msg: "missing required field" });
        }
      }
    }
    for k in m.keys() {
      let Some(fv) = m.get(k) else { continue; };
      if let Some(ps) = props.get(k) {
        out = validate(ps, fv, path + "." + k, out);
      } else if !additional {
        out.push(Issue { path: path + "." + k, msg: "unexpected field" });
      }
    }
  } else if let Json::Arr(xs) = v {
    if let Some(mn) = schema.get("min_items").and_then(|j| j.as_int()) {
      if xs.len() < mn {
        out.push(Issue { path: path, msg: "fewer than " + mn.to_str() + " items" });
      }
    }
    if let Some(is) = schema.get("items") {
      let mut i = 0;
      for x in xs {
        out = validate(is, x, path + "[" + i.to_str() + "]", out);
        i += 1;
      }
    }
  } else if let Json::Str(s) = v {
    let n = s.chars().len();
    let mut msg = "";
    if let Some(mn) = schema.get("min_length").and_then(|j| j.as_int()) {
      if n < mn { msg = "shorter than " + mn.to_str(); }
    }
    if msg == "" {
      if let Some(mx) = schema.get("max_length").and_then(|j| j.as_int()) {
        if n > mx { msg = "longer than " + mx.to_str(); }
      }
    }
    if msg == "" {
      if let Some(en) = schema.get("enum").and_then(|j| j.as_list()) {
        if !en.contains(Json::Str(s)) { msg = "not in enum"; }
      }
    }
    if msg != "" { out.push(Issue { path: path, msg: msg }); }
  } else if t == "integer" || t == "number" {
    let mut msg = "";
    if let Some(mn) = schema.get("minimum").and_then(|j| j.as_int()) {
      if num_less(v, mn) { msg = "less than " + mn.to_str(); }
    }
    if msg == "" {
      if let Some(mx) = schema.get("maximum").and_then(|j| j.as_int()) {
        if num_greater(v, mx) { msg = "greater than " + mx.to_str(); }
      }
    }
    if msg != "" { out.push(Issue { path: path, msg: msg }); }
  }
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let schema_text = input.read("schema.json")?.to_str();
  let schema = match schema_text.parse_json() {
    Ok(j) => j,
    Err(e) => { return Ok("invalid schema: " + e); }
  };
  let text = input.read("records.jsonl")?.to_str();
  let mut lines: List<Str> = [];
  let mut valid = 0;
  let mut total = 0;
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    if line.trim().len() == 0 { continue; }
    total += 1;
    let prefix = "line " + n.to_str() + ": ";
    match line.parse_json() {
      Err(_) => lines.push(prefix + "invalid JSON"),
      Ok(v) => {
        let mut errs = validate(schema, v, "$", []);
        if errs.len() == 0 {
          valid += 1;
          lines.push(prefix + "ok");
        } else {
          errs.sort_by(|a, b| a.path < b.path || (a.path == b.path && a.msg < b.msg));
          for e in errs {
            lines.push(prefix + e.path + ": " + e.msg);
          }
        }
      }
    }
  }
  lines.push("valid " + valid.to_str() + " of " + total.to_str());
  Ok(lines.join("\n"))
}

