      let reqs = s.get("required").and_then(|j| j.as_list()).unwrap_or(noreq);
      for r in reqs {
        if let Some(name) = r.as_str() {
          if m.get(name).is_none() {
            out.push(E { path: path + "." + name, msg: "missing required field" });
          }
        }
      }
      let additional = s.get("additional").and_then(|j| j.as_bool()).unwrap_or(true);
      for k in m.keys() {
        let Some(fv) = m.get(k) else { continue; };
        match props.get(k) {
          Some(ps) => {
            let sub = validate(ps, fv, path + "." + k);
            for e in sub { out.push(e); }
          }
          None => {
            if !additional {
              out.push(E { path: path + "." + k, msg: "unexpected field" });
            }
          }
        }
      }
    }
    Json::Arr(xs) => {
      if let Some(n) = get_int(s, "min_items") {
        if xs.len() < n {
          out.push(E { path: path, msg: "fewer than " + n.to_str() + " items" });
        }
      }
      if let Some(is) = s.get("items") {
        for i in 0..xs.len() {
          let sub = validate(is, xs[i], path + "[" + i.to_str() + "]");
          for e in sub { out.push(e); }
        }
      }
    }
    Json::Str(x) => {
      let n = x.chars().len();
      let mn = get_int(s, "min_length");
      let mx = get_int(s, "max_length");
      let en = s.get("enum").and_then(|j| j.as_list());
      let mut msg = "";
      if let Some(a) = mn {
        if n < a { msg = "shorter than " + a.to_str(); }
      }
      if msg == "" {
        if let Some(b) = mx {
          if n > b { msg = "longer than " + b.to_str(); }
        }
      }
      if msg == "" {
        if let Some(l) = en {
          if !l.contains(Json::Str(x)) { msg = "not in enum"; }
        }
      }
      if msg != "" { out.push(E { path: path, msg: msg }); }
    }
    Json::Num(n) => {
      let mut msg = "";
      if let Some(a) = get_int(s, "minimum") {
        if n < a { msg = "less than " + a.to_str(); }
      }
      if msg == "" {
        if let Some(b) = get_int(s, "maximum") {
          if n > b { msg = "greater than " + b.to_str(); }
        }
      }
      if msg != "" { out.push(E { path: path, msg: msg }); }
    }
    Json::Float(f) => {
      let mut msg = "";
      if let Some(a) = get_int(s, "minimum") {
        if f < a.to_float() { msg = "less than " + a.to_str(); }
      }
      if msg == "" {
        if let Some(b) = get_int(s, "maximum") {
          if f > b.to_float() { msg = "greater than " + b.to_str(); }
        }
      }
      if msg != "" { out.push(E { path: path, msg: msg }); }
    }
    _ => {}
  }
  out
}

fn less(a: E, b: E) -> Bool {
  if a.path != b.path { a.path < b.path } else { a.msg < b.msg }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let schema_text = input.read("schema.json")?.to_str();
  let schema = match schema_text.parse_json() {
    Ok(j) => j,
    Err(e) => { return Ok("invalid schema: " + e); }
  };
  let text = input.read("records.jsonl")?.to_str();
  let lines = text.lines();
  let mut out: List<Str> = [];
  let mut valid = 0;
  let mut total = 0;
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim().len() == 0 { continue; }
    total += 1;
    let n = (i + 1).to_str();
    match line.parse_json() {
      Err(_) => out.push("line " + n + ": invalid JSON"),
      Ok(v) => {
        let mut errs = validate(schema, v, "$");
        if errs.len() == 0 {
          valid += 1;
          out.push("line " + n + ": ok");
        } else {
          errs.sort_by(less);
          for e in errs {
            out.push("line " + n + ": " + e.path + ": " + e.msg);
          }
        }
      }
    }
  }
  out.push("valid " + valid.to_str() + " of " + total.to_str());
  Ok(out.join("\n"))
}

