}

fn last_version(state: Kv, id: Str) -> Result<Option<Int>, Str> {
  let v = state.get("v:" + id).map_err(kv_err)?;
  match v {
    Some(b) => Ok(b.to_str().parse_int()),
    None => Ok(None),
  }
}

fn send_round(api: Http, ids: List<Str>, recs: Map<Str, Rec>) -> List<Result<HttpResponse, HttpErr>> {
  let mut out: List<Result<HttpResponse, HttpErr>> = [];
  let mut i = 0;
  while i < ids.len() {
    let end = (i + 64).min(ids.len());
    let mut reqs: List<HttpRequest> = [];
    for k in i..end {
      let id = ids[k];
      let body = match recs.get(id) {
        Some(r) => r.body,
        None => "",
      };
      reqs.push(HttpRequest {
        method: "PUT",
        path: "/records/" + id,
        headers: ["content-type: application/json"],
        body: body.to_bytes(),
        timeout_ms: 0,
      });
    }
    let res = api.send_all(reqs);
    for r in res { out.push(r); }
    i = end;
  }
  out
}

fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Str> {
  let text = match input.read("records.jsonl") {
    Ok(b) => b.to_str(),
    Err(_) => return Err("cannot read records.jsonl"),
  };
  let mut out = "";
  let mut recs: Map<Str, Rec> = Map::new();
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    let t = line.trim();
    if t.len() == 0 { continue; }
    match parse_rec(t) {
      Some(r) => recs.insert(r.id, r),
      None => out = out + "line " + n.to_str() + " invalid\n",
    }
  }

  let mut status: Map<Str, Str> = Map::new();
  let mut pending: List<Str> = [];
  for id in recs.keys() {
    let Some(r) = recs.get(id) else { continue; };
    let last = last_version(state, id)?;
    let push = match last {
      Some(v) => r.version > v,
      None => true,
    };
    if push { pending.push(id); } else { status.insert(id, "unchanged"); }
  }

  let mut attempt = 0;
  while attempt < 3 && pending.len() > 0 {
    attempt += 1;
    let res = send_round(api, pending, recs);
    let mut next: List<Str> = [];
    for k in 0..pending.len() {
      let id = pending[k];
      let mut retry = false;
      match res[k] {
        Ok(resp) => {
          if resp.status >= 200 && resp.status < 300 {
            status.insert(id, "synced");
            let Some(r) = recs.get(id) else { continue; };
            state.set("v:" + id, r.version.to_str().to_bytes()).map_err(kv_err)?;
          } else if resp.status >= 400 && resp.status < 500 {
            status.insert(id, "rejected " + resp.status.to_str());
          } else {
            retry = true;
          }
        }
        Err(_) => retry = true,
      }
      if retry {
        if attempt < 3 { next.push(id); } else { status.insert(id, "failed"); }
      }
    }
    pending = next;
  }

  let mut s = 0;
  let mut u = 0;
  let mut rj = 0;
  let mut f = 0;
  for id in status.keys() {
    let st = status.get(id).unwrap_or("");
    out = out + id + " " + st + "\n";
    if st == "synced" { s += 1; }
    else if st == "unchanged" { u += 1; }
    else if st == "failed" { f += 1; }
    else { rj += 1; }
  }
  out = out + "synced " + s.to_str() + " unchanged " + u.to_str() + " rejected " + rj.to_str() + " failed " + f.to_str();
  Ok(out)
}

