fn hexdigit(n: Int) -> Int {
  if n < 10 { 48 + n } else { 55 + n }
}

fn encode(id: Str) -> Str {
  let mut out = "".to_bytes();
  for b in id.to_bytes() {
    let ok = (b >= 48 && b <= 57) || (b >= 65 && b <= 90) || (b >= 97 && b <= 122)
      || b == 45 || b == 46 || b == 95 || b == 126;
    if ok {
      out.push(b);
    } else {
      out.push(37);
      out.push(hexdigit(b / 16));
      out.push(hexdigit(b % 16));
    }
  }
  out.to_str()
}

