fn enc(s: Str) -> Str {
  let hex = "0123456789ABCDEF".chars();
  let mut out = "";
  for b in s.to_bytes() {
    let plain = (b >= 48 && b <= 57) || (b >= 65 && b <= 90) || (b >= 97 && b <= 122)
      || b == 45 || b == 46 || b == 95 || b == 126;
    if plain {
      let mut one: Bytes = "".to_bytes();
      one.push(b);
      out = out + one.to_str();
    } else {
      out = out + "%" + hex[b / 16] + hex[b % 16];
    }
  }
  out
}

