const MAX: Int = 9223372036854775807;

struct Acct { balance: Int, last: Int, closed: Bool }

enum Outcome { Done, Fail(Str), Dup }

fn dberr(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(s) => "db invalid: " + s,
    DbErr::Denied => "db denied",
    DbErr::Busy => "db busy",
    DbErr::TooLarge => "db too large",
    DbErr::Constraint(s) => "db constraint: " + s,
  }
}

fn ioerr(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "ops.txt not found",
    IoErr::Denied => "read denied",
    IoErr::TooLarge => "file too large",
    IoErr::InvalidPath => "invalid path",
    IoErr::Exists => "exists",
  }
}

fn logerr(e: LogErr) -> Str {
  match e {
    LogErr::TooLarge => "log too large",
  }
}

fn get_int(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(n) => n,
    _ => 0,
  }
}

fn get_str(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn pad(n: Int, w: Int) -> Str {
  let mut s = n.to_str();
  while s.len() < w { s = "0" + s; }
  s
}

fn fmt_time(ms: Int) -> Str {
  let mut secs = ms / 1000;
  if ms % 1000 < 0 { secs = secs - 1; }
  let mut days = secs / 86400;
  let mut rem = secs % 86400;
  if rem < 0 { rem = rem + 86400; days = days - 1; }
  let z = days + 719468;
  let mut era = z / 146097;
  if z < 0 && z % 146097 != 0 { era = era - 1; }
  let doe = z - era * 146097;
  let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
  let mut y = yoe + era * 400;
  let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
  let mp = (5 * doy + 2) / 153;
  let d = doy - (153 * mp + 2) / 5 + 1;
  let m = if mp < 10 { mp + 3 } else { mp - 9 };
  if m <= 2 { y = y + 1; }
  let hh = rem / 3600;
  let mm = (rem % 3600) / 60;
  let ss = rem % 60;
  pad(y, 4) + "-" + pad(m, 2) + "-" + pad(d, 2) + "T" + pad(hh, 2) + ":" + pad(mm, 2) + ":" + pad(ss, 2) + "Z"
}

fn find_acct(db: Db, name: Str) -> Result<Option<Acct>, Str> {
  let rows = db.query("SELECT balance, last, closed FROM accounts WHERE name = ?", [SqlValue::Text(name)]).map_err(dberr)?;
  if rows.len() == 0 { return Ok(None); }
  let r = rows[0];
  Ok(Some(Acct { balance: get_int(r[0]), last: get_int(r[1]), closed: get_int(r[2]) != 0 }))
}

fn live_acct(db: Db, name: Str) -> Result<Option<Acct>, Str> {
  let a = find_acct(db, name)?;
  match a {
    Some(x) => if x.closed { Ok(None) } else { Ok(Some(x)) },
    None => Ok(None),
  }
}

fn do_open(db: Db, words: List<Str>, now: Int) -> Result<Outcome, Str> {
  if words.len() != 3 { return Ok(Outcome::Fail("malformed")); }
  let Some(c) = words[2].parse_int() else { return Ok(Outcome::Fail("malformed")); };
  if c < 0 { return Ok(Outcome::Fail("bad amount")); }
  let name = words[1];
  if find_acct(db, name)?.is_some() { return Ok(Outcome::Fail("account exists")); }
  db.exec("INSERT INTO accounts (name, balance, last, closed) VALUES (?, ?, ?, 0)",
    [SqlValue::Text(name), SqlValue::Int(c), SqlValue::Int(now)]).map_err(dberr)?;
  Ok(Outcome::Done)
}

fn do_transfer(db: Db, words: List<Str>, now: Int) -> Result<Outcome, Str> {
  if words.len() != 5 { return Ok(Outcome::Fail("malformed")); }
  let Some(c) = words[4].parse_int() else { return Ok(Outcome::Fail("malformed")); };
  let id = words[1];
  let from = words[2];
  let to = words[3];
  let rows = db.query("SELECT src, dst, cents FROM transfers WHERE id = ?", [SqlValue::Text(id)]).map_err(dberr)?;
  if rows.len() > 0 {
    let r = rows[0];
    if get_str(r[0]) == from && get_str(r[1]) == to && get_int(r[2]) == c {
      return Ok(Outcome::Dup);
    }
    return Ok(Outcome::Fail("id reused"));
  }
  if c <= 0 { return Ok(Outcome::Fail("bad amount")); }
  if from == to { return Ok(Outcome::Fail("same account")); }
  let Some(fa) = live_acct(db, from)? else { return Ok(Outcome::Fail("no account " + from)); };
  let Some(ta) = live_acct(db, to)? else { return Ok(Outcome::Fail("no account " + to)); };
  if fa.balance < c { return Ok(Outcome::Fail("insufficient funds")); }
  if ta.balance > MAX - c { return Ok(Outcome::Fail("overflow")); }
  db.transaction(
    ["UPDATE accounts SET balance = balance - ?, last = ? WHERE name = ?",
     "UPDATE accounts SET balance = balance + ?, last = ? WHERE name = ?",
     "INSERT INTO transfers (id, src, dst, cents) VALUES (?, ?, ?, ?)"],
    [[SqlValue::Int(c), SqlValue::Int(now), SqlValue::Text(from)],
     [SqlValue::Int(c), SqlValue::Int(now), SqlValue::Text(to)],
     [SqlValue::Text(id), SqlValue::Text(from), SqlValue::Text(to), SqlValue::Int(c)]]).map_err(dberr)?;
  Ok(Outcome::Done)
}

fn do_close(db: Db, words: List<Str>) -> Result<Outcome, Str> {
  if words.len() != 2 { return Ok(Outcome::Fail("malformed")); }
  let name = words[1];
  let Some(a) = live_acct(db, name)? else { return Ok(Outcome::Fail("no account " + name)); };
  if a.balance != 0 { return Ok(Outcome::Fail("balance not zero")); }
  db.exec("UPDATE accounts SET closed = 1 WHERE name = ?", [SqlValue::Text(name)]).map_err(dberr)?;
  Ok(Outcome::Done)
}

fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Str> {
  let text = input.read("ops.txt").map_err(ioerr)?.to_str();
  db.exec("CREATE TABLE IF NOT EXISTS accounts (name TEXT PRIMARY KEY, balance INTEGER NOT NULL, last INTEGER NOT NULL, closed INTEGER NOT NULL)", []).map_err(dberr)?;
  db.exec("CREATE TABLE IF NOT EXISTS transfers (id TEXT PRIMARY KEY, src TEXT NOT NULL, dst TEXT NOT NULL, cents INTEGER NOT NULL)", []).map_err(dberr)?;
  let now = clock.now_ms();
  let ts = fmt_time(now);
  let mut ok = 0;
  let mut failed = 0;
  let mut dup = 0;
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    if line.trim() == "" { continue; }
    let words = line.split(" ");
    let outcome = match words[0] {
      "open" => do_open(db, words, now)?,
      "transfer" => do_transfer(db, words, now)?,
      "close" => do_close(db, words)?,
      _ => Outcome::Fail("malformed"),
    };
    match outcome {
      Outcome::Done => ok += 1,
      Outcome::Dup => dup += 1,
      Outcome::Fail(msg) => {
        failed += 1;
        log.write(ts + " line " + n.to_str() + ": " + msg).map_err(logerr)?;
      }
    }
  }
  let mut out: List<Str> = ["ok " + ok.to_str() + " failed " + failed.to_str() + " duplicate " + dup.to_str()];
  let rows = db.query("SELECT name, balance, last FROM accounts WHERE closed = 0 ORDER BY name", []).map_err(dberr)?;
  for r in rows {
    out.push(get_str(r[0]) + " " + get_int(r[1]).to_str() + " last " + fmt_time(get_int(r[2])));
  }
  Ok(out.join("\n"))
}

const SESS_MS: Int = 1800000;
const LOCK_MS: Int = 900000;

struct User { hash: Str, fails: Int, locked_until: Int, logins: Int }
struct Creds { name: Str, password: Str }
struct Session { name: Str, exp: Int }

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 { i += 1; continue; }
    let mut need = 0;
    let mut lo = 128;
    let mut hi = 191;
    if c >= 194 && c <= 223 { need = 1; }
    else if c == 224 { need = 2; lo = 160; }
    else if c == 237 { need = 2; hi = 159; }
    else if c >= 225 && c <= 239 { need = 2; }
    else if c == 240 { need = 3; lo = 144; }
    else if c >= 241 && c <= 243 { need = 3; }
    else if c == 244 { need = 3; hi = 143; }
    else { return false; }
    if i + need >= n { return false; }
    let first = b[i + 1];
    if first < lo || first > hi { return false; }
    let end = need + 1;
    for k in 2..end {
      let x = b[i + k];
      if x < 128 || x > 191 { return false; }
    }
    i += need + 1;
  }
  true
}

fn valid_name(name: Str) -> Bool {
  if name.len() < 3 || name.len() > 20 { return false; }
  let allowed = "abcdefghijklmnopqrstuvwxyz0123456789_";
  for c in name.chars() {
    if !allowed.contains(c) { return false; }
  }
  true
}

fn hash_pw(name: Str, pw: Str) -> Str {
  ("kio-acct:" + name + ":" + pw).sha256().to_hex()
}

fn parse_creds(body: Bytes) -> Option<Creds> {
  if !valid_utf8(body) { return None; }
  let j = body.to_str().parse_json().ok()?;
  let name = j.get("name")?.as_str()?;
  let password = j.get("password")?.as_str()?;
  Some(Creds { name: name, password: password })
}

fn user_to_bytes(u: User) -> Bytes {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("hash", Json::Str(u.hash));
  m.insert("fails", Json::Num(u.fails));
  m.insert("locked_until", Json::Num(u.locked_until));
  m.insert("logins", Json::Num(u.logins));
  Json::Obj(m).to_json().to_bytes()
}

fn user_from(b: Bytes) -> Option<User> {
  if !valid_utf8(b) { return None; }
  let j = b.to_str().parse_json().ok()?;
  Some(User {
    hash: j.get("hash")?.as_str()?,
    fails: j.get("fails")?.as_int()?,
    locked_until: j.get("locked_until")?.as_int()?,
    logins: j.get("logins")?.as_int()?,
  })
}

fn sess_to_bytes(s: Session) -> Bytes {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(s.name));
  m.insert("exp", Json::Num(s.exp));
  Json::Obj(m).to_json().to_bytes()
}

fn sess_from(b: Bytes) -> Option<Session> {
  if !valid_utf8(b) { return None; }
  let j = b.to_str().parse_json().ok()?;
  Some(Session { name: j.get("name")?.as_str()?, exp: j.get("exp")?.as_int()? })
}

fn obj1(k: Str, v: Json) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(k, v);
  Json::Obj(m)
}

fn reply(res: Outgoing, status: Int, body: Json) {
  let _r = res.send(status, ["content-type"], ["application/json"], body.to_json().to_bytes());
}

fn err(res: Outgoing, status: Int, msg: Str) {
  reply(res, status, obj1("error", Json::Str(msg)));
}

fn bearer(req: Incoming) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  for i in 0..names.len() {
    if names[i] == "authorization" && i < values.len() {
      let v = values[i].trim();
      let t = v.strip_prefix("Bearer ")?.trim();
      if t.len() == 32 { return Some(t); }
      return None;
    }
  }
  None
}

fn create_user(req: Incoming, res: Outgoing, store: Kv) -> Result<(), KvErr> {
  let Some(c) = parse_creds(req.body()) else { err(res, 400, "invalid"); return Ok(()); };
  if !valid_name(c.name) || c.password.len() < 8 {
    err(res, 400, "invalid");
    return Ok(());
  }
  let u = User { hash: hash_pw(c.name, c.password), fails: 0, locked_until: 0, logins: 0 };
  let ok = store.swap("user:" + c.name, None, Some(user_to_bytes(u)))?;
  if !ok {
    err(res, 409, "name taken");
  } else {
    reply(res, 201, obj1("name", Json::Str(c.name)));
  }
  Ok(())
}

fn login(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Result<(), KvErr> {
  let Some(c) = parse_creds(req.body()) else { err(res, 401, "bad credentials"); return Ok(()); };
  if !valid_name(c.name) { err(res, 401, "bad credentials"); return Ok(()); }
  let key = "user:" + c.name;
  loop {
    let Some(b) = store.get(key)? else { err(res, 401, "bad credentials"); return Ok(()); };
    let Some(u) = user_from(b) else { err(res, 401, "bad credentials"); return Ok(()); };
    let now = clock.now_ms();
    if now < u.locked_until {
      err(res, 429, "locked");
      return Ok(());
    }
    let h = hash_pw(c.name, c.password);
    if !h.ct_eq(u.hash) {
      let fails = u.fails + 1;
      let nu = if fails >= 3 {
        User { fails: 0, locked_until: now + LOCK_MS, ..u }
      } else {
        User { fails: fails, ..u }
      };
      let ok = store.swap(key, Some(b), Some(user_to_bytes(nu)))?;
      if !ok { continue; }
      err(res, 401, "bad credentials");
      return Ok(());
    }
    let nu = User { fails: 0, logins: u.logins + 1, ..u };
    let ok = store.swap(key, Some(b), Some(user_to_bytes(nu)))?;
    if !ok { continue; }
    let token = rng.bytes(16).to_hex();
    let s = Session { name: c.name, exp: now + SESS_MS };
    store.set("sess:" + token, sess_to_bytes(s))?;
    let mut m: Map<Str, Json> = Map::new();
    m.insert("token", Json::Str(token));
    m.insert("expires_in", Json::Num(1800));
    reply(res, 200, Json::Obj(m));
    return Ok(());
  }
}

fn me(req: Incoming, res: Outgoing, store: Kv, clock: Clock) -> Result<(), KvErr> {
  let Some(token) = bearer(req) else { err(res, 401, "unauthorized"); return Ok(()); };
  let key = "sess:" + token;
  loop {
    let Some(b) = store.get(key)? else { err(res, 401, "unauthorized"); return Ok(()); };
    let Some(s) = sess_from(b) else { err(res, 401, "unauthorized"); return Ok(()); };
    let now = clock.now_ms();
    if now >= s.exp {
      store.delete(key)?;
      err(res, 401, "unauthorized");
      return Ok(());
    }
    let ns = Session { exp: now + SESS_MS, ..s };
    let ok = store.swap(key, Some(b), Some(sess_to_bytes(ns)))?;
    if !ok { continue; }
    let mut logins = 0;
    if let Some(ub) = store.get("user:" + s.name)? {
      if let Some(u) = user_from(ub) { logins = u.logins; }
    }
    let mut m: Map<Str, Json> = Map::new();
    m.insert("name", Json::Str(s.name));
    m.insert("logins", Json::Num(logins));
    reply(res, 200, Json::Obj(m));
    return Ok(());
  }
}

fn logout(req: Incoming, res: Outgoing, store: Kv, clock: Clock) -> Result<(), KvErr> {
  let Some(token) = bearer(req) else { err(res, 401, "unauthorized"); return Ok(()); };
  let key = "sess:" + token;
  let Some(b) = store.get(key)? else { err(res, 401, "unauthorized"); return Ok(()); };
  let Some(s) = sess_from(b) else { err(res, 401, "unauthorized"); return Ok(()); };
  let now = clock.now_ms();
  store.delete(key)?;
  if now >= s.exp {
    err(res, 401, "unauthorized");
    return Ok(());
  }
  let _r = res.send(204, [], [], "".to_bytes());
  Ok(())
}

fn handle(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Result<(), KvErr> {
  let t = req.target();
  let path = match t.find("?") { Some(i) => t.slice(0, i), None => t };
  let method = req.method();
  if method == "POST" && path == "/users" {
    create_user(req, res, store)
  } else if method == "POST" && path == "/login" {
    login(req, res, store, clock, rng)
  } else if method == "GET" && path == "/me" {
    me(req, res, store, clock)
  } else if method == "POST" && path == "/logout" {
    logout(req, res, store, clock)
  } else {
    err(res, 404, "not found");
    Ok(())
  }
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Str {
  match handle(req, res, store, clock, rng) {
    Ok(()) => "ok",
    Err(_) => {
      err(res, 500, "internal");
      "error"
    }
  }
}

