fn col_int(v: SqlValue) -> Int { match v { SqlValue::Int(n) => n, _ => 0 } }
fn col_str(v: SqlValue) -> Str { match v { SqlValue::Text(s) => s, _ => "" } }

fn row_pay(r: List<SqlValue>) -> Pay {
  Pay { id: col_int(r[0]), account: col_str(r[1]), cents: col_int(r[2]), currency: col_str(r[3]), status: col_str(r[4]), refunded: col_int(r[5]) }
}

