}

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 { i += 1; continue; }
    let mut need = 0;
    let mut min = 0;
    let mut cp = 0;
    if c >= 194 && c <= 223 { need = 1; min = 128; cp = c - 192; }
    else if c >= 224 && c <= 239 { need = 2; min = 2048; cp = c - 224; }
    else if c >= 240 && c <= 244 { need = 3; min = 65536; cp = c - 240; }
    else { return false; }
    if i + need >= n { return false; }
    for k in 1..need + 1 {
      let d = b[i + k];
      if d < 128 || d > 191 { return false; }
      cp = cp * 64 + (d - 128);
    }
    if cp < min || cp > 1114111 || (cp >= 55296 && cp <= 57343) { return false; }
    i += need + 1;
  }
  true
}

fn utf8_str(b: Bytes) -> Option<Str> {
  if valid_utf8(b) { Some(b.to_str()) } else { None }
}

fn hexval(b: Int) -> Int {
  if b >= 48 && b <= 57 { b - 48 }
  else if b >= 97 && b <= 102 { b - 87 }
  else if b >= 65 && b <= 70 { b - 55 }
  else { -1 }
}

fn pct_decode(s: Str) -> Option<Str> {
  let b = s.to_bytes();
  let mut out = "".to_bytes();
  let mut i = 0;
  while i < b.len() {
    let c = b[i];
    if c == 37 && i + 2 < b.len() {
      let h = hexval(b[i + 1]);
      let l = hexval(b[i + 2]);
      if h >= 0 && l >= 0 { out.push(h * 16 + l); i += 3; continue; }
    }
    if c == 43 { out.push(32); } else { out.push(c); }
    i += 1;
  }
  utf8_str(out)
}

fn query_param(q: Str, name: Str) -> Option<Str> {
  for part in q.split("&") {
    let mut k = part;
    let mut v = "";
    if let Some(i) = part.find("=") {
      k = part.slice(0, i);
      v = part.slice(i + 1, part.len());
    }
    if pct_decode(k) == Some(name) { return pct_decode(v); }
  }
  None
}

fn parse_id(s: Str) -> Option<Int> {
  let n = s.strip_prefix("pay_")?.parse_int()?;
  if n <= 0 || "pay_" + n.to_str() != s { return None; }
  Some(n)
}

fn idem_key(req: Incoming) -> Str {
  let names = req.header_names();
  let vals = req.header_values();
  for i in 0..names.len() {
    if names[i] == "idempotency-key" && i < vals.len() { return vals[i]; }
  }
  ""
}

fn canon_of(raw: Bytes) -> Str {
  match utf8_str(raw) {
    Some(s) => match s.parse_json() {
      Ok(j) => "json:" + j.to_json(),
      Err(_) => "text:" + s,
    },
    None => "hex:" + raw.to_hex(),
  }
}

fn idem_check(db: Db, key: Str, method: Str, path: Str, canon: Str) -> Result<Option<Resp>, DbErr> {
  let rows = db.query("SELECT method, path, body, status, resp FROM idem WHERE key = ?", [SqlValue::Text(key)])?;
  if rows.len() == 0 { return Ok(None); }
  let r = rows[0];
  if col_str(r[0]) == method && col_str(r[1]) == path && col_str(r[2]) == canon {
    Ok(Some(Resp { status: col_int(r[3]), body: col_str(r[4]) }))
  } else {
    Ok(Some(fail(409, "key reused")))
  }
}

fn idem_store(db: Db, key: Str, method: Str, path: Str, canon: Str, r: Resp) -> Result<(), DbErr> {
  db.exec("INSERT OR IGNORE INTO idem (key, method, path, body, status, resp) VALUES (?, ?, ?, ?, ?, ?)",
    [SqlValue::Text(key), SqlValue::Text(method), SqlValue::Text(path), SqlValue::Text(canon), SqlValue::Int(r.status), SqlValue::Text(r.body)])?;
  Ok(())
}

fn create(db: Db, key: Str, path: Str, canon: Str, text: Option<Str>) -> Result<Resp, DbErr> {
  if let Some(r) = idem_check(db, key, "POST", path, canon)? { return Ok(r); }
  let inv = fail(422, "invalid payment");
  let Some(t) = text else { return Ok(inv); };
  let Ok(j) = t.parse_json() else { return Ok(inv); };
  let Some(m) = j.as_map() else { return Ok(inv); };
  if m.len() != 3 { return Ok(inv); }
  let Some(Json::Str(account)) = m.get("account") else { return Ok(inv); };
  if account.len() == 0 { return Ok(inv); }
  let Some(Json::Num(cents)) = m.get("cents") else { return Ok(inv); };
  if cents <= 0 { return Ok(inv); }
  let Some(Json::Str(cur)) = m.get("currency") else { return Ok(inv); };
  if cur != "EUR" && cur != "USD" { return Ok(inv); }
  let ins = db.exec("INSERT INTO payments (account, cents, currency, status, refunded, ikey) VALUES (?, ?, ?, 'pending', 0, ?)",
    [SqlValue::Text(account), SqlValue::Int(cents), SqlValue::Text(cur), SqlValue::Text(key)]);
  match ins {
    Ok(_) => {}
    Err(DbErr::Constraint(_)) => {
      if let Some(r) = idem_check(db, key, "POST", path, canon)? { return Ok(r); }
      return Ok(fail(409, "key reused"));
    }
    Err(e) => return Err(e),
  }
  let rows = db.query("SELECT id, account, cents, currency, status, refunded FROM payments WHERE ikey = ?", [SqlValue::Text(key)])?;
  if rows.len() == 0 { return Ok(fail(500, "internal error")); }
  let r = Resp { status: 201, body: pay_json(row_pay(rows[0])).to_json() };
  idem_store(db, key, "POST", path, canon, r)?;
  Ok(r)
}

fn refund_cents(text: Option<Str>) -> Option<Int> {
  let t = text?;
  let j = t.parse_json().ok()?;
  let Some(Json::Num(n)) = j.get("cents") else { return None; };
  if n <= 0 { return None; }
  Some(n)
}

fn refund(db: Db, id: Option<Int>, key: Str, path: Str, canon: Str, text: Option<Str>) -> Result<Resp, DbErr> {
  if let Some(r) = idem_check(db, key, "POST", path, canon)? { return Ok(r); }
  let Some(pid) = id else { return Ok(nf()); };
  let Some(p) = get_pay(db, pid)? else { return Ok(nf()); };
  let Some(n) = refund_cents(text) else { return Ok(fail(422, "invalid refund")); };
  let mut changed = 0;
  if n <= p.cents {
    changed = db.exec("UPDATE payments SET refunded = refunded + ?, status = CASE WHEN refunded + ? = cents THEN 'refunded' ELSE status END WHERE id = ? AND status = 'captured' AND refunded + ? <= cents",
      [SqlValue::Int(n), SqlValue::Int(n), SqlValue::Int(pid), SqlValue::Int(n)])?;
  }
  let Some(q) = get_pay(db, pid)? else { return Ok(nf()); };
  if changed == 0 {
    if q.status != "captured" { return Ok(fail(409, "invalid transition")); }
    return Ok(fail(409, "exceeds captured"));
  }
  let r = Resp { status: 200, body: pay_json(q).to_json() };
  idem_store(db, key, "POST", path, canon, r)?;
  Ok(r)
}

fn capture(db: Db, id: Option<Int>) -> Result<Resp, DbErr> {
  let Some(pid) = id else { return Ok(nf()); };
  db.exec("UPDATE payments SET status = 'captured' WHERE id = ? AND status = 'pending'", [SqlValue::Int(pid)])?;
  let Some(p) = get_pay(db, pid)? else { return Ok(nf()); };
  if p.status == "captured" { Ok(Resp { status: 200, body: pay_json(p).to_json() }) } else { Ok(fail(409, "invalid transition")) }
}

fn cancel(db: Db, id: Option<Int>) -> Result<Resp, DbErr> {
  let Some(pid) = id else { return Ok(nf()); };
  let n = db.exec("UPDATE payments SET status = 'canceled' WHERE id = ? AND status = 'pending'", [SqlValue::Int(pid)])?;
  let Some(p) = get_pay(db, pid)? else { return Ok(nf()); };
  if n > 0 { Ok(Resp { status: 200, body: pay_json(p).to_json() }) } else { Ok(fail(409, "invalid transition")) }
}

fn list(db: Db, query: Str) -> Result<Resp, DbErr> {
  let account = query_param(query, "account").unwrap_or("");
  let rows = db.query("SELECT id, account, cents, currency, status, refunded FROM payments WHERE account = ? ORDER BY id", [SqlValue::Text(account)])?;
  let mut out: List<Json> = [];
  for r in rows { out.push(pay_json(row_pay(r))); }
  Ok(Resp { status: 200, body: Json::Arr(out).to_json() })
}

fn handle(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL, ikey TEXT UNIQUE)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS idem (key TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)", [])?;
  db.exec("CREATE INDEX IF NOT EXISTS payments_account ON payments (account, id)", [])?;
  let method = req.method();
  let target = req.target();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  let segs = path.split("/");
  if segs.len() < 2 || segs[0] != "" || segs[1] != "payments" { return Ok(nf()); }
  let raw = req.body();
  let text = utf8_str(raw);
  let canon = canon_of(raw);
  if segs.len() == 2 {
    if method == "GET" { return list(db, query); }
    if method == "POST" {
      let key = idem_key(req);
      if key == "" { return Ok(fail(400, "missing idempotency key")); }
      return create(db, key, path, canon, text);
    }
    return Ok(nf());
  }
  let id = parse_id(segs[2]);
  if segs.len() == 3 {
    if method == "GET" {
      let Some(pid) = id else { return Ok(nf()); };
      let Some(p) = get_pay(db, pid)? else { return Ok(nf()); };
      return Ok(Resp { status: 200, body: pay_json(p).to_json() });
    }
    return Ok(nf());
  }
  if segs.len() == 4 && method == "POST" {
    let action = segs[3];
    if action == "refund" {
      let key = idem_key(req);
      if key == "" { return Ok(fail(400, "missing idempotency key")); }
      return refund(db, id, key, path, canon, text);
    }
    if action == "capture" { return capture(db, id); }
    if action == "cancel" { return cancel(db, id); }
  }
  Ok(nf())
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Str {
  let r = match handle(req, db) {
    Ok(r) => r,
    Err(_) => fail(500, "internal error"),
  };
  match res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes()) {
    Ok(_) => "ok",
    Err(_) => "send failed",
  }
}

fn digit(b: Int) -> Option<Int> {
  if b >= 48 && b <= 57 { Some(b - 48) } else { None }
}

fn num(bs: Bytes, a: Int, b: Int) -> Option<Int> {
  let mut n = 0;
  for i in a..b {
    let d = digit(bs[i])?;
    n = n * 10 + d;
  }
  Some(n)
}

fn is_leap(y: Int) -> Bool {
  (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in(y: Int, m: Int) -> Int {
  if m == 2 { if is_leap(y) { 29 } else { 28 } }
  else if m == 4 || m == 6 || m == 9 || m == 11 { 30 }
  else { 31 }
}

fn days_from_civil(y0: Int, m: Int, d: Int) -> Int {
  let y = if m <= 2 { y0 - 1 } else { y0 };
  let era = (if y >= 0 { y } else { y - 399 }) / 400;
  let yoe = y - era * 400;
  let mp = if m > 2 { m - 3 } else { m + 9 };
  let doy = (153 * mp + 2) / 5 + d - 1;
  let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  era * 146097 + doe - 719468
}

fn parse_time(s: Str) -> Option<Int> {
  let bs = s.to_bytes();
  if bs.len() != 20 { return None; }
  if bs[4] != 45 || bs[7] != 45 || bs[10] != 84 || bs[13] != 58 || bs[16] != 58 || bs[19] != 90 {
    return None;
  }
  let y = num(bs, 0, 4)?;
  let mo = num(bs, 5, 7)?;
  let d = num(bs, 8, 10)?;
  let h = num(bs, 11, 13)?;
  let mi = num(bs, 14, 16)?;
  let se = num(bs, 17, 19)?;
  if mo < 1 || mo > 12 { return None; }
  if d < 1 || d > days_in(y, mo) { return None; }
  if h > 23 || mi > 59 || se > 59 { return None; }
  Some(days_from_civil(y, mo, d) * 86400 + h * 3600 + mi * 60 + se)
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn fmt_dur(d: Int) -> Str {
  pad2(d / 3600) + ":" + pad2((d % 3600) / 60) + ":" + pad2(d % 60)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("events.log")?.to_str();
  let mut malformed = 0;
  let mut dups = 0;
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut times: Map<Str, List<Int>> = Map::new();
  let mut upages: Map<Str, Map<Str, Bool>> = Map::new();
  let mut pcount: HashMap<Str, Int> = HashMap::new();
  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    let parts = line.split(" ");
    if parts.len() != 3 || parts[0] == "" || parts[1] == "" || parts[2] == "" {
      malformed += 1;
      continue;
    }
    let Some(t) = parse_time(parts[0]) else { malformed += 1; continue; };
    if seen.get(line).is_some() { dups += 1; continue; }
    seen.insert(line, true);
    let user = parts[1];
    let page = parts[2];
    let mut ts = times.get(user).unwrap_or([]);
    ts.push(t);
    times.insert(user, ts);
    let mut ps: Map<Str, Bool> = upages.get(user).unwrap_or(Map::new());
    ps.insert(page, true);
    upages.insert(user, ps);
    pcount.insert(page, pcount.get(page).unwrap_or(0) + 1);
  }
  let tail = "malformed " + malformed.to_str() + " duplicates " + dups.to_str();
  if times.len() == 0 { return Ok(tail); }
  let mut out: List<Str> = [];
  let mut all: List<Int> = [];
  for u in times.keys() {
    let mut ts = times.get(u).unwrap_or([]);
    ts.sort();
    let mut sessions = 0;
    let mut longest = 0;
    let mut start = ts[0];
    let mut prev = ts[0];
    for i in 1..ts.len() {
      let t = ts[i];
      if t - prev > 1800 {
        let d = prev - start;
        all.push(d);
        sessions += 1;
        longest = longest.max(d);
        start = t;
      }
      prev = t;
    }
    let d = prev - start;
    all.push(d);
    sessions += 1;
    longest = longest.max(d);
    let np = upages.get(u).map(|m| m.len()).unwrap_or(0);
    out.push(u + " sessions " + sessions.to_str() + " events " + ts.len().to_str()
      + " longest " + fmt_dur(longest) + " pages " + np.to_str());
  }
  all.sort();
  out.push("median " + all[(all.len() - 1) / 2].to_str());
  let mut pages = pcount.keys();
  let pc = pcount;
  pages.sort_by(|a: Str, b: Str| {
    let ca = pc.get(a).unwrap_or(0);
    let cb = pc.get(b).unwrap_or(0);
    ca > cb || (ca == cb && a < b)
  });
  let mut top: List<Str> = [];
  let n = pages.len().min(3);
  for i in 0..n {
    top.push(pages[i] + " (" + pc.get(pages[i]).unwrap_or(0).to_str() + ")");
  }
  out.push("top: " + top.join(", "));
  out.push(tail);
  Ok(out.join("\n"))
}

struct Ev { t: Int, page: Str }

fn digits(b: Bytes, a: Int, n: Int) -> Option<Int> {
  let mut v = 0;
  for i in a..(a + n) {
    let c = b[i];
    if c < 48 || c > 57 { return None; }
    v = v * 10 + (c - 48);
  }
  Some(v)
}

fn is_leap(y: Int) -> Bool {
  y % 4 == 0 && (y % 100 != 0 || y % 400 == 0)
}

fn month_days(y: Int, m: Int) -> Int {
  if m == 2 { if is_leap(y) { 29 } else { 28 } }
  else if m == 4 || m == 6 || m == 9 || m == 11 { 30 }
  else { 31 }
}

fn parse_time(s: Str) -> Option<Int> {
  let b = s.to_bytes();
  if b.len() != 20 { return None; }
  if b[4] != 45 || b[7] != 45 || b[10] != 84 || b[13] != 58 || b[16] != 58 || b[19] != 90 {
    return None;
  }
  let y = digits(b, 0, 4)?;
  let mo = digits(b, 5, 2)?;
  let d = digits(b, 8, 2)?;
  let h = digits(b, 11, 2)?;
  let mi = digits(b, 14, 2)?;
  let se = digits(b, 17, 2)?;
  if mo < 1 || mo > 12 { return None; }
  if d < 1 || d > month_days(y, mo) { return None; }
  if h > 23 || mi > 59 || se > 59 { return None; }
  let yy = if mo <= 2 { y - 1 } else { y };
  let era = if yy >= 0 { yy / 400 } else { (yy - 399) / 400 };
  let yoe = yy - era * 400;
  let mp = (mo + 9) % 12;
  let doy = (153 * mp + 2) / 5 + d - 1;
  let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  let days = era * 146097 + doe - 719468;
  Some(days * 86400 + h * 3600 + mi * 60 + se)
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn hms(d: Int) -> Str {
  pad2(d / 3600) + ":" + pad2((d % 3600) / 60) + ":" + pad2(d % 60)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("events.log")?.to_str();
  let mut malformed = 0;
  let mut dups = 0;
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut users: Map<Str, List<Ev>> = Map::new();
  let mut page_counts: Map<Str, Int> = Map::new();
  for raw in text.lines() {
    let line = match raw.strip_suffix("\r") { Some(x) => x, None => raw };
    if line.trim() == "" { continue; }
    let parts = line.split(" ");
    if parts.len() != 3 || parts[1] == "" || parts[2] == "" {
      malformed += 1;
      continue;
    }
    let Some(t) = parse_time(parts[0]) else { malformed += 1; continue; };
    if seen.get(line).is_some() { dups += 1; continue; }
    seen.insert(line, true);
    let user = parts[1];
    let page = parts[2];
    let mut evs = users.get(user).unwrap_or([]);
    evs.push(Ev { t: t, page: page });
    users.insert(user, evs);
    page_counts.insert(page, page_counts.get(page).unwrap_or(0) + 1);
  }
  let last = "malformed " + malformed.to_str() + " duplicates " + dups.to_str();
  if users.len() == 0 { return Ok(last); }
  let mut out: List<Str> = [];
  let mut durations: List<Int> = [];
  for u in users.keys() {
    let mut evs = users.get(u).unwrap_or([]);
    evs.sort_by_key(|e| e.t);
    let mut sessions = 0;
    let mut longest = 0;
    let mut start = 0;
    let mut prev = 0;
    let mut pages: Map<Str, Bool> = Map::new();
    let mut i = 0;
    for e in evs {
      pages.insert(e.page, true);
      if i == 0 {
        sessions = 1;
        start = e.t;
      } else if e.t - prev > 1800 {
        let d = prev - start;
        durations.push(d);
        if d > longest { longest = d; }
        sessions += 1;
        start = e.t;
      }
      prev = e.t;
      i += 1;
    }
    let d = prev - start;
    durations.push(d);
    if d > longest { longest = d; }
    out.push(u + " sessions " + sessions.to_str() + " events " + evs.len().to_str()
      + " longest " + hms(longest) + " pages " + pages.len().to_str());
  }
  durations.sort();
  let med = durations[(durations.len() - 1) / 2];
  out.push("median " + med.to_str());
  let mut pl = page_counts.keys();
  let pc = page_counts;
  pl.sort_by(|a, b| {
    let ca = pc.get(a).unwrap_or(0);
    let cb = pc.get(b).unwrap_or(0);
    ca > cb || (ca == cb && a < b)
  });
  let mut tops: List<Str> = [];
  let mut k = 0;
  for p in pl {
    if k >= 3 { break; }
    tops.push(p + " (" + pc.get(p).unwrap_or(0).to_str() + ")");
    k += 1;
  }
  out.push("top: " + tops.join(", "));
  out.push(last);
  Ok(out.join("\n"))
}

