    if dur > longest { longest = dur; }
    let np = upages.get(user).unwrap_or(Map::new()).len();
    out.push(user + " sessions " + sessions.to_str() + " events " + ts.len().to_str()
      + " longest " + hms(longest) + " pages " + np.to_str());
  }

  durations.sort();
  let median = durations[(durations.len() - 1) / 2];
  out.push("median " + median.to_str());

  let mut pages = pcount.keys();
  let pc = pcount;
  pages.sort_by(|a, b| {
    let ca = pc.get(a).unwrap_or(0);
    let cb = pc.get(b).unwrap_or(0);
    ca > cb || (ca == cb && a < b)
  });
  let mut tops: List<Str> = [];
  let mut i = 0;
  while i < pages.len() && i < 3 {
    let p = pages[i];
    tops.push(p + " (" + pc.get(p).unwrap_or(0).to_str() + ")");
    i += 1;
  }
  out.push("top: " + tops.join(", "));
  out.push(last);
  Ok(out.join("\n"))
}

struct Rec { fields: List<Str>, bad: Bool }

struct Agg { revenue: Int, items: Int, products: Map<Str, Int> }

fn at_end_of_field(cs: List<Str>, i: Int, n: Int) -> Bool {
  if i >= n { return true; }
  if cs[i] == "," || cs[i] == "\n" { return true; }
  if cs[i] == "\r" && i + 1 < n && cs[i + 1] == "\n" { return true; }
  false
}

fn parse(text: Str) -> List<Rec> {
  let cs = text.chars();
  let n = cs.len();
  let mut i = 0;
  let mut recs: List<Rec> = [];
  while i < n {
    if cs[i] == "\n" { i += 1; continue; }
    if cs[i] == "\r" && i + 1 < n && cs[i + 1] == "\n" { i += 2; continue; }
    let mut fields: List<Str> = [];
    let mut bad = false;
    loop {
      let mut f = "";
      if i < n && cs[i] == "\"" {
        i += 1;
        let mut closed = false;
        while i < n {
          let c = cs[i];
          if c == "\"" {
            if i + 1 < n && cs[i + 1] == "\"" {
              f = f + "\"";
              i += 2;
            } else {
              i += 1;
              closed = true;
              break;
            }
          } else {
            f = f + c;
            i += 1;
          }
        }
        if !closed {
          bad = true;
          fields.push(f);
          break;
        }
        while !at_end_of_field(cs, i, n) {
          bad = true;
          i += 1;
        }
      } else {
        while !at_end_of_field(cs, i, n) {
          if cs[i] == "\"" { bad = true; }
          f = f + cs[i];
          i += 1;
        }
      }
      fields.push(f);
      if i >= n { break; }
      if cs[i] == "," { i += 1; continue; }
      if cs[i] == "\r" { i += 2; } else { i += 1; }
      break;
    }
    recs.push(Rec { fields: fields, bad: bad });
  }
  recs
}

fn all_digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for c in s.chars() {
    if !(c >= "0" && c <= "9") { return false; }
  }
  true
}

fn parse_price(s: Str) -> Option<Int> {
  let parts = s.split(".");
  if parts.len() == 1 {
    if !all_digits(parts[0]) { return None; }
    let w = parts[0].parse_int()?;
    if w > 1000000000000000 { return None; }
    return Some(w * 100);
  }
  if parts.len() != 2 { return None; }
  if !all_digits(parts[0]) || !all_digits(parts[1]) { return None; }
  if parts[1].len() > 2 { return None; }
  let w = parts[0].parse_int()?;
  if w > 1000000000000000 { return None; }
  let mut fr = parts[1].parse_int()?;
  if parts[1].len() == 1 { fr = fr * 10; }
  Some(w * 100 + fr)
}

fn two(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn money(c: Int) -> Str {
  let neg = c < 0;
  let a = if neg { -c } else { c };
  let s = (a / 100).to_str() + "." + two(a % 100);
  if neg { "-" + s } else { s }
}

fn enc(f: Str) -> Str {
  if f.contains(",") || f.contains("\"") || f.contains("\r") || f.contains("\n") {
    "\"" + f.replace("\"", "\"\"") + "\""
  } else {
    f
  }
}

fn enc_rec(fields: List<Str>) -> Str {
  let mut parts: List<Str> = [];
  for f in fields { parts.push(enc(f)); }
  parts.join(",") + "\n"
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let recs = parse(text);
  let mut clean = "region,product,qty,price,note\n";
  if recs.len() > 0 { clean = enc_rec(recs[0].fields); }
  let mut aggs: Map<Str, Agg> = Map::new();
  let mut badnums: List<Str> = [];
  let mut count = 0;
  let mut idx = 1;
  while idx < recs.len() {
    let r = recs[idx];
    count += 1;
    let mut ok = !r.bad && r.fields.len() == 5;
    let mut qty = 0;
    let mut cents = 0;
    if ok {
      let fs = r.fields;
      if fs[0].len() == 0 || fs[1].len() == 0 { ok = false; }
      match fs[2].parse_int() { Some(q) => qty = q, None => ok = false, }
      match parse_price(fs[3]) { Some(c) => cents = c, None => ok = false, }
    }
    if ok {
      let fs = r.fields;
      let mut outf = fs;
      outf[3] = money(cents);
      clean = clean + enc_rec(outf);
      let region = fs[0];
      let product = fs[1];
      let rev = qty * cents;
      let mut a = aggs.get(region).unwrap_or(Agg { revenue: 0, items: 0, products: Map::new() });
      a.revenue = a.revenue + rev;
      a.items = a.items + qty;
      let p = a.products.get(product).unwrap_or(0);
      a.products.insert(product, p + rev);
      aggs.insert(region, a);
    } else {
      badnums.push(count.to_str());
    }
    idx += 1;
  }
  out.create("clean.csv", clean.to_bytes())?;
  let mut lines: List<Str> = [];
  for region in aggs.keys() {
    let Some(a) = aggs.get(region) else { continue; };
    let mut top = "";
    let mut best = 0;
    let mut first = true;
    for p in a.products.keys() {
      let v = a.products.get(p).unwrap_or(0);
      if first || v > best {
        top = p;
        best = v;
        first = false;
      }
    }
    lines.push(region + " revenue " + money(a.revenue) + " items " + a.items.to_str() + " top " + top);
  }
  let mut last = "records " + count.to_str() + " bad " + badnums.len().to_str();
  if badnums.len() > 0 { last = last + ": " + badnums.join(", "); }
  lines.push(last);
  Ok(lines.join("\n"))
}

struct Rec { fields: List<Str>, bad: Bool }

struct Agg { rev: Int, items: Int, prods: Map<Str, Int> }

fn parse(text: Str) -> List<Rec> {
  let cs = text.chars();
  let n = cs.len();
  let mut recs: List<Rec> = [];
  let mut fields: List<Str> = [];
  let mut field = "";
  let mut inq = false;
  let mut closed = false;
  let mut fstart = true;
  let mut quoted_any = false;
  let mut bad = false;
  let mut i = 0;
  while i < n {
    let c = cs[i];
    i += 1;
    if inq {
      if c == "\"" { inq = false; closed = true; } else { field = field + c; }
      continue;
    }
    let mut eor = false;
    if c == "\n" {
      eor = true;
    } else if c == "\r" && i < n && cs[i] == "\n" {
      i += 1;
      eor = true;
    }
    if eor || c == "," {
      fields.push(field);
      field = "";
      fstart = true;
      closed = false;
      if eor {
        let empty = fields.len() == 1 && fields[0] == "" && !quoted_any;
        if !empty {
          recs.push(Rec { fields: fields, bad: bad });
        }
        fields = [];
        quoted_any = false;
        bad = false;
      }
      continue;
    }
    if closed {
      if c == "\"" {
        field = field + "\"";
        inq = true;
        closed = false;
      } else {
        bad = true;
        closed = false;
        field = field + c;
      }
      continue;
    }
    if c == "\"" {
      if fstart {
        inq = true;
        quoted_any = true;
        fstart = false;
      } else {
        bad = true;
        field = field + c;
      }
      continue;
    }
    fstart = false;
    field = field + c;
  }
  if inq {
    fields.push(field);
    recs.push(Rec { fields: fields, bad: true });
  } else {
    let nothing = fields.len() == 0 && field == "" && !quoted_any;
    if !nothing {
      fields.push(field);
      let empty = fields.len() == 1 && fields[0] == "" && !quoted_any;
      if !empty {
        recs.push(Rec { fields: fields, bad: bad });
      }
    }
  }
  recs
}

fn is_digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for b in s.to_bytes() {
    if b < 48 || b > 57 { return false; }
  }
  true
}

fn parse_qty(s: Str) -> Option<Int> {
  let body = s.strip_prefix("-").unwrap_or(s);
  if !is_digits(body) || body.len() > 15 { return None; }
  s.parse_int()
}

fn parse_price(s: Str) -> Option<Int> {
  let parts = s.split(".");
  if parts.len() == 1 {
    if !is_digits(parts[0]) || parts[0].len() > 13 { return None; }
    return Some(parts[0].parse_int()? * 100);
  }
  if parts.len() != 2 { return None; }
  let ip = parts[0];
  let fp = parts[1];
  if !is_digits(ip) || ip.len() > 13 { return None; }
  if !is_digits(fp) || fp.len() > 2 { return None; }
  let mut f = fp.parse_int()?;
  if fp.len() == 1 { f = f * 10; }
  Some(ip.parse_int()? * 100 + f)
}

fn money(c: Int) -> Str {
  let mut sign = "";
  let mut a = c;
  if c < 0 { sign = "-"; a = 0 - c; }
  let frac = a % 100;
  let fs = if frac < 10 { "0" + frac.to_str() } else { frac.to_str() };
  sign + (a / 100).to_str() + "." + fs
}

fn quote(s: Str) -> Str {
  if s.contains(",") || s.contains("\"") || s.contains("\r") || s.contains("\n") {
    "\"" + s.replace("\"", "\"\"") + "\""
  } else {
    s
  }
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let recs = parse(text);
  let mut clean = "region,product,qty,price,note\n";
  let mut aggs: Map<Str, Agg> = Map::new();
  let mut bads: List<Str> = [];
  let mut count = 0;
  let mut idx = 0;
  for r in recs {
    idx += 1;
    if idx == 1 { continue; }
    count += 1;
    let num = idx - 1;
    let mut ok = !r.bad && r.fields.len() == 5;
    let mut q = 0;
    let mut p = 0;
    if ok {
      if r.fields[0] == "" || r.fields[1] == "" { ok = false; }
    }
    if ok {
      match parse_qty(r.fields[2]) { Some(v) => q = v, None => ok = false, }
    }
    if ok {
      match parse_price(r.fields[3]) { Some(v) => p = v, None => ok = false, }
    }
    if !ok {
      bads.push(num.to_str());
      continue;
    }
    let f = r.fields;
    clean = clean + quote(f[0]) + "," + quote(f[1]) + "," + quote(f[2]) + "," + money(p) + "," + quote(f[4]) + "\n";
    let rev = q * p;
    let mut a = aggs.get(f[0]).unwrap_or(Agg { rev: 0, items: 0, prods: Map::new() });
    a.rev = a.rev + rev;
    a.items = a.items + q;
    let prev = a.prods.get(f[1]).unwrap_or(0);
    a.prods.insert(f[1], prev + rev);
    aggs.insert(f[0], a);
  }
  out.write("clean.csv", clean.to_bytes())?;
  let mut lines: List<Str> = [];
  for region in aggs.keys() {
    let Some(a) = aggs.get(region) else { continue; };
    let mut top = "";
    let mut best = 0;
    let mut first = true;
    for prod in a.prods.keys() {
      let v = a.prods.get(prod).unwrap_or(0);
      if first || v > best {
        top = prod;
        best = v;
        first = false;
      }
    }
    lines.push(region + " revenue " + money(a.rev) + " items " + a.items.to_str() + " top " + top);
  }
  let mut last = "records " + count.to_str() + " bad " + bads.len().to_str();
  if bads.len() > 0 { last = last + ": " + bads.join(", "); }
  lines.push(last);
  Ok(lines.join("\n"))
}

fn ke(e: KvErr) -> Str { "kv error" }
fn ie(e: IoErr) -> Str { "io error" }

fn walk(d: Dir, dir: Str) -> Result<List<Str>, Str> {
  let names = d.list(dir).map_err(ie)?;
  let mut res: List<Str> = [];
  for n in names {
    let full = if dir == "" { n } else { dir + "/" + n };
    if let Some(sub) = full.strip_suffix("/") {
      let inner = walk(d, sub)?;
      for x in inner { res.push(x); }
    } else {
      res.push(full);
    }
  }
  Ok(res)
}

fn is_word_byte(c: Int) -> Bool {
  c >= 128 || (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122)
}

fn words(s: Str) -> List<Str> {
  let b = s.to_bytes();
  let mut cur = "".to_bytes();
  let mut out: List<Str> = [];
  for c in b {
    if is_word_byte(c) {
      cur.push(c);
    } else {
      if cur.len() > 0 {
        out.push(cur.to_str().to_lowercase());
        cur = "".to_bytes();
      }
    }
  }
  if cur.len() > 0 { out.push(cur.to_str().to_lowercase()); }
  out
}

fn dedup(xs: List<Str>) -> List<Str> {
  let mut m: Map<Str, Bool> = Map::new();
  for x in xs { m.insert(x, true); }
  m.keys()
}

fn get_list(kv: Kv, key: Str) -> Result<List<Str>, Str> {
  let v = kv.get(key).map_err(ke)?;
  let Some(b) = v else { return Ok([]); };
  let j = b.to_str().parse_json()?;
  let mut out: List<Str> = [];
  for x in j.as_list().unwrap_or([]) {
    if let Some(s) = x.as_str() { out.push(s); }
  }
  Ok(out)
}

fn set_list(kv: Kv, key: Str, xs: List<Str>) -> Result<(), Str> {
  if xs.len() == 0 {
    kv.delete(key).map_err(ke)
  } else {
    let j = Json::Arr(xs.map(|s| Json::Str(s)));
    kv.set(key, j.to_json().to_bytes()).map_err(ke)
  }
}

fn load_files(kv: Kv) -> Result<Map<Str, Str>, Str> {
  let mut m: Map<Str, Str> = Map::new();
  let v = kv.get("files").map_err(ke)?;
  let Some(b) = v else { return Ok(m); };
  let j = b.to_str().parse_json()?;
  let obj = j.as_map().unwrap_or(Map::new());
  for k in obj.keys() {
    if let Some(x) = obj.get(k) {
      if let Some(s) = x.as_str() { m.insert(k, s); }
    }
  }
  Ok(m)
}

fn save_files(kv: Kv, m: Map<Str, Str>) -> Result<(), Str> {
  let mut obj: Map<Str, Json> = Map::new();
  for k in m.keys() {
    if let Some(h) = m.get(k) { obj.insert(k, Json::Str(h)); }
  }
  kv.set("files", Json::Obj(obj).to_json().to_bytes()).map_err(ke)
}

fn unindex(kv: Kv, p: Str) -> Result<(), Str> {
  let ws = get_list(kv, "f:" + p)?;
  for w in ws {
    let l = get_list(kv, "w:" + w)?;
    let nl = l.filter(|x| x != p);
    set_list(kv, "w:" + w, nl)?;
  }
  kv.delete("f:" + p).map_err(ke)
}

fn reindex(kv: Kv, p: Str, data: Bytes) -> Result<(), Str> {
  let ws = dedup(words(data.to_str()));
  for w in ws {
    let mut l = get_list(kv, "w:" + w)?;
    if !l.contains(p) { l.push(p); }
    set_list(kv, "w:" + w, l)?;
  }
  set_list(kv, "f:" + p, ws)
}

fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Str> {
  let paths = walk(docs, "")?;
  let old = load_files(index)?;
  let mut newf: Map<Str, Str> = Map::new();
  let mut events: Map<Str, Str> = Map::new();
  let mut unchanged = 0;
  for p in paths {
    let data = docs.read(p).map_err(ie)?;
    let h = data.sha256().to_hex();
    newf.insert(p, h);
    if let Some(oh) = old.get(p) {
      if oh == h {
        unchanged += 1;
      } else {
        events.insert(p, "changed");
        unindex(index, p)?;
        reindex(index, p, data)?;
      }
    } else {
      events.insert(p, "added");
      reindex(index, p, data)?;
    }
  }
  for p in old.keys() {
    if newf.get(p).is_none() {
      events.insert(p, "removed");
      unindex(index, p)?;
    }
  }
  save_files(index, newf)?;

  let mut lines: List<Str> = [];
  for p in events.keys() {
    let k = events.get(p).unwrap_or("");
    lines.push(k + " " + p);
  }
  lines.push("unchanged " + unchanged.to_str());

  let text = queries.read("queries.txt").map_err(ie)?.to_str();
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let qw = words(line);
    let mut cur: List<Str> = newf.keys();
    for w in qw {
      let l = get_list(index, "w:" + w)?;
      cur = cur.filter(|x| l.contains(x));
    }
    cur.sort();
    let ans = if cur.len() == 0 { "none" } else { cur.join(", ") };
    lines.push(line + ": " + ans);
  }
  Ok(lines.join("\n"))
}

struct Counts { applied: Int, stale: Int, invalid: Int }

enum Change { Upsert(Str, Str, Int, Int), Delete(Str, Int) }

fn dberr(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(m) => "db invalid: " + m,
    DbErr::Denied => "db denied",
    DbErr::Busy => "db busy",
    DbErr::TooLarge => "db too large",
    DbErr::Constraint(m) => "db constraint: " + m,
  }
}

fn setup(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS versions (sku TEXT PRIMARY KEY, version INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS sync_state (k TEXT PRIMARY KEY, pos TEXT NOT NULL)", [])?;
  Ok(())
}

fn load_cursor(db: Db) -> Result<Str, DbErr> {
  let rows = db.query("SELECT pos FROM sync_state WHERE k = 'cursor'", [])?;
  if rows.len() == 0 { return Ok("0"); }
  match rows[0][0] {
    SqlValue::Text(s) => Ok(s),
    _ => Ok("0"),
  }
}

fn is_unreserved(b: Int) -> Bool {
  (b >= 48 && b <= 57) || (b >= 65 && b <= 90) || (b >= 97 && b <= 122) || b == 45 || b == 46 || b == 95 || b == 126
}

fn hex_digit(n: Int) -> Int {
  if n < 10 { 48 + n } else { 55 + n }
}

fn enc(s: Str) -> Str {
  let mut out = "".to_bytes();
  for b in s.to_bytes() {
    if is_unreserved(b) {
      out.push(b);
    } else {
      out.push(37);
      out.push(hex_digit(b / 16));
      out.push(hex_digit(b % 16));
    }
  }
  out.to_str()
}

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 { i += 1; continue; }
    let mut need = 0;
    let mut min = 0;
    let mut cp = 0;
    if c >= 194 && c <= 223 { need = 1; min = 128; cp = c - 192; }
    else if c >= 224 && c <= 239 { need = 2; min = 2048; cp = c - 224; }
    else if c >= 240 && c <= 244 { need = 3; min = 65536; cp = c - 240; }
    else { return false; }
    if i + need >= n { return false; }
    for k in 1..need + 1 {
      let d = b[i + k];
      if d < 128 || d > 191 { return false; }
      cp = cp * 64 + (d - 128);
    }
    if cp < min || cp > 1114111 { return false; }
    if cp >= 55296 && cp <= 57343 { return false; }
    i = i + need + 1;
  }
  true
}

fn parse_change(j: Json) -> Option<Change> {
  let op = j.get("op")?.as_str()?;
  let sku = j.get("sku")?.as_str()?;
  let ver = j.get("version")?.as_int()?;
  if op == "upsert" {
    let name = j.get("name")?.as_str()?;
    let qty = j.get("qty")?.as_int()?;
    Some(Change::Upsert(sku, name, qty, ver))
  } else if op == "delete" {
    Some(Change::Delete(sku, ver))
  } else {
    None
  }
}

fn known_version(db: Db, vers: HashMap<Str, Int>, sku: Str) -> Result<Option<Int>, DbErr> {
  if let Some(v) = vers.get(sku) { return Ok(Some(v)); }
  let rows = db.query("SELECT version FROM versions WHERE sku = ?", [SqlValue::Text(sku)])?;
  if rows.len() == 0 { return Ok(None); }
  match rows[0][0] {
    SqlValue::Int(v) => Ok(Some(v)),
    _ => Ok(None),
  }
}

fn apply_page(db: Db, changes: List<Json>, new_cursor: Str) -> Result<Counts, DbErr> {
  let mut c = Counts { applied: 0, stale: 0, invalid: 0 };
  let mut vers: HashMap<Str, Int> = HashMap::new();
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  for j in changes {
    let Some(ch) = parse_change(j) else { c.invalid += 1; continue; };
    let mut sku = "";
    let mut ver = 0;
    match ch {
      Change::Upsert(s, _, _, v) => { sku = s; ver = v; }
      Change::Delete(s, v) => { sku = s; ver = v; }
    }
    let last = known_version(db, vers, sku)?;
    if let Some(l) = last {
      if ver <= l { c.stale += 1; continue; }
    }
    match ch {
      Change::Upsert(s, name, qty, _) => {
        stmts.push("INSERT INTO items (sku, name, qty) VALUES (?, ?, ?) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty");
        params.push([SqlValue::Text(s), SqlValue::Text(name), SqlValue::Int(qty)]);
      }
      Change::Delete(s, _) => {
        stmts.push("DELETE FROM items WHERE sku = ?");
        params.push([SqlValue::Text(s)]);
      }
    }
    stmts.push("INSERT INTO versions (sku, version) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET version = excluded.version");
    params.push([SqlValue::Text(sku), SqlValue::Int(ver)]);
    vers.insert(sku, ver);
    c.applied += 1;
  }
  stmts.push("INSERT INTO sync_state (k, pos) VALUES ('cursor', ?) ON CONFLICT(k) DO UPDATE SET pos = excluded.pos");
  params.push([SqlValue::Text(new_cursor)]);
  db.transaction(stmts, params)?;
  Ok(c)
}

