struct Fin { deleted: Bool, name: Str, qty: Int }

enum Change { Up(Str, Str, Int, Int), Del(Str, Int), Invalid }

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    let mut k = 0;
    if c < 128 { k = 0; }
    else if c >= 194 && c < 224 { k = 1; }
    else if c >= 224 && c < 240 { k = 2; }
    else if c >= 240 && c < 245 { k = 3; }
    else { return false; }
    if i + k >= n { return false; }
    for j in 1..k + 1 {
      let d = b[i + j];
      if d < 128 || d > 191 { return false; }
    }
    if k >= 2 {
      let d = b[i + 1];
      if c == 224 && d < 160 { return false; }
      if c == 237 && d >= 160 { return false; }
      if c == 240 && d < 144 { return false; }
      if c == 244 && d > 143 { return false; }
    }
    i = i + k + 1;
  }
  true
}

fn enc(s: Str) -> Str {
  let hex = "0123456789ABCDEF";
  let mut out = "";
  for b in s.to_bytes() {
    let alnum = (b >= 48 && b <= 57) || (b >= 65 && b <= 90) || (b >= 97 && b <= 122);
    if alnum || b == 45 || b == 95 || b == 46 || b == 126 {
      let mut one = "".to_bytes();
      one.push(b);
      out = out + one.to_str();
    } else {
      out = out + "%" + hex.slice(b / 16, b / 16 + 1) + hex.slice(b % 16, b % 16 + 1);
    }
  }
  out
}

fn parse_change(j: Json) -> Change {
  let Some(op) = j.get("op").and_then(|x| x.as_str()) else { return Change::Invalid; };
  let Some(sku) = j.get("sku").and_then(|x| x.as_str()) else { return Change::Invalid; };
  let Some(ver) = j.get("version").and_then(|x| x.as_int()) else { return Change::Invalid; };
  if op == "upsert" {
    let Some(name) = j.get("name").and_then(|x| x.as_str()) else { return Change::Invalid; };
    let Some(qty) = j.get("qty").and_then(|x| x.as_int()) else { return Change::Invalid; };
    return Change::Up(sku, name, qty, ver);
  }
  if op == "delete" { return Change::Del(sku, ver); }
  Change::Invalid
}

