}

fn main(api: Http, db: Db) -> Result<Str, Str> {
  setup(db)?;
  let mut cursor = "0";
  let rows = db.query("SELECT v FROM state WHERE k = 'cursor'", []).map_err(|e| "db error: " + db_msg(e))?;
  if rows.len() > 0 && rows[0].len() > 0 {
    if let SqlValue::Text(c) = rows[0][0] { cursor = c; }
  }
  let mut versions: HashMap<Str, Int> = HashMap::new();
  let vrows = db.query("SELECT sku, version FROM versions", []).map_err(|e| "db error: " + db_msg(e))?;
  for r in vrows {
    if r.len() == 2 {
      if let SqlValue::Text(s) = r[0] {
        if let SqlValue::Int(v) = r[1] { versions.insert(s, v); }
      }
    }
  }

  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut status = "";
  loop {
    let path = "/changes?cursor=" + enc(cursor);
    let resp = match api.send("GET", path, [], "".to_bytes(), 0) {
      Ok(r) => r,
      Err(_) => { status = "stopped at " + cursor + " (no response)"; break; }
    };
    if resp.status != 200 {
      status = "stopped at " + cursor + " (status " + resp.status.to_str() + ")";
      break;
    }
    let bad = "stopped at " + cursor + " (invalid page)";
    if !valid_utf8(resp.body) { status = bad; break; }
    let Ok(doc) = resp.body.to_str().parse_json() else { status = bad; break; };
    let Some(changes) = doc.get("changes").and_then(|x| x.as_list()) else { status = bad; break; };
    let next: Option<Str> = doc.get("next").and_then(|x| x.as_str());

    let mut v2 = versions;
    let mut fin: HashMap<Str, Fin> = HashMap::new();
    let mut a = 0;
    let mut s = 0;
    let mut inv = 0;
    for c in changes {
      match parse_change(c) {
        Change::Invalid => inv += 1,
        Change::Up(sku, name, qty, ver) => {
          let last = v2.get(sku);
          if last.is_some() && ver <= last.unwrap_or(0) { s += 1; } else {
            a += 1;
            v2.insert(sku, ver);
            fin.insert(sku, Fin { deleted: false, name: name, qty: qty });
          }
        }
        Change::Del(sku, ver) => {
          let last = v2.get(sku);
          if last.is_some() && ver <= last.unwrap_or(0) { s += 1; } else {
            a += 1;
            v2.insert(sku, ver);
            fin.insert(sku, Fin { deleted: true, name: "", qty: 0 });
          }
        }
      }
    }

    let mut stmts: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    for sku in fin.keys() {
      let Some(f) = fin.get(sku) else { continue; };
      if f.deleted {
        stmts.push("DELETE FROM items WHERE sku = ?");
        params.push([SqlValue::Text(sku)]);
      } else {
        stmts.push("INSERT INTO items (sku, name, qty) VALUES (?, ?, ?) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty");
        params.push([SqlValue::Text(sku), SqlValue::Text(f.name), SqlValue::Int(f.qty)]);
      }
      stmts.push("INSERT INTO versions (sku, version) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET version = excluded.version");
      params.push([SqlValue::Text(sku), SqlValue::Int(v2.get(sku).unwrap_or(0))]);
    }
    let new_cursor = next.unwrap_or(cursor);
    stmts.push("INSERT INTO state (k, v) VALUES ('cursor', ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v");
    params.push([SqlValue::Text(new_cursor)]);
    db.transaction(stmts, params).map_err(|e| "db error: " + db_msg(e))?;

    versions = v2;
    pages += 1;
    applied += a;
    stale += s;
    invalid += inv;
    match next {
      None => { status = "complete"; break; }
      Some(n) => { cursor = n; }
    }
  }

  let mut lines: List<Str> = [];
  lines.push("pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str());
  lines.push(status);
  let irows = db.query("SELECT sku, qty, name FROM items", []).map_err(|e| "db error: " + db_msg(e))?;
  let mut items: List<Fin> = [];
  for r in irows {
    if r.len() == 3 {
      if let SqlValue::Text(sku) = r[0] {
        if let SqlValue::Int(q) = r[1] {
          if let SqlValue::Text(nm) = r[2] {
            items.push(Fin { deleted: false, name: sku + " " + q.to_str() + " " + nm, qty: 0 });
          }
        }
      }
    }
  }
  items.sort_by_key(|f| f.name);
  for it in items { lines.push(it.name); }
  Ok(lines.join("\n"))
}

