    stmts.push("INSERT OR REPLACE INTO sync_state (k, v) VALUES ('cursor', ?)");
    params.push([SqlValue::Text(new_cursor)]);
    db.transaction(stmts, params).map_err(dberr)?;
    pages += 1;
    applied += pa;
    stale += ps;
    invalid += pi;
    if next.is_none() {
      status_line = "complete";
      break;
    }
    cursor = new_cursor;
  }

  let mut lines: List<Str> = [];
  lines.push("pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str());
  lines.push(status_line);
  for l in list_items(db)? {
    lines.push(l);
  }
  Ok(lines.join("\n"))
}

struct Page { changes: List<Json>, next: Option<Str> }

struct Change { upsert: Bool, sku: Str, name: Str, qty: Int, version: Int }

fn dbe(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(m) => "db invalid: " + m,
    DbErr::Denied => "db denied",
    DbErr::Busy => "db busy",
    DbErr::TooLarge => "db too large",
    DbErr::Constraint(m) => "db constraint: " + m,
  }
}

fn setup(db: Db) -> Result<(), Str> {
  db.exec("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL)", []).map_err(dbe)?;
  db.exec("CREATE TABLE IF NOT EXISTS versions (sku TEXT PRIMARY KEY, version INTEGER NOT NULL)", []).map_err(dbe)?;
  db.exec("CREATE TABLE IF NOT EXISTS state (k TEXT PRIMARY KEY, v TEXT NOT NULL)", []).map_err(dbe)?;
  Ok(())
}

fn get_cursor(db: Db) -> Result<Str, Str> {
  let rows = db.query("SELECT v FROM state WHERE k = 'cursor'", []).map_err(dbe)?;
  if rows.len() == 0 { return Ok("0"); }
  match rows[0][0] {
    SqlValue::Text(t) => Ok(t),
    _ => Ok("0"),
  }
}

fn db_version(db: Db, sku: Str) -> Result<Option<Int>, Str> {
  let rows = db.query("SELECT version FROM versions WHERE sku = ?", [SqlValue::Text(sku)]).map_err(dbe)?;
  if rows.len() == 0 { return Ok(None); }
  match rows[0][0] {
    SqlValue::Int(v) => Ok(Some(v)),
    _ => Ok(None),
  }
}

fn parse_page(s: Str) -> Option<Page> {
  let j = s.parse_json().ok()?;
  let m = j.as_map()?;
  let changes = m.get("changes")?.as_list()?;
  let next = match m.get("next") {
    None => None,
    Some(Json::Null) => None,
    Some(Json::Str(x)) => Some(x),
    Some(_) => return None,
  };
  Some(Page { changes: changes, next: next })
}

fn parse_change(c: Json) -> Option<Change> {
  let op = c.get("op")?.as_str()?;
  let sku = c.get("sku")?.as_str()?;
  let version = c.get("version")?.as_int()?;
  if op == "upsert" {
    let name = c.get("name")?.as_str()?;
    let qty = c.get("qty")?.as_int()?;
    Some(Change { upsert: true, sku: sku, name: name, qty: qty, version: version })
  } else if op == "delete" {
    Some(Change { upsert: false, sku: sku, name: "", qty: 0, version: version })
  } else {
    None
  }
}

fn encode(s: Str) -> Str {
  let mut out = "";
  for b in s.to_bytes() {
    let unreserved = (b >= 65 && b <= 90) || (b >= 97 && b <= 122) || (b >= 48 && b <= 57)
      || b == 45 || b == 95 || b == 46 || b == 126;
    let mut one = "".to_bytes();
    one.push(b);
    if unreserved {
      out = out + one.to_str();
    } else {
      out = out + "%" + one.to_hex().to_uppercase();
    }
  }
  out
}

fn main(api: Http, db: Db) -> Result<Str, Str> {
  setup(db)?;
  let mut cursor = get_cursor(db)?;
  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut status_line = "";
  loop {
    let r = api.send("GET", "/changes?cursor=" + encode(cursor), [], "".to_bytes(), 0);
    let resp = match r {
      Ok(x) => x,
      Err(_) => {
        status_line = "stopped at " + cursor + " (no response)";
        break;
      }
    };
    if resp.status != 200 {
      status_line = "stopped at " + cursor + " (status " + resp.status.to_str() + ")";
      break;
    }
    let Some(page) = parse_page(resp.body.to_str()) else {
      status_line = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let mut stmts: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    let mut seen: HashMap<Str, Int> = HashMap::new();
    let mut a = 0;
    let mut s = 0;
    let mut i = 0;
    for c in page.changes {
      let Some(ch) = parse_change(c) else { i += 1; continue; };
      let prev = match seen.get(ch.sku) {
        Some(v) => Some(v),
        None => db_version(db, ch.sku)?,
      };
      if let Some(p) = prev {
        if ch.version <= p { s += 1; continue; }
      }
      seen.insert(ch.sku, ch.version);
      if ch.upsert {
        stmts.push("INSERT OR REPLACE INTO items (sku, name, qty) VALUES (?, ?, ?)");
        params.push([SqlValue::Text(ch.sku), SqlValue::Text(ch.name), SqlValue::Int(ch.qty)]);
      } else {
        stmts.push("DELETE FROM items WHERE sku = ?");
        params.push([SqlValue::Text(ch.sku)]);
      }
      stmts.push("INSERT OR REPLACE INTO versions (sku, version) VALUES (?, ?)");
      params.push([SqlValue::Text(ch.sku), SqlValue::Int(ch.version)]);
      a += 1;
    }
    let newc = match page.next {
      Some(n) => n,
      None => cursor,
    };
    stmts.push("INSERT OR REPLACE INTO state (k, v) VALUES ('cursor', ?)");
    params.push([SqlValue::Text(newc)]);
    db.transaction(stmts, params).map_err(dbe)?;
    pages += 1;
    applied += a;
    stale += s;
    invalid += i;
    match page.next {
      Some(n) => cursor = n,
      None => {
        status_line = "complete";
        break;
      }
    }
  }
  let mut out = "pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str()
    + " invalid " + invalid.to_str() + "\n" + status_line + "\n";
  let rows = db.query("SELECT sku, qty, name FROM items ORDER BY sku", []).map_err(dbe)?;
  for row in rows {
    let sku = match row[0] { SqlValue::Text(t) => t, _ => "" };
    let qty = match row[1] { SqlValue::Int(q) => q.to_str(), _ => "" };
    let name = match row[2] { SqlValue::Text(t) => t, _ => "" };
    out = out + sku + " " + qty + " " + name + "\n";
  }
  Ok(out)
}

struct Page { changes: List<Json>, next: Option<Str> }

enum Op { Upsert(Str, Str, Int, Int), Delete(Str, Int), Invalid }

struct Item { sku: Str, qty: Int, name: Str }

fn setup(db: Db) -> Result<(), Str> {
  db.exec("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL)", []).map_err(|e| "db error creating items")?;
  db.exec("CREATE TABLE IF NOT EXISTS versions (sku TEXT PRIMARY KEY, version INTEGER NOT NULL)", []).map_err(|e| "db error creating versions")?;
  db.exec("CREATE TABLE IF NOT EXISTS state (k TEXT PRIMARY KEY, v TEXT NOT NULL)", []).map_err(|e| "db error creating state")?;
  Ok(())
}

fn load_cursor(db: Db) -> Result<Str, Str> {
  let rows = db.query("SELECT v FROM state WHERE k = 'cursor'", []).map_err(|e| "db error reading cursor")?;
  if rows.len() == 0 { return Ok("0"); }
  match rows[0][0] {
    SqlValue::Text(s) => Ok(s),
    _ => Ok("0"),
  }
}

fn db_version(db: Db, sku: Str) -> Result<Option<Int>, Str> {
  let rows = db.query("SELECT version FROM versions WHERE sku = ?", [SqlValue::Text(sku)]).map_err(|e| "db error reading version")?;
  if rows.len() == 0 { return Ok(None); }
  match rows[0][0] {
    SqlValue::Int(v) => Ok(Some(v)),
    _ => Ok(None),
  }
}

fn in_range(b: Bytes, i: Int, lo: Int, hi: Int) -> Bool {
  i < b.len() && b[i] >= lo && b[i] <= hi
}

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 {
      i += 1;
    } else if c >= 194 && c <= 223 {
      if !in_range(b, i + 1, 128, 191) { return false; }
      i += 2;
    } else if c >= 224 && c <= 239 {
      let mut lo = 128;
      let mut hi = 191;
      if c == 224 { lo = 160; }
      if c == 237 { hi = 159; }
      if !in_range(b, i + 1, lo, hi) { return false; }
      if !in_range(b, i + 2, 128, 191) { return false; }
      i += 3;
    } else if c >= 240 && c <= 244 {
      let mut lo = 128;
      let mut hi = 191;
      if c == 240 { lo = 144; }
      if c == 244 { hi = 143; }
      if !in_range(b, i + 1, lo, hi) { return false; }
      if !in_range(b, i + 2, 128, 191) { return false; }
      if !in_range(b, i + 3, 128, 191) { return false; }
      i += 4;
    } else {
      return false;
    }
  }
  true
}

fn enc(s: Str) -> Str {
  let mut out = "";
  let b = s.to_bytes();
  for c in b {
    let unreserved = (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122)
      || c == 45 || c == 46 || c == 95 || c == 126;
    if unreserved {
      let mut one = "".to_bytes();
      one.push(c);
      out = out + one.to_str();
    } else {
      let mut one = "".to_bytes();
      one.push(c);
      out = out + "%" + one.to_hex().to_uppercase();
    }
  }
  out
}

fn parse_page(body: Bytes) -> Option<Page> {
  if !valid_utf8(body) { return None; }
  let doc = body.to_str().parse_json().ok()?;
  let Json::Obj(m) = doc else { return None; };
  let Some(Json::Arr(changes)) = m.get("changes") else { return None; };
  let next = match m.get("next") {
    Some(Json::Str(s)) => Some(s),
    _ => None,
  };
  Some(Page { changes: changes, next: next })
}

fn classify(j: Json) -> Op {
  let Json::Obj(m) = j else { return Op::Invalid; };
  let Some(Json::Str(op)) = m.get("op") else { return Op::Invalid; };
  let Some(Json::Str(sku)) = m.get("sku") else { return Op::Invalid; };
  let Some(Json::Num(version)) = m.get("version") else { return Op::Invalid; };
  if op == "upsert" {
    let Some(Json::Str(name)) = m.get("name") else { return Op::Invalid; };
    let Some(Json::Num(qty)) = m.get("qty") else { return Op::Invalid; };
    Op::Upsert(sku, name, qty, version)
  } else if op == "delete" {
    Op::Delete(sku, version)
  } else {
    Op::Invalid
  }
}

fn list_items(db: Db) -> Result<List<Item>, Str> {
  let rows = db.query("SELECT sku, qty, name FROM items", []).map_err(|e| "db error reading items")?;
  let mut items: List<Item> = [];
  for row in rows {
    let SqlValue::Text(sku) = row[0] else { continue; };
    let SqlValue::Int(qty) = row[1] else { continue; };
    let SqlValue::Text(name) = row[2] else { continue; };
    items.push(Item { sku: sku, qty: qty, name: name });
  }
  items.sort_by_key(|it| it.sku);
  Ok(items)
}

fn main(api: Http, db: Db) -> Result<Str, Str> {
  setup(db)?;
  let mut cursor = load_cursor(db)?;
  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut tail = "";
  loop {
    let path = "/changes?cursor=" + enc(cursor);
    let r = match api.send("GET", path, [], "".to_bytes(), 0) {
      Ok(r) => r,
      Err(_) => {
        tail = "stopped at " + cursor + " (no response)";
        break;
      }
    };
    if r.status != 200 {
      tail = "stopped at " + cursor + " (status " + r.status.to_str() + ")";
      break;
    }
    let Some(page) = parse_page(r.body) else {
      tail = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let mut cache: HashMap<Str, Int> = HashMap::new();
    let mut stmts: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    let mut a = 0;
    let mut s = 0;
    let mut inv = 0;
    for c in page.changes {
      let op = classify(c);
      let mut sku = "";
      let mut version = 0;
      match op {
        Op::Invalid => { inv += 1; continue; }
        Op::Upsert(k, _, _, v) => { sku = k; version = v; }
        Op::Delete(k, v) => { sku = k; version = v; }
      }
      let last = match cache.get(sku) {
        Some(v) => Some(v),
        None => db_version(db, sku)?,
      };
      if let Some(l) = last {
        if version <= l { s += 1; continue; }
      }
      match op {
        Op::Upsert(k, name, qty, v) => {
          stmts.push("INSERT INTO items (sku, name, qty) VALUES (?, ?, ?) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty");
          params.push([SqlValue::Text(k), SqlValue::Text(name), SqlValue::Int(qty)]);
        }
        Op::Delete(k, _) => {
          stmts.push("DELETE FROM items WHERE sku = ?");
          params.push([SqlValue::Text(k)]);
        }
        Op::Invalid => {}
      }
      stmts.push("INSERT INTO versions (sku, version) VALUES (?, ?) ON CONFLICT(sku) DO UPDATE SET version = excluded.version");
      params.push([SqlValue::Text(sku), SqlValue::Int(version)]);
      cache.insert(sku, version);
      a += 1;
    }
    let new_cursor = match page.next {
      Some(n) => n,
      None => cursor,
    };
    stmts.push("INSERT INTO state (k, v) VALUES ('cursor', ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v");
    params.push([SqlValue::Text(new_cursor)]);
    db.transaction(stmts, params).map_err(|e| "db error applying page " + cursor)?;
    pages += 1;
    applied += a;
    stale += s;
    invalid += inv;
    match page.next {
      Some(n) => { cursor = n; }
      None => {
        tail = "complete";
        break;
      }
    }
  }
  let mut out = "pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str()
    + " invalid " + invalid.to_str() + "\n" + tail + "\n";
  let items = list_items(db)?;
  for it in items {
    out = out + it.sku + " " + it.qty.to_str() + " " + it.name + "\n";
  }
  Ok(out)
}

struct Job { id: Str, priority: Int, due: Int, attempts: Int, state: Str }

fn get_int(o: Json, k: Str) -> Int {
  o.get(k).and_then(|j| j.as_int()).unwrap_or(0)
}

fn load(queue: Kv) -> Result<Map<Str, Job>, Str> {
  let mut jobs: Map<Str, Job> = Map::new();
  let v = queue.get("jobs").map_err(|_e| "kv error")?;
  let Some(b) = v else { return Ok(jobs); };
  let doc = b.to_str().parse_json()?;
  let m: Map<Str, Json> = doc.as_map().unwrap_or(Map::new());
  for k in m.keys() {
    let Some(o) = m.get(k) else { continue; };
    let st = o.get("state").and_then(|j| j.as_str()).unwrap_or("pending");
    jobs.insert(k, Job {
      id: k,
      priority: get_int(o, "priority"),
      due: get_int(o, "due"),
      attempts: get_int(o, "attempts"),
      state: st,
    });
  }
  Ok(jobs)
}

fn save(queue: Kv, jobs: Map<Str, Job>) -> Result<(), Str> {
  let mut m: Map<Str, Json> = Map::new();
  for k in jobs.keys() {
    let Some(j) = jobs.get(k) else { continue; };
    let mut o: Map<Str, Json> = Map::new();
    o.insert("priority", Json::Num(j.priority));
    o.insert("due", Json::Num(j.due));
    o.insert("attempts", Json::Num(j.attempts));
    o.insert("state", Json::Str(j.state));
    m.insert(k, Json::Obj(o));
  }
  queue.set("jobs", Json::Obj(m).to_json().to_bytes()).map_err(|_e| "kv error")
}

fn parse_job(line: Str) -> Option<Job> {
  let doc = line.parse_json().ok()?;
  let _m = doc.as_map()?;
  let id = doc.get("id")?.as_str()?;
  let p = match doc.get("priority")? {
    Json::Num(n) => n,
    _ => return None,
  };
  Some(Job { id: id, priority: p, due: 0, attempts: 0, state: "pending" })
}

fn outcome(script: Json, id: Str, idx: Int) -> Str {
  let list: List<Json> = script.get(id).and_then(|j| j.as_list()).unwrap_or([]);
  if list.len() == 0 { return "ok"; }
  let i = if idx < list.len() { idx } else { list.len() - 1 };
  list[i].as_str().unwrap_or("ok")
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
  let now = clock.now_ms();
  let mut jobs = load(queue)?;
  let mut out: List<Str> = [];

  let text = match input.read("enqueue.jsonl") {
    Ok(b) => b.to_str(),
    Err(_) => "",
  };
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    if line.trim().len() == 0 { continue; }
    match parse_job(line.trim()) {
      Some(j) => {
        if jobs.get(j.id).is_some() {
          out.push("duplicate " + j.id);
        } else {
          jobs.insert(j.id, Job { due: now, ..j });
        }
      }
      None => out.push("invalid line " + n.to_str()),
    }
  }

  let script = match input.read("script.json") {
    Ok(b) => b.to_str().parse_json().unwrap_or(Json::Null),
    Err(_) => Json::Null,
  };

  let mut due: List<Job> = [];
  for k in jobs.keys() {
    let Some(j) = jobs.get(k) else { continue; };
    if j.state == "pending" && j.due <= now { due.push(j); }
  }
  due.sort_by(|a, b| {
    if a.priority != b.priority { a.priority > b.priority }
    else if a.due != b.due { a.due < b.due }
    else { a.id < b.id }
  });
  let mut ran = 0;
  for j in due {
    if ran >= 5 { break; }
    ran += 1;
    let res = outcome(script, j.id, j.attempts);
    let attempts = j.attempts + 1;
    if res == "ok" {
      jobs.insert(j.id, Job { attempts: attempts, state: "done", ..j });
      out.push("done " + j.id);
    } else if attempts >= 4 {
      jobs.insert(j.id, Job { attempts: attempts, state: "dead", ..j });
      out.push("dead " + j.id);
    } else {
      let mut s = 60;
      let mut i = 1;
      while i < attempts { s = s * 2; i += 1; }
      jobs.insert(j.id, Job { attempts: attempts, due: now + s * 1000, ..j });
      out.push("retry " + j.id + " in " + s.to_str());
    }
  }

  save(queue, jobs)?;

  let mut p = 0;
  let mut d = 0;
  let mut x = 0;
  for k in jobs.keys() {
    let Some(j) = jobs.get(k) else { continue; };
    if j.state == "done" { d += 1; } else if j.state == "dead" { x += 1; } else { p += 1; }
  }
  out.push("pending " + p.to_str() + " done " + d.to_str() + " dead " + x.to_str());
  Ok(out.join("\n"))
}

struct Tok { kind: Int, text: Str }

enum Expr {
  Num(Str),
  Var(Str),
  Neg(List<Expr>),
  Bin(Str, List<Expr>),
  Call(Str, List<Expr>),
}

struct R { e: Expr, p: Int }

const MAXI: Int = 9223372036854775807;

fn min_int() -> Int { -9223372036854775807 - 1 }

fn is_digit(c: Str) -> Bool { c >= "0" && c <= "9" && c.len() == 1 }

fn is_alpha(c: Str) -> Bool {
  c.len() == 1 && ((c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || c == "_")
}

fn tokenize(s: Str) -> Option<List<Tok>> {
  let cs = s.chars();
  let n = cs.len();
  let mut i = 0;
  let mut out: List<Tok> = [];
  while i < n {
    let c = cs[i];
    if c == " " || c == "\r" { i += 1; continue; }
    if is_digit(c) {
      let mut t = "";
      while i < n && is_digit(cs[i]) { t = t + cs[i]; i += 1; }
      out.push(Tok { kind: 0, text: t });
      continue;
    }
    if is_alpha(c) {
      let mut t = "";
      while i < n && (is_alpha(cs[i]) || is_digit(cs[i])) { t = t + cs[i]; i += 1; }
      out.push(Tok { kind: 1, text: t });
      continue;
    }
    if c.len() == 1 && "+-*/%^(),=".contains(c) {
      out.push(Tok { kind: 2, text: c });
      i += 1;
      continue;
    }
    return None;
  }
  Some(out)
}

fn is_op(t: List<Tok>, p: Int, s: Str) -> Bool {
  p < t.len() && t[p].kind == 2 && t[p].text == s
}

fn expr(t: List<Tok>, p: Int) -> Option<R> {
  let mut r = term(t, p)?;
  loop {
    if is_op(t, r.p, "+") || is_op(t, r.p, "-") {
      let op = t[r.p].text;
      let b = term(t, r.p + 1)?;
      r = R { e: Expr::Bin(op, [r.e, b.e]), p: b.p };
    } else {
      break;
    }
  }
  Some(r)
}

fn term(t: List<Tok>, p: Int) -> Option<R> {
  let mut r = factor(t, p)?;
  loop {
    if is_op(t, r.p, "*") || is_op(t, r.p, "/") || is_op(t, r.p, "%") {
      let op = t[r.p].text;
      let b = factor(t, r.p + 1)?;
      r = R { e: Expr::Bin(op, [r.e, b.e]), p: b.p };
    } else {
      break;
    }
  }
  Some(r)
}

fn factor(t: List<Tok>, p: Int) -> Option<R> {
  if is_op(t, p, "-") {
    let f = factor(t, p + 1)?;
    return Some(R { e: Expr::Neg([f.e]), p: f.p });
  }
  power(t, p)
}

fn power(t: List<Tok>, p: Int) -> Option<R> {
  let a = atom(t, p)?;
  if is_op(t, a.p, "^") {
    let f = factor(t, a.p + 1)?;
    return Some(R { e: Expr::Bin("^", [a.e, f.e]), p: f.p });
  }
  Some(a)
}

fn atom(t: List<Tok>, p: Int) -> Option<R> {
  if p >= t.len() { return None; }
  let k = t[p];
  if k.kind == 0 {
    return Some(R { e: Expr::Num(k.text), p: p + 1 });
  }
  if k.kind == 1 {
    if is_op(t, p + 1, "(") {
      let mut args: List<Expr> = [];
      let a = expr(t, p + 2)?;
      args.push(a.e);
      let mut q = a.p;
      while is_op(t, q, ",") {
        let b = expr(t, q + 1)?;
        args.push(b.e);
        q = b.p;
      }
      if !is_op(t, q, ")") { return None; }
      return Some(R { e: Expr::Call(k.text, args), p: q + 1 });
    }
    return Some(R { e: Expr::Var(k.text), p: p + 1 });
  }
  if is_op(t, p, "(") {
    let r = expr(t, p + 1)?;
    if !is_op(t, r.p, ")") { return None; }
    return Some(R { e: r.e, p: r.p + 1 });
  }
  None
}

fn add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a > MAXI - b { return Err("overflow"); }
  if b < 0 && a < min_int() - b { return Err("overflow"); }
  Ok(a + b)
}

fn sub(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 && a > MAXI + b { return Err("overflow"); }
  if b > 0 && a < min_int() + b { return Err("overflow"); }
  Ok(a - b)
}

fn mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  let mn = min_int();
  if a > 0 {
    if b > 0 {
      if a > MAXI / b { return Err("overflow"); }
    } else {
      if b < mn / a { return Err("overflow"); }
    }
  } else {
    if b > 0 {
      if a < mn / b { return Err("overflow"); }
    } else {
      if a < MAXI / b { return Err("overflow"); }
    }
  }
  Ok(a * b)
}

fn pow(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  if b == 0 { return Ok(1); }
  if a == 0 { return Ok(0); }
  if a == 1 { return Ok(1); }
  if a == -1 { if b % 2 == 0 { return Ok(1); } else { return Ok(-1); } }
  if b > 64 { return Err("overflow"); }
  let mut r = 1;
  for _i in 0..b { r = mul(r, a)?; }
  Ok(r)
}

fn binop(op: Str, a: Int, b: Int) -> Result<Int, Str> {
  match op {
    "+" => add(a, b),
    "-" => sub(a, b),
    "*" => mul(a, b),
    "/" => {
      if b == 0 { Err("division by zero") }
      else if a == min_int() && b == -1 { Err("overflow") }
      else { Ok(a / b) }
    }
    "%" => {
      if b == 0 { Err("division by zero") }
      else if b == -1 { Ok(0) }
      else { Ok(a % b) }
    }
    _ => pow(a, b),
  }
}

fn eval(e: Expr, env: HashMap<Str, Int>) -> Result<Int, Str> {
  match e {
    Expr::Num(s) => match s.parse_int() {
      Some(v) => Ok(v),
      None => Err("overflow"),
    },
    Expr::Var(n) => match env.get(n) {
      Some(v) => Ok(v),
      None => Err("unknown variable " + n),
    },
    Expr::Neg(xs) => {
      let v = eval(xs[0], env)?;
      if v == min_int() { Err("overflow") } else { Ok(-v) }
    }
    Expr::Bin(op, xs) => {
      let a = eval(xs[0], env)?;
      let b = eval(xs[1], env)?;
      binop(op, a, b)
    }
    Expr::Call(name, xs) => {
      let mut want = 0;
      if name == "min" || name == "max" { want = 2; }
      else if name == "abs" { want = 1; }
      else { return Err("unknown function " + name); }
      if xs.len() != want { return Err("wrong number of arguments to " + name); }
      let mut vals: List<Int> = [];
      for x in xs { vals.push(eval(x, env)?); }
      if name == "min" { Ok(vals[0].min(vals[1])) }
      else if name == "max" { Ok(vals[0].max(vals[1])) }
      else {
        let v = vals[0];
        if v == min_int() { Err("overflow") } else if v < 0 { Ok(-v) } else { Ok(v) }
      }
    }
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut env: HashMap<Str, Int> = HashMap::new();
  let mut out: List<Str> = [];
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    if line.trim().len() == 0 { continue; }
    let pre = n.to_str() + ": ";
    let Some(toks) = tokenize(line) else {
      out.push(pre + "error: syntax error");
      continue;
    };
    let len = toks.len();
    if len > 0 && toks[0].kind == 1 && toks[0].text == "let" {
      let mut ok = len >= 4 && toks[1].kind == 1 && is_op(toks, 2, "=");
      let mut ex: Option<Expr> = None;
      if ok {
        match expr(toks, 3) {
          Some(r) => { if r.p == len { ex = Some(r.e); } else { ok = false; } }
          None => ok = false,
        }
      }
      let Some(e) = ex else {
        out.push(pre + "error: syntax error");
        continue;
      };
      if !ok { out.push(pre + "error: syntax error"); continue; }
      let name = toks[1].text;
      match eval(e, env) {
        Ok(v) => {
          env.insert(name, v);
          out.push(pre + name + " = " + v.to_str());
        }
        Err(m) => out.push(pre + "error: " + m),
      }
    } else {
      let mut ex: Option<Expr> = None;
      if let Some(r) = expr(toks, 0) {
        if r.p == len { ex = Some(r.e); }
      }
      let Some(e) = ex else {
        out.push(pre + "error: syntax error");
        continue;
      };
      match eval(e, env) {
        Ok(v) => out.push(pre + v.to_str()),
        Err(m) => out.push(pre + "error: " + m),
      }
    }
  }
  Ok(out.join("\n"))
}

struct Tok { kind: Str, text: Str }

enum Expr { Num(Str), Var(Str), Neg(List<Expr>), Bin(Str, List<Expr>), Call(Str, List<Expr>) }

struct P { e: Expr, pos: Int }

const MAXI: Int = 9223372036854775807;
const MINI: Int = -9223372036854775808;

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }
fn is_alpha(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }

fn lex(s: Str) -> Option<List<Tok>> {
  let b = s.to_bytes();
  let n = b.len();
  let mut i = 0;
  let mut out: List<Tok> = [];
  while i < n {
    let c = b[i];
    if c == 32 || c == 9 || c == 13 { i += 1; continue; }
    if is_digit(c) {
      let st = i;
      while i < n && is_digit(b[i]) { i += 1; }
      out.push(Tok { kind: "int", text: s.slice(st, i) });
      continue;
    }
    if is_alpha(c) {
      let st = i;
      while i < n && (is_alpha(b[i]) || is_digit(b[i])) { i += 1; }
      out.push(Tok { kind: "name", text: s.slice(st, i) });
      continue;
    }
    if c < 128 {
      let ch = s.slice(i, i + 1);
      if "+-*/%^(),=".contains(ch) {
        out.push(Tok { kind: ch, text: ch });
        i += 1;
        continue;
      }
    }
    return None;
  }
  Some(out)
}

fn at(t: List<Tok>, i: Int) -> Str {
  if i < t.len() { t[i].kind } else { "" }
}

fn p_expr(t: List<Tok>, pos: Int) -> Option<P> {
  let first = p_term(t, pos)?;
  let mut e = first.e;
  let mut p = first.pos;
  loop {
    let k = at(t, p);
    if k == "+" || k == "-" {
      let r = p_term(t, p + 1)?;
      e = Expr::Bin(k, [e, r.e]);
      p = r.pos;
    } else {
      break;
    }
  }
  Some(P { e: e, pos: p })
}

fn p_term(t: List<Tok>, pos: Int) -> Option<P> {
  let first = p_factor(t, pos)?;
  let mut e = first.e;
  let mut p = first.pos;
  loop {
    let k = at(t, p);
    if k == "*" || k == "/" || k == "%" {
      let r = p_factor(t, p + 1)?;
      e = Expr::Bin(k, [e, r.e]);
      p = r.pos;
    } else {
      break;
    }
  }
  Some(P { e: e, pos: p })
}

fn p_factor(t: List<Tok>, pos: Int) -> Option<P> {
  if at(t, pos) == "-" {
    let r = p_factor(t, pos + 1)?;
    return Some(P { e: Expr::Neg([r.e]), pos: r.pos });
  }
  p_power(t, pos)
}

fn p_power(t: List<Tok>, pos: Int) -> Option<P> {
  let a = p_atom(t, pos)?;
  if at(t, a.pos) == "^" {
    let r = p_factor(t, a.pos + 1)?;
    return Some(P { e: Expr::Bin("^", [a.e, r.e]), pos: r.pos });
  }
  Some(a)
}

fn p_atom(t: List<Tok>, pos: Int) -> Option<P> {
  let k = at(t, pos);
  if k == "int" {
    return Some(P { e: Expr::Num(t[pos].text), pos: pos + 1 });
  }
  if k == "name" {
    let name = t[pos].text;
    if at(t, pos + 1) == "(" {
      let mut args: List<Expr> = [];
      let a = p_expr(t, pos + 2)?;
      args.push(a.e);
      let mut p = a.pos;
      while at(t, p) == "," {
        let b = p_expr(t, p + 1)?;
        args.push(b.e);
        p = b.pos;
      }
      if at(t, p) != ")" { return None; }
      return Some(P { e: Expr::Call(name, args), pos: p + 1 });
    }
    return Some(P { e: Expr::Var(name), pos: pos + 1 });
  }
  if k == "(" {
    let r = p_expr(t, pos + 1)?;
    if at(t, r.pos) != ")" { return None; }
    return Some(P { e: r.e, pos: r.pos + 1 });
  }
  None
}

fn add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a > MAXI - b { return Err("overflow"); }
  if b < 0 && a < MINI - b { return Err("overflow"); }
  Ok(a + b)
}

fn sub(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a < MINI + b { return Err("overflow"); }
  if b < 0 && a > MAXI + b { return Err("overflow"); }
  Ok(a - b)
}

fn neg(a: Int) -> Result<Int, Str> {
  if a == MINI { Err("overflow") } else { Ok(0 - a) }
}

fn mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if a == -1 { return neg(b); }
  if b == -1 { return neg(a); }
  if a > 0 {
    if b > 0 { if a > MAXI / b { return Err("overflow"); } }
    else { if b < MINI / a { return Err("overflow"); } }
  } else {
    if b > 0 { if a < MINI / b { return Err("overflow"); } }
    else { if a < MAXI / b { return Err("overflow"); } }
  }
  Ok(a * b)
}

fn pow(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  if b == 0 { return Ok(1); }
  if a == 0 { return Ok(0); }
  if a == 1 { return Ok(1); }
  if a == -1 { if b % 2 == 0 { return Ok(1); } else { return Ok(-1); } }
  let mut r = 1;
  let mut i = 0;
  while i < b {
    r = mul(r, a)?;
    i += 1;
  }
  Ok(r)
}

fn ev(e: Expr, env: Map<Str, Int>) -> Result<Int, Str> {
  match e {
    Expr::Num(s) => match s.parse_int() {
      Some(v) => Ok(v),
      None => Err("overflow"),
    },
    Expr::Var(n) => match env.get(n) {
      Some(v) => Ok(v),
      None => Err("unknown variable " + n),
    },
    Expr::Neg(xs) => {
      let a = ev(xs[0], env)?;
      neg(a)
    }
    Expr::Bin(op, xs) => {
      let a = ev(xs[0], env)?;
      let b = ev(xs[1], env)?;
      if op == "+" { add(a, b) }
      else if op == "-" { sub(a, b) }
      else if op == "*" { mul(a, b) }
      else if op == "/" {
        if b == 0 { Err("division by zero") }
        else if a == MINI && b == -1 { Err("overflow") }
        else { Ok(a / b) }
      }
      else if op == "%" {
        if b == 0 { Err("division by zero") }
        else if b == -1 { Ok(0) }
        else { Ok(a % b) }
      }
      else { pow(a, b) }
    }
    Expr::Call(name, args) => {
      let want = if name == "min" || name == "max" { 2 } else if name == "abs" { 1 } else { 0 };
      if want == 0 { return Err("unknown function " + name); }
      if args.len() != want { return Err("wrong number of arguments to " + name); }
      let mut vals: List<Int> = [];
      for a in args { vals.push(ev(a, env)?); }
      if name == "min" { Ok(vals[0].min(vals[1])) }
      else if name == "max" { Ok(vals[0].max(vals[1])) }
      else { neg_abs(vals[0]) }
    }
  }
}

fn neg_abs(a: Int) -> Result<Int, Str> {
  if a < 0 { neg(a) } else { Ok(a) }
}

