fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut env: Map<Str, Int> = Map::new();
  let mut out: List<Str> = [];
  let mut ln = 0;
  for line in text.lines() {
    ln += 1;
    if line.trim().len() == 0 { continue; }
    let prefix = ln.to_str() + ": ";
    let Some(toks) = lex(line) else {
      out.push(prefix + "error: syntax error");
      continue;
    };
    let mut is_let = false;
    if toks.len() > 0 && toks[0].kind == "name" && toks[0].text == "let" { is_let = true; }
    if is_let {
      if at(toks, 1) != "name" || at(toks, 2) != "=" {
        out.push(prefix + "error: syntax error");
        continue;
      }
      let name = toks[1].text;
      let parsed = p_expr(toks, 3);
      let Some(p) = parsed else { out.push(prefix + "error: syntax error"); continue; };
      if p.pos != toks.len() { out.push(prefix + "error: syntax error"); continue; }
      match ev(p.e, env) {
        Ok(v) => {
          env.insert(name, v);
          out.push(prefix + name + " = " + v.to_str());
        }
        Err(m) => out.push(prefix + "error: " + m),
      }
    } else {
      let parsed = p_expr(toks, 0);
      let Some(p) = parsed else { out.push(prefix + "error: syntax error"); continue; };
      if p.pos != toks.len() { out.push(prefix + "error: syntax error"); continue; }
      match ev(p.e, env) {
        Ok(v) => out.push(prefix + v.to_str()),
        Err(m) => out.push(prefix + "error: " + m),
      }
    }
  }
  Ok(out.join("\n"))
}

const MAXI: Int = 9223372036854775807;

enum Tok { Num(Str), Name(Str), Op(Str) }

enum Expr {
  Lit(Str),
  Var(Str),
  Neg(List<Expr>),
  Bin(Str, List<Expr>),
  Call(Str, List<Expr>),
}

struct P { e: Expr, pos: Int }

fn imin() -> Int { -MAXI - 1 }

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }
fn is_alpha(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }

fn tokenize(s: Str) -> Option<List<Tok>> {
  let b = s.to_bytes();
  let n = b.len();
  let mut out: List<Tok> = [];
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c == 32 {
      i += 1;
    } else if is_digit(c) {
      let st = i;
      while i < n && is_digit(b[i]) { i += 1; }
      out.push(Tok::Num(s.slice(st, i)));
    } else if is_alpha(c) {
      let st = i;
      while i < n && (is_alpha(b[i]) || is_digit(b[i])) { i += 1; }
      out.push(Tok::Name(s.slice(st, i)));
    } else {
      let ops = "+-*/%^(),=";
      if c >= 128 { return None; }
      let ch = s.slice(i, i + 1);
      if !ops.contains(ch) { return None; }
      out.push(Tok::Op(ch));
      i += 1;
    }
  }
  Some(out)
}

fn is_op(t: List<Tok>, i: Int, s: Str) -> Bool {
  if i >= t.len() { return false; }
  match t[i] {
    Tok::Op(o) => o == s,
    _ => false,
  }
}

fn p_expr(t: List<Tok>, i: Int) -> Option<P> {
  let first = p_term(t, i)?;
  let mut e = first.e;
  let mut pos = first.pos;
  loop {
    let mut op = "";
    if is_op(t, pos, "+") { op = "+"; } else if is_op(t, pos, "-") { op = "-"; }
    if op == "" { break; }
    let r = p_term(t, pos + 1)?;
    e = Expr::Bin(op, [e, r.e]);
    pos = r.pos;
  }
  Some(P { e: e, pos: pos })
}

fn p_term(t: List<Tok>, i: Int) -> Option<P> {
  let first = p_factor(t, i)?;
  let mut e = first.e;
  let mut pos = first.pos;
  loop {
    let mut op = "";
    if is_op(t, pos, "*") { op = "*"; } else if is_op(t, pos, "/") { op = "/"; } else if is_op(t, pos, "%") { op = "%"; }
    if op == "" { break; }
    let r = p_factor(t, pos + 1)?;
    e = Expr::Bin(op, [e, r.e]);
    pos = r.pos;
  }
  Some(P { e: e, pos: pos })
}

fn p_factor(t: List<Tok>, i: Int) -> Option<P> {
  if is_op(t, i, "-") {
    let f = p_factor(t, i + 1)?;
    return Some(P { e: Expr::Neg([f.e]), pos: f.pos });
  }
  p_power(t, i)
}

fn p_power(t: List<Tok>, i: Int) -> Option<P> {
  let a = p_atom(t, i)?;
  if is_op(t, a.pos, "^") {
    let f = p_factor(t, a.pos + 1)?;
    return Some(P { e: Expr::Bin("^", [a.e, f.e]), pos: f.pos });
  }
  Some(a)
}

fn p_atom(t: List<Tok>, i: Int) -> Option<P> {
  if i >= t.len() { return None; }
  match t[i] {
    Tok::Num(s) => Some(P { e: Expr::Lit(s), pos: i + 1 }),
    Tok::Name(n) => {
      if is_op(t, i + 1, "(") {
        let mut args: List<Expr> = [];
        let a = p_expr(t, i + 2)?;
        args.push(a.e);
        let mut pos = a.pos;
        while is_op(t, pos, ",") {
          let b = p_expr(t, pos + 1)?;
          args.push(b.e);
          pos = b.pos;
        }
        if !is_op(t, pos, ")") { return None; }
        Some(P { e: Expr::Call(n, args), pos: pos + 1 })
      } else {
        Some(P { e: Expr::Var(n), pos: i + 1 })
      }
    }
    Tok::Op(o) => {
      if o != "(" { return None; }
      let a = p_expr(t, i + 1)?;
      if !is_op(t, a.pos, ")") { return None; }
      Some(P { e: a.e, pos: a.pos + 1 })
    }
  }
}

fn cadd(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a > MAXI - b { return Err("overflow"); }
  if b < 0 && a < imin() - b { return Err("overflow"); }
  Ok(a + b)
}

fn csub(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 && a > MAXI + b { return Err("overflow"); }
  if b > 0 && a < imin() + b { return Err("overflow"); }
  Ok(a - b)
}

fn cmul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  let bad = if a > 0 {
    if b > 0 { a > MAXI / b } else { b < imin() / a }
  } else {
    if b > 0 { a < imin() / b } else { a < MAXI / b }
  };
  if bad { Err("overflow") } else { Ok(a * b) }
}

fn cpow(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  if b == 0 { return Ok(1); }
  if a == 0 { return Ok(0); }
  if a == 1 { return Ok(1); }
  if a == -1 { if b % 2 == 0 { return Ok(1); } else { return Ok(-1); } }
  if b > 64 { return Err("overflow"); }
  let mut r = 1;
  for _i in 0..b { r = cmul(r, a)?; }
  Ok(r)
}

fn binop(op: Str, a: Int, b: Int) -> Result<Int, Str> {
  if op == "+" { return cadd(a, b); }
  if op == "-" { return csub(a, b); }
  if op == "*" { return cmul(a, b); }
  if op == "^" { return cpow(a, b); }
  if b == 0 { return Err("division by zero"); }
  if a == imin() && b == -1 {
    if op == "/" { return Err("overflow"); }
    return Ok(0);
  }
  if op == "/" { Ok(a / b) } else { Ok(a % b) }
}

fn eval(e: Expr, vars: HashMap<Str, Int>) -> Result<Int, Str> {
  match e {
    Expr::Lit(s) => s.parse_int().ok_or("overflow"),
    Expr::Var(n) => vars.get(n).ok_or("unknown variable " + n),
    Expr::Neg(xs) => {
      let a = eval(xs[0], vars)?;
      if a == imin() { Err("overflow") } else { Ok(-a) }
    }
    Expr::Bin(op, xs) => {
      let a = eval(xs[0], vars)?;
      let b = eval(xs[1], vars)?;
      binop(op, a, b)
    }
    Expr::Call(n, xs) => {
      let mut want = 0;
      if n == "min" || n == "max" { want = 2; } else if n == "abs" { want = 1; } else {
        return Err("unknown function " + n);
      }
      if xs.len() != want { return Err("wrong number of arguments to " + n); }
      let mut vals: List<Int> = [];
      for x in xs { vals.push(eval(x, vars)?); }
      if n == "min" { return Ok(vals[0].min(vals[1])); }
      if n == "max" { return Ok(vals[0].max(vals[1])); }
      if vals[0] == imin() { return Err("overflow"); }
      if vals[0] < 0 { Ok(-vals[0]) } else { Ok(vals[0]) }
    }
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut vars: HashMap<Str, Int> = HashMap::new();
  let mut out: List<Str> = [];
  let mut ln = 0;
  for line in text.lines() {
    ln += 1;
    if line.trim() == "" { continue; }
    let pre = ln.to_str() + ": ";
    let Some(toks) = tokenize(line) else { out.push(pre + "error: syntax error"); continue; };
    let mut is_let = false;
    if toks.len() > 0 {
      match toks[0] { Tok::Name(n) => { if n == "let" { is_let = true; } } _ => {} }
    }
    if is_let {
      let mut name = "";
      if toks.len() > 1 {
        match toks[1] { Tok::Name(n) => name = n, _ => {} }
      }
      let mut parsed: Option<Expr> = None;
      if name != "" && is_op(toks, 2, "=") {
        if let Some(p) = p_expr(toks, 3) {
          if p.pos == toks.len() { parsed = Some(p.e); }
        }
      }
      let Some(e) = parsed else { out.push(pre + "error: syntax error"); continue; };
      match eval(e, vars) {
        Ok(v) => {
          vars.insert(name, v);
          out.push(pre + name + " = " + v.to_str());
        }
        Err(m) => out.push(pre + "error: " + m),
      }
    } else {
      let mut parsed: Option<Expr> = None;
      if let Some(p) = p_expr(toks, 0) {
        if p.pos == toks.len() { parsed = Some(p.e); }
      }
      let Some(e) = parsed else { out.push(pre + "error: syntax error"); continue; };
      match eval(e, vars) {
        Ok(v) => out.push(pre + v.to_str()),
        Err(m) => out.push(pre + "error: " + m),
      }
    }
  }
  Ok(out.join("\n"))
}

struct Resp { status: Int, body: Json }

struct Event { id: Str, kind: Str, sub: Str, seq: Int }

struct Sub { state: Str, seq: Int, history: List<Str> }

fn obj1(k: Str, v: Str) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(k, Json::Str(v));
  Json::Obj(m)
}

fn reply(status: Int, k: Str, v: Str) -> Resp {
  Resp { status: status, body: obj1(k, v) }
}

fn not_found() -> Resp { reply(404, "error", "not found") }

fn dberr(e: DbErr) -> Str {
  match e {
    DbErr::Invalid(m) => "db invalid: " + m,
    DbErr::Denied => "db denied",
    DbErr::Busy => "db busy",
    DbErr::TooLarge => "db too large",
    DbErr::Constraint(m) => "db constraint: " + m,
  }
}

fn ioerr(e: IoErr) -> Str {
  match e {
    IoErr::NotFound => "secret not found",
    _ => "secret unreadable",
  }
}

fn logw(log: Log, s: Str) {
  match log.write(s) {
    Ok(_) => {}
    Err(_) => {}
  }
}

fn header(req: Incoming, name: Str) -> Option<Str> {
  let names = req.header_names();
  let vals = req.header_values();
  for i in 0..names.len() {
    if i < vals.len() && names[i] == name { return Some(vals[i]); }
  }
  None
}

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 { i += 1; continue; }
    let mut need = 0;
    let mut min = 0;
    let mut cp = 0;
    if c >= 194 && c <= 223 { need = 1; min = 128; cp = c - 192; }
    else if c >= 224 && c <= 239 { need = 2; min = 2048; cp = c - 224; }
    else if c >= 240 && c <= 244 { need = 3; min = 65536; cp = c - 240; }
    else { return false; }
    if i + need >= n { return false; }
    for k in 1..need + 1 {
      let d = b[i + k];
      if d < 128 || d > 191 { return false; }
      cp = cp * 64 + (d - 128);
    }
    if cp < min || cp > 1114111 || (cp >= 55296 && cp <= 57343) { return false; }
    i += need + 1;
  }
  true
}

fn parse_event(body: Bytes) -> Option<Event> {
  if !valid_utf8(body) { return None; }
  let j = body.to_str().parse_json().ok()?;
  let Json::Obj(m) = j else { return None; };
  let Some(Json::Str(id)) = m.get("id") else { return None; };
  let Some(Json::Str(kind)) = m.get("type") else { return None; };
  let Some(Json::Str(sub)) = m.get("subscription") else { return None; };
  let Some(Json::Num(seq)) = m.get("seq") else { return None; };
  if seq < 1 { return None; }
  if !(kind == "subscription.created" || kind == "subscription.activated"
       || kind == "payment.failed" || kind == "subscription.canceled") {
    return None;
  }
  Some(Event { id: id, kind: kind, sub: sub, seq: seq })
}

fn transition(state: Str, kind: Str) -> Option<Str> {
  match kind {
    "subscription.created" => if state == "none" { Some("created") } else { None },
    "subscription.activated" => if state == "created" || state == "past_due" { Some("active") } else { None },
    "payment.failed" => if state == "active" { Some("past_due") } else { None },
    "subscription.canceled" => if state == "created" || state == "active" || state == "past_due" { Some("canceled") } else { None },
    _ => None,
  }
}

fn ensure_schema(db: Db) -> Result<(), Str> {
  db.exec("CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, sub TEXT NOT NULL, seq INTEGER NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL)", []).map_err(dberr)?;
  db.exec("CREATE INDEX IF NOT EXISTS events_sub_seq ON events(sub, seq, status)", []).map_err(dberr)?;
  db.exec("CREATE TABLE IF NOT EXISTS subs (id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL, history TEXT NOT NULL)", []).map_err(dberr)?;
  Ok(())
}

fn load_sub(db: Db, id: Str) -> Result<Option<Sub>, Str> {
  let rows = db.query("SELECT state, seq, history FROM subs WHERE id = ?", [SqlValue::Text(id)]).map_err(dberr)?;
  if rows.len() == 0 { return Ok(None); }
  let r = rows[0];
  let SqlValue::Text(state) = r[0] else { return Err("bad state column"); };
  let SqlValue::Int(seq) = r[1] else { return Err("bad seq column"); };
  let SqlValue::Text(h) = r[2] else { return Err("bad history column"); };
  let mut history: List<Str> = [];
  if let Ok(Json::Arr(items)) = h.parse_json() {
    for it in items {
      if let Json::Str(s) = it { history.push(s); }
    }
  }
  Ok(Some(Sub { state: state, seq: seq, history: history }))
}

fn insert_event(db: Db, ev: Event, status: Str) -> Result<Bool, Str> {
  match db.exec("INSERT INTO events (id, sub, seq, kind, status) VALUES (?, ?, ?, ?, ?)",
                [SqlValue::Text(ev.id), SqlValue::Text(ev.sub), SqlValue::Int(ev.seq),
                 SqlValue::Text(ev.kind), SqlValue::Text(status)]) {
    Ok(_) => Ok(true),
    Err(DbErr::Constraint(_)) => Ok(false),
    Err(e) => Err(dberr(e)),
  }
}

fn strip_newline(b: Bytes) -> Bytes {
  let mut k = b;
  if k.len() > 0 && k[k.len() - 1] == 10 {
    k = k.slice(0, k.len() - 1);
    if k.len() > 0 && k[k.len() - 1] == 13 {
      k = k.slice(0, k.len() - 1);
    }
  }
  k
}

fn webhook(req: Incoming, db: Db, secrets: Dir, log: Log) -> Result<Resp, Str> {
  let key = strip_newline(secrets.read("webhook.key").map_err(ioerr)?);
  let body = req.body();
  let mut msg = key;
  msg.push(46);
  msg.extend(body);
  let expected = "sha256=" + msg.sha256().to_hex();
  let ok = match header(req, "x-signature") {
    Some(s) => s.ct_eq(expected),
    None => false,
  };
  if !ok {
    logw(log, "rejected signature");
    return Ok(reply(401, "error", "bad signature"));
  }
  let Some(ev) = parse_event(body) else { return Ok(reply(400, "error", "invalid event")); };

  let ex = db.query("SELECT status FROM events WHERE id = ?", [SqlValue::Text(ev.id)]).map_err(dberr)?;
  if ex.len() > 0 { return Ok(reply(200, "status", "duplicate")); }

  let cur = match load_sub(db, ev.sub)? {
    Some(s) => s,
    None => Sub { state: "none", seq: 0, history: [] },
  };

  if ev.seq <= cur.seq {
    if insert_event(db, ev, "stale")? {
      return Ok(reply(200, "status", "stale"));
    }
    return Ok(reply(200, "status", "duplicate"));
  }
  if ev.seq > cur.seq + 1 {
    if insert_event(db, ev, "queued")? {
      return Ok(reply(202, "status", "queued"));
    }
    return Ok(reply(200, "status", "duplicate"));
  }

  // ev.seq == cur.seq + 1: apply it and every queued follower
  let mut state = cur.state;
  let mut history = cur.history;
  let mut last = ev.seq;
  let mut count = 1;
  let mut invalid: List<Str> = [];
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];

  match transition(state, ev.kind) {
    Some(s) => { state = s; history.push(s); }
    None => { invalid.push(ev.id); }
  }
  stmts.push("INSERT INTO events (id, sub, seq, kind, status) VALUES (?, ?, ?, ?, 'applied')");
  params.push([SqlValue::Text(ev.id), SqlValue::Text(ev.sub), SqlValue::Int(ev.seq), SqlValue::Text(ev.kind)]);

  loop {
    let rows = db.query("SELECT id, kind FROM events WHERE sub = ? AND seq = ? AND status = 'queued' ORDER BY rowid LIMIT 1",
                        [SqlValue::Text(ev.sub), SqlValue::Int(last + 1)]).map_err(dberr)?;
    if rows.len() == 0 { break; }
    let SqlValue::Text(qid) = rows[0][0] else { return Err("bad id column"); };
    let SqlValue::Text(qkind) = rows[0][1] else { return Err("bad kind column"); };
    match transition(state, qkind) {
      Some(s) => { state = s; history.push(s); }
      None => { invalid.push(qid); }
    }
    stmts.push("UPDATE events SET status = 'applied' WHERE id = ?");
    params.push([SqlValue::Text(qid)]);
    last += 1;
    count += 1;
  }

  stmts.push("UPDATE events SET status = 'stale' WHERE sub = ? AND status = 'queued' AND seq <= ?");
  params.push([SqlValue::Text(ev.sub), SqlValue::Int(last)]);

  let hist_json = Json::Arr(history.map(|s| Json::Str(s))).to_json();
  stmts.push("INSERT INTO subs (id, state, seq, history) VALUES (?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET state = excluded.state, seq = excluded.seq, history = excluded.history");
  params.push([SqlValue::Text(ev.sub), SqlValue::Text(state), SqlValue::Int(last), SqlValue::Text(hist_json)]);

  match db.transaction(stmts, params) {
    Ok(_) => {}
    Err(DbErr::Constraint(_)) => { return Ok(reply(200, "status", "duplicate")); }
    Err(e) => { return Err(dberr(e)); }
  }

  for id in invalid {
    logw(log, "invalid transition " + id);
  }

  let mut m: Map<Str, Json> = Map::new();
  m.insert("status", Json::Str("applied"));
  m.insert("applied", Json::Num(count));
  Ok(Resp { status: 200, body: Json::Obj(m) })
}

fn get_sub(db: Db, id: Str) -> Result<Resp, Str> {
  let Some(s) = load_sub(db, id)? else { return Ok(not_found()); };
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str(id));
  m.insert("state", Json::Str(s.state));
  m.insert("seq", Json::Num(s.seq));
  m.insert("history", Json::Arr(s.history.map(|h| Json::Str(h))));
  Ok(Resp { status: 200, body: Json::Obj(m) })
}

fn handle(req: Incoming, db: Db, secrets: Dir, log: Log) -> Result<Resp, Str> {
  let method = req.method();
  let path = req.target().split("?")[0];
  if method == "POST" && path == "/webhooks" {
    ensure_schema(db)?;
    return webhook(req, db, secrets, log);
  }
  if method == "GET" {
    if let Some(id) = path.strip_prefix("/subscriptions/") {
      if id.len() > 0 && !id.contains("/") {
        ensure_schema(db)?;
        return get_sub(db, id);
      }
    }
  }
  Ok(not_found())
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, Str> {
  let r = match handle(req, db, secrets, log) {
    Ok(r) => r,
    Err(e) => {
      logw(log, "error " + e);
      reply(500, "error", "internal error")
    }
  };
  let body = r.body.to_json().to_bytes();
  match res.send(r.status, ["content-type"], ["application/json"], body) {
    Ok(_) => {}
    Err(_) => {}
  }
  Ok(r.status.to_str())
}
